INSERT INTO `badges` (`id`, `name`, `description`, `icon`, `xp_reward`, `created_at`) VALUES (6, 'Streak Scholar', 'Studied for 7 consecutive days.', 'local_fire_department', 90, '2026-06-05 22:22:41');
INSERT INTO `chapters` (`id`, `class_level`, `chapter_number`, `title`, `description`, `learning_objectives`, `key_points`, `important_laws`, `formulas`, `constants`, `important_reactions`, `notes`, `real_life_applications`, `virtual_labs`, `practice_questions`, `common_mistakes`, `difficulty`, `estimated_study_time`, `chapter_weightage`, `next_chapter`, `quiz_id`, `created_at`, `module_id`, `status`, `version`, `order_index`, `publish_at`, `course_id`, `reactions`, `experiment_content`, `updated_at`, `overview_content`, `key_points_content`, `formula_content`, `reaction_content`, `practice_content`) VALUES (1, '11', 1, 'Some Basic Concepts of Chemistry', 'This chapter introduces the fundamental principles of chemistry including laws of chemical combination, atomic and molecular masses, mole concept, stoichiometry, concentration terms, and calculations involving chemical equations.', '["Understand the nature of matter and its classification.", "Learn the laws of chemical combination.", "Apply the mole concept in numerical problems.", "Perform stoichiometric calculations.", "Calculate concentration using molarity and molality.", "Interpret balanced chemical equations."]', '["Matter is anything that occupies space and has mass.", "Atoms are the smallest units of matter.", "Molecules are formed by the combination of atoms.", "Chemical reactions follow the Law of Conservation of Mass.", "The mole is the SI unit for amount of substance.", "One mole contains 6.022 × 10^23 particles.", "Balanced chemical equations obey stoichiometric relationships.", "Concentration of solutions can be expressed using molarity and molality."]', '[{"name": "Law of Conservation of Mass", "statement": "Mass can neither be created nor destroyed during a chemical reaction."}, {"name": "Law of Definite Proportions", "statement": "A chemical compound always contains the same elements in the same proportion by mass."}, {"name": "Law of Multiple Proportions", "statement": "When two elements combine to form more than one compound, the masses of one element that combine with a fixed mass of the other are in simple whole-number ratios."}, {"name": "Gay-Lussac\'s Law of Gaseous Volumes", "statement": "Gases combine in simple whole-number ratios by volume."}, {"name": "Avogadro\'s Law", "statement": "Equal volumes of gases at the same temperature and pressure contain equal numbers of molecules."}]', '[{"name": "Number of Moles", "formula": "n = Mass / Molar Mass"}, {"name": "Number of Particles", "formula": "N = n × NA"}, {"name": "Molarity", "formula": "M = Moles of Solute / Volume of Solution (L)"}, {"name": "Molality", "formula": "m = Moles of Solute / Mass of Solvent (kg)"}, {"name": "Percentage Composition", "formula": "% Element = (Mass of Element / Molecular Mass) × 100"}, {"name": "Empirical Formula", "formula": "Molecular Formula = n × Empirical Formula"}]', '[{"name": "Avogadro Constant", "value": "6.022 × 10^23 mol^-1"}, {"name": "Molar Volume at STP", "value": "22.4 L"}]', '[{"type": "Combination Reaction", "equation": "2H2 + O2 → 2H2O"}, {"type": "Combustion Reaction", "equation": "C + O2 → CO2"}, {"type": "Haber Process", "equation": "N2 + 3H2 → 2NH3"}]', '["Chemistry is the science of matter and its transformations.", "The mole concept forms the foundation of quantitative chemistry.", "Stoichiometry helps determine reactant and product quantities.", "Balanced equations are essential for chemical calculations.", "Atomic mass is measured in atomic mass units (u)."]', '["Calculation of medicine dosages.", "Industrial production of chemicals.", "Fertilizer manufacturing.", "Environmental pollution analysis.", "Food chemistry and nutrition."]', '[{"id": 101, "title": "Mole Concept Simulator", "description": "Convert between mass, moles and particles interactively."}, {"id": 102, "title": "Stoichiometry Calculator", "description": "Perform reactant-product calculations."}, {"id": 103, "title": "Solution Concentration Lab", "description": "Prepare solutions and calculate molarity."}]', '[{"id": 1, "hint": "C = 12, H = 1, O = 16", "question": "Calculate the molecular mass of glucose (C6H12O6)."}, {"id": 2, "hint": "Molar mass of water = 18 g/mol", "question": "How many moles are present in 180 g of water?"}, {"id": 3, "question": "Calculate the number of molecules present in 2 moles of oxygen."}, {"id": 4, "question": "Find the molarity of a solution containing 2 moles of NaCl dissolved in 1 litre of solution."}, {"id": 5, "question": "Calculate the percentage composition of oxygen in water."}]', '[]', 'Beginner', '4 Hours', '{"jee": "Very High", "neet": "Very High", "boards": "High"}', '{"id": 2, "title": "Structure of Atom"}', 1, '2026-06-05 22:22:41', 3, 'published', 1, 0, NULL, NULL, NULL, NULL, '2026-06-06 23:25:17', NULL, NULL, NULL, NULL, NULL);
INSERT INTO `chapters` (`id`, `class_level`, `chapter_number`, `title`, `description`, `learning_objectives`, `key_points`, `important_laws`, `formulas`, `constants`, `important_reactions`, `notes`, `real_life_applications`, `virtual_labs`, `practice_questions`, `common_mistakes`, `difficulty`, `estimated_study_time`, `chapter_weightage`, `next_chapter`, `quiz_id`, `created_at`, `module_id`, `status`, `version`, `order_index`, `publish_at`, `course_id`, `reactions`, `experiment_content`, `updated_at`, `overview_content`, `key_points_content`, `formula_content`, `reaction_content`, `practice_content`) VALUES (2, '11', 2, 'Structure of Atom', 'This chapter explores the evolution of atomic models, subatomic particles, electromagnetic radiation, quantum theory, atomic spectra, Bohr\'s model, quantum mechanical model, and electronic configuration.', '["Understand the discovery of subatomic particles.", "Compare different atomic models.", "Study electromagnetic radiation and atomic spectra.", "Understand quantum theory and wave-particle duality.", "Learn quantum numbers and their significance.", "Write electronic configurations of atoms and ions."]', '["Atoms consist of electrons, protons and neutrons.", "J.J. Thomson proposed the Plum Pudding Model.", "Rutherford discovered the atomic nucleus through alpha scattering experiments.", "Bohr explained the hydrogen spectrum using quantized energy levels.", "Matter exhibits both particle and wave nature.", "Heisenberg\'s Uncertainty Principle limits simultaneous measurement of position and momentum.", "Quantum numbers describe the location and behavior of electrons.", "Electronic configuration follows Aufbau Principle, Pauli Exclusion Principle and Hund\'s Rule."]', '[{"name": "Planck\'s Quantum Theory", "statement": "Energy is emitted or absorbed in discrete packets called quanta."}, {"name": "de Broglie Hypothesis", "statement": "Matter exhibits wave-like properties."}, {"name": "Heisenberg\'s Uncertainty Principle", "statement": "Position and momentum of a particle cannot both be measured accurately at the same time."}, {"name": "Pauli Exclusion Principle", "statement": "No two electrons in an atom can have the same set of four quantum numbers."}, {"name": "Hund\'s Rule", "statement": "Electrons occupy degenerate orbitals singly before pairing."}]', '[{"name": "Planck\'s Equation", "formula": "E = hν"}, {"name": "de Broglie Equation", "formula": "λ = h / p"}, {"name": "Uncertainty Principle", "formula": "Δx × Δp ≥ h / 4π"}, {"name": "Frequency", "formula": "ν = c / λ"}, {"name": "Bohr Radius", "formula": "r = n²h² / 4π²mke²"}, {"name": "Bohr Energy", "formula": "En = -13.6 / n² eV"}]', '[{"name": "Planck Constant", "value": "6.626 × 10^-34 Js"}, {"name": "Speed of Light", "value": "3 × 10^8 m/s"}, {"name": "Avogadro Number", "value": "6.022 × 10^23 mol^-1"}, {"name": "Electron Charge", "value": "1.602 × 10^-19 C"}]', '[]', '["Atoms are composed of subatomic particles.", "Bohr\'s model successfully explained hydrogen spectrum.", "Quantum mechanics replaced classical atomic models.", "Electrons occupy atomic orbitals instead of fixed paths.", "Electronic configuration determines chemical properties."]', '["Lasers and spectroscopy.", "Medical imaging technologies.", "Electron microscopes.", "Semiconductor devices.", "Solar cell technology."]', '[{"id": 201, "title": "Rutherford Scattering Simulator", "description": "Visualize alpha-particle scattering around atomic nuclei."}, {"id": 202, "title": "Bohr Model Simulator", "description": "Observe electron transitions and hydrogen spectra."}, {"id": 203, "title": "Quantum Number Explorer", "description": "Visualize orbitals and electron distributions."}, {"id": 204, "title": "Electronic Configuration Builder", "description": "Build electronic configurations interactively."}]', '[{"id": 1, "hint": "Relate uncertainties in position and momentum.", "question": "State Heisenberg\'s Uncertainty Principle."}, {"id": 2, "hint": "Use ν = c / λ", "question": "Calculate the frequency of light having wavelength 400 nm."}, {"id": 3, "question": "Write the electronic configuration of Iron (Fe)."}, {"id": 4, "question": "Calculate the energy of a photon having frequency 5 × 10^14 Hz."}, {"id": 5, "question": "State the limitations of Bohr\'s atomic model."}]', '["Confusing orbit and orbital.", "Incorrect application of Hund\'s Rule.", "Mixing principal and azimuthal quantum numbers.", "Ignoring units while using Planck\'s equation."]', 'Intermediate', '5 Hours', '{"jee": "Very High", "neet": "Very High", "boards": "High"}', '{"id": 3, "title": "Classification of Elements and Periodicity in Properties"}', 2, '2026-06-05 22:22:41', 3, 'published', 1, 0, NULL, NULL, NULL, NULL, '2026-06-06 23:25:17', NULL, NULL, NULL, NULL, NULL);
INSERT INTO `chapters` (`id`, `class_level`, `chapter_number`, `title`, `description`, `learning_objectives`, `key_points`, `important_laws`, `formulas`, `constants`, `important_reactions`, `notes`, `real_life_applications`, `virtual_labs`, `practice_questions`, `common_mistakes`, `difficulty`, `estimated_study_time`, `chapter_weightage`, `next_chapter`, `quiz_id`, `created_at`, `module_id`, `status`, `version`, `order_index`, `publish_at`, `course_id`, `reactions`, `experiment_content`, `updated_at`, `overview_content`, `key_points_content`, `formula_content`, `reaction_content`, `practice_content`) VALUES (3, '11', 3, 'Classification of Elements', 'Periodic laws, table groupings, electron affinities, and atomic radii configurations.', '[]', '["Mendeleev\'s Periodic Law", "Modern Periodic Law", "Trends in physical properties (atomic size, ionization energy)", "Chemical reactivity trends"]', '[]', '[]', '[]', '[]', '["The modern periodic table arranges elements by increasing atomic number. Periodic properties such as electronegativity and electron gain enthalpy trend periodically down groups and across periods."]', '[]', '[]', '[{"hint": "Consider nuclear shielding and atomic size.", "question": "Why does ionization enthalpy decrease down a group?"}]', '[]', NULL, NULL, '{}', '{}', 3, '2026-06-05 22:22:41', 3, 'published', 1, 0, NULL, NULL, NULL, NULL, '2026-06-06 23:25:17', NULL, NULL, NULL, NULL, NULL);
INSERT INTO `chapters` (`id`, `class_level`, `chapter_number`, `title`, `description`, `learning_objectives`, `key_points`, `important_laws`, `formulas`, `constants`, `important_reactions`, `notes`, `real_life_applications`, `virtual_labs`, `practice_questions`, `common_mistakes`, `difficulty`, `estimated_study_time`, `chapter_weightage`, `next_chapter`, `quiz_id`, `created_at`, `module_id`, `status`, `version`, `order_index`, `publish_at`, `course_id`, `reactions`, `experiment_content`, `updated_at`, `overview_content`, `key_points_content`, `formula_content`, `reaction_content`, `practice_content`) VALUES (4, '9', 1, 'Matter in Our Surroundings', 'This chapter introduces students to the concept of matter, its physical nature, states of matter, and how temperature and pressure affect states, concluding with evaporation.', '["Define matter and describe its particulate nature.", "Understand the characteristics of particles of matter.", "Classify matter into solid, liquid, and gas states.", "Explain the interconversion of states of matter.", "Differentiate between evaporation and boiling."]', '["Matter is anything that occupies space and has mass.", "Particles of matter are very small, have spaces between them, move continuously, and attract each other.", "States of matter: Solids (fixed shape/volume), Liquids (no fixed shape, fixed volume), Gases (no fixed shape/volume).", "Change of state occurs by changing temperature or pressure.", "Evaporation is a surface phenomenon that causes cooling."]', '["Law of Conservation of Mass"]', '[{"formula": "K = °C + 273.15", "explanation": "Formula to convert Celsius scale temperature to Kelvin scale."}]', '[]', '[]', '["Matter is made of tiny particles called atoms and molecules. The space between these particles is minimum in solids, intermediate in liquids, and maximum in gases. The force of attraction is strongest in solids and weakest in gases. Kinetic energy of particles increases with rise in temperature."]', '["Cooling of water in earthen pots (matkas) via evaporation.", "Wearing cotton clothes in summer to absorb sweat and facilitate evaporation cooling."]', '["Melting Point of Ice Simulation"]', '[{"hint": "Humidity is low and temperature is high, which increases the rate of evaporation.", "question": "Why does a desert cooler cool better on a hot dry day?"}]', '["Confusing boiling (bulk phenomenon) with evaporation (surface phenomenon)."]', 'Beginner', '3 Hours', '{}', '{}', 3, '2026-06-05 22:22:41', 1, 'published', 1, 0, NULL, NULL, NULL, NULL, '2026-06-06 23:25:17', NULL, NULL, NULL, NULL, NULL);
INSERT INTO `chapters` (`id`, `class_level`, `chapter_number`, `title`, `description`, `learning_objectives`, `key_points`, `important_laws`, `formulas`, `constants`, `important_reactions`, `notes`, `real_life_applications`, `virtual_labs`, `practice_questions`, `common_mistakes`, `difficulty`, `estimated_study_time`, `chapter_weightage`, `next_chapter`, `quiz_id`, `created_at`, `module_id`, `status`, `version`, `order_index`, `publish_at`, `course_id`, `reactions`, `experiment_content`, `updated_at`, `overview_content`, `key_points_content`, `formula_content`, `reaction_content`, `practice_content`) VALUES (5, '10', 1, 'Acids, Bases and Salts', 'This chapter explores the chemical properties of acids and bases, how they react with metals, their common properties, the concept of pH, and family of salts.', '["Differentiate between acids and bases by their physical and chemical properties.", "Understand the indicators used for detection.", "Explain neutralization reactions.", "Understand the importance of pH in daily life.", "Identify common salts and their manufacturing processes."]', '["Acids are sour in taste, turn blue litmus red, and release H+ ions in solution.", "Bases are bitter in taste, soapy to touch, turn red litmus blue, and release OH- ions in solution.", "Indicators change color or odor in acidic or basic media.", "Acid + Base -> Salt + Water (Neutralization reaction).", "pH scale ranges from 0 (very acidic) to 14 (very alkaline). 7 is neutral."]', '[]', '[{"formula": "pH = -log[H+]", "explanation": "Calculates the pH of a solution based on hydrogen ion concentration."}]', '[]', '[{"reaction": "HCl + NaOH -> NaCl + H2O", "explanation": "Standard strong acid and strong base neutralization."}]', '["Water-soluble bases are called Alkalis. Mixing acid/base with water decreases ion concentration per unit volume (dilution). Strong acids dissociate completely in water (like HCl), while weak acids dissociate partially (like CH3COOH)."]', '["Using antacids containing magnesium hydroxide to treat acidity/indigestion.", "Tooth decay starts when pH of mouth is lower than 5.5."]', '["pH Testing and Acid-Base Titration"]', '[{"hint": "Sour substances contain acids which react with brass and copper to form toxic metallic compounds.", "question": "Why should curd and sour substances not be kept in brass and copper vessels?"}]', '["Pouring water into concentrated acid instead of slowly adding acid to water with constant stirring."]', 'Intermediate', '4 Hours', '{}', '{}', 4, '2026-06-05 22:22:41', 2, 'published', 1, 0, NULL, NULL, NULL, NULL, '2026-06-06 23:25:17', NULL, NULL, NULL, NULL, NULL);
INSERT INTO `chapters` (`id`, `class_level`, `chapter_number`, `title`, `description`, `learning_objectives`, `key_points`, `important_laws`, `formulas`, `constants`, `important_reactions`, `notes`, `real_life_applications`, `virtual_labs`, `practice_questions`, `common_mistakes`, `difficulty`, `estimated_study_time`, `chapter_weightage`, `next_chapter`, `quiz_id`, `created_at`, `module_id`, `status`, `version`, `order_index`, `publish_at`, `course_id`, `reactions`, `experiment_content`, `updated_at`, `overview_content`, `key_points_content`, `formula_content`, `reaction_content`, `practice_content`) VALUES (6, '12', 1, 'Chemical Kinetics', 'This chapter covers rate of reaction, average and instantaneous rates, factors affecting reaction rates, order and molecularity of reactions, integrated rate equations, and collision theory.', '["Define rate of reaction and differentiate between average and instantaneous rates.", "Derive integrated rate equations for zero and first order reactions.", "Understand factors affecting reaction rates (temperature, catalyst, concentration).", "Explain activation energy and Arrhenius equation."]', '["Rate of reaction is the change in concentration of reactant or product per unit time.", "Order of reaction is the sum of powers of concentration terms in the experimental rate law.", "Molecularity is the number of reacting species taking part in an elementary chemical reaction.", "Integrated rate equation for first order: k = (2.303 / t) * log( [R]0 / [R] ).", "Arrhenius Equation explains temperature dependence of rate constant."]', '["Rate Law"]', '[{"formula": "k = A * e^(-Ea / RT)", "explanation": "Arrhenius Equation relating rate constant k, pre-exponential factor A, activation energy Ea, gas constant R, and temperature T."}, {"formula": "t1/2 = 0.693 / k", "explanation": "Half-life formula for a first-order chemical reaction."}]', '[{"name": "Gas Constant (R)", "value": "8.314 J/(mol K)"}]', '[]', '["A catalyst increases reaction rate by providing an alternative reaction pathway with lower activation energy. The molecularity of a complex reaction has no meaning; order of reaction is experimentally determined and can be fractional or zero, whereas molecularity is a theoretical value and must be an integer."]', '["Storing food in a refrigerator to slow down decomposition rates.", "Catalytic converters in vehicles accelerating reactions that remove toxic exhaust gases."]', '["Kinetics Concentration Workbench"]', '[{"hint": "Use the integrated first-order rate expression and solve for t_99% and t_90%.", "question": "Show that for a first order reaction, the time required for 99% completion is twice the time required for 90% completion."}]', '["Confusing molecularity of a reaction with the order of reaction."]', 'Hard', '5 Hours', '{}', '{}', 5, '2026-06-05 22:22:41', 4, 'published', 1, 0, NULL, NULL, NULL, NULL, '2026-06-06 23:25:17', NULL, NULL, NULL, NULL, NULL);
INSERT INTO `chapters` (`id`, `class_level`, `chapter_number`, `title`, `description`, `learning_objectives`, `key_points`, `important_laws`, `formulas`, `constants`, `important_reactions`, `notes`, `real_life_applications`, `virtual_labs`, `practice_questions`, `common_mistakes`, `difficulty`, `estimated_study_time`, `chapter_weightage`, `next_chapter`, `quiz_id`, `created_at`, `module_id`, `status`, `version`, `order_index`, `publish_at`, `course_id`, `reactions`, `experiment_content`, `updated_at`, `overview_content`, `key_points_content`, `formula_content`, `reaction_content`, `practice_content`) VALUES (11, '9', 1, 'Solutions', 'Solutions are homogeneous mixtures. Their behavior follows Raoult\'s law for ideal cases but deviates for real solutions. Colligative properties help determine molar masses.', '[]', '[]', '[]', '[]', '[]', '[]', '[]', '[]', '[]', '[]', '[]', 'Beginner', '4 Hours', '{}', '{}', NULL, '2026-06-06 21:11:37', NULL, 'published', 1, 1, NULL, NULL, NULL, NULL, '2026-06-06 23:25:17', NULL, NULL, NULL, NULL, NULL);
