INSERT INTO `content_versions` (`id`, `content_type`, `content_id`, `version_number`, `title`, `content_data`, `created_by`, `created_at`) VALUES (57, 'chapter', 13, 2, 'solution', '{"course_id": 1, "class_level": "9", "chapter_number": 1, "title": "solution", "description": "SDcas", "key_points": "Types of Solutions (based on physical states of solute & solvent):\\n\\n\\u00a0\\u00a0\\u00a0* Gas in Gas, Liquid in Gas, Solid in Gas\\n\\u00a0\\u00a0\\u00a0* Gas/Liquid/Solid in Liquid (most common)\\n\\u00a0\\u00a0\\u00a0* Gas/Liquid/Solid in Solid\\n\\nConcentration Expressions:\\n\\n\\u00a0\\u00a0\\u00a0* Mass % (w/w), Volume % (v/v), Mass/Volume % (w/v)\\n\\u00a0\\u00a0\\u00a0* ppm (for trace amounts)\\n\\u00a0\\u00a0\\u00a0* Mole fraction (x)\\n\\u00a0\\u00a0\\u00a0* Molarity (M) \\u2014 temperature dependent\\n\\u00a0\\u00a0\\u00a0* Molality (m) \\u2014 temperature independent", "notes": "This chapter covers liquid solutions (mainly binary), their formation, concentration expressions, solubility factors (especially gases via Henry\'s law), vapor pressure (Raoult\'s law), ideal/non-ideal behavior, colligative properties, and abnormal molar masses due to association/dissociation (van\'t Hoff factor). It emphasizes that most life processes occur in solutions and links properties to the number of solute particles rather than their nature (colligative properties).\\nKey theme: Solutions are homogeneous mixtures. Their behavior follows Raoult\'s law for ideal cases but deviates for real solutions. Colligative properties help determine molar masses.", "formulas": "", "reactions": "", "experiment_content": "", "learning_objectives": [], "important_laws": [], "constants": [], "important_reactions": [], "real_life_applications": "[]", "virtual_labs": [], "practice_questions": [], "common_mistakes": [], "difficulty": "Beginner", "estimated_study_time": "4 Hours", "chapter_weightage": {}, "next_chapter": {}, "status": "published", "order_index": 0, "publish_at": null}', 1, '2026-06-06 23:33:04');
