INSERT INTO `experiments` (`id`, `chapter_id`, `title`, `aim`, `apparatus`, `theory`, `procedure`, `observations`, `result`, `viva_questions`, `simulation_url`, `created_at`) VALUES (1, NULL, 'Wurtz Alkane Synthesis', 'Perform a coupling reaction using methyl chloride and sodium metal in dry ether to synthesize symmetric higher alkanes (ethane).', '["Reaction Flask", "Dropping Funnel", "Reflux Condenser", "Sodium metal dispenser", "Dry Ether solvent"]', 'The Wurtz reaction is an organic coupling reaction where two alkyl halides are reacted with sodium metal in dry ether solvent to form a symmetric higher alkane. Equation: 2 R-X + 2 Na -> R-R + 2 NaX.', '["Assemble reactants in dry flask under nitrogen blanket.", "Add 2 moles of methyl chloride in dry ether.", "Introduce sodium metal pellets dropwise.", "Reflux the mixture gently to facilitate coupling.", "Isolate synthesized ethane gas output."]', '["Intense exothermic reaction upon sodium addition.", "Formation of white sodium chloride precipitate.", "Release of symmetric alkane gas (ethane)."]', 'Ethane (C2H6) is successfully synthesized through Wurtz coupling.', '[{"answer": "Sodium is highly reactive with moisture/water. Dry ether provides an inert, anhydrous medium.", "question": "Why is dry ether used as a solvent in the Wurtz reaction?"}, {"answer": "No, because Wurtz coupling requires joining of two carbon fragments, producing symmetrical alkanes with at least two carbons.", "question": "Can methane be prepared by the Wurtz reaction?"}]', NULL, '2026-06-05 22:22:41');
INSERT INTO `experiments` (`id`, `chapter_id`, `title`, `aim`, `apparatus`, `theory`, `procedure`, `observations`, `result`, `viva_questions`, `simulation_url`, `created_at`) VALUES (2, 5, 'Acid-Base Titration Workbench', 'Determine the concentration of an unknown hydrochloric acid solution by titration against standard sodium hydroxide solution using phenolphthalein indicator.', '["Burette (50 mL)", "Conical Flask (250 mL)", "Burette Stand", "Pipette (10 mL)", "Phenolphthalein indicator", "Analyte flask"]', 'Neutralization titration involves reactively mixing an acid and base to reach stoichiometry (equivalence). HCl + NaOH -> NaCl + H2O. Phenolphthalein turns pink at the alkaline endpoint (pH ~8.3).', '["Fill the burette with 0.1M sodium hydroxide titrant.", "Pipette 10 mL of unknown HCl analyte into conical flask.", "Add 2-3 drops of phenolphthalein indicator.", "Run titrant drop-wise while swirling until faint pink color persists.", "Record the burette volume equivalence mark."]', '["Acid analyte remains clear initially.", "Local pink color appears and disappears upon swirling.", "Faint persistent pink coloration marks the equivalence titration volume endpoint."]', 'Stoichiometry pH equivalence successfully reached and titration volume recorded.', '[{"answer": "The point at which the added titrant is stoichiometrically equal to the analyte.", "question": "What is the equivalent point in a titration?"}, {"answer": "Deprotonation of phenolphthalein shifts its chemical structure, widening the conjugation and absorbing green light to reflect pink.", "question": "Why does phenolphthalein turn pink in basic solutions?"}]', NULL, '2026-06-05 22:22:41');
INSERT INTO `experiments` (`id`, `chapter_id`, `title`, `aim`, `apparatus`, `theory`, `procedure`, `observations`, `result`, `viva_questions`, `simulation_url`, `created_at`) VALUES (3, 4, 'Melting Point of Ice', 'Determine the melting point of ice by observing the temperature change as ice turns into liquid water.', '["Beaker", "Thermometer (-10°C to 110°C)", "Glass Stirrer", "Crushed Ice", "Burner / Heat Source", "Tripod Stand"]', 'The temperature at which a solid substance changes into its liquid state at atmospheric pressure is called its melting point. For pure ice, this phase transition occurs at 0°C (273.15 K). During melting, the temperature remains constant due to the latent heat of fusion.', '["Place crushed ice in a beaker, ensuring it covers the bulb of the thermometer.", "Suspend the thermometer in the beaker using a stand, ensuring it does not touch the sides/bottom.", "Record the initial temperature of the ice.", "Gently stir the ice using the glass stirrer.", "Note the temperature at regular intervals as the ice starts melting, noting the point of constant temperature."]', '["Initial temperature of crushed ice is below 0°C.", "As melting begins, the temperature reaches 0°C and stays constant.", "The temperature remains at 0°C until all the ice has completely melted into liquid water."]', 'The melting point of ice is determined to be 0°C.', '[{"answer": "The amount of heat energy required to change 1 kg of a solid into liquid at atmospheric pressure at its melting point.", "question": "What is latent heat of fusion?"}, {"answer": "The heat supplied is consumed in overcoming the forces of attraction between particles of the solid state, rather than raising kinetic energy.", "question": "Why does the temperature remain constant during the change of state?"}]', NULL, '2026-06-05 22:22:41');
INSERT INTO `experiments` (`id`, `chapter_id`, `title`, `aim`, `apparatus`, `theory`, `procedure`, `observations`, `result`, `viva_questions`, `simulation_url`, `created_at`) VALUES (4, 5, 'pH Determination of Solutions', 'Determine the pH of different solution samples (hydrochloric acid, sodium hydroxide, water, acetic acid, lemon juice) using pH paper or universal indicator.', '["Test Tubes and Test Tube Stand", "pH Paper Strip", "Standard pH Color Chart", "Dropper", "Universal Indicator", "Sample Solutions"]', 'pH is a numeric scale used to specify the acidity or basicity of an aqueous solution. It is defined as the negative logarithm of hydrogen ion concentration. Acidic solutions have pH < 7, basic solutions have pH > 7, and neutral solutions have pH = 7.', '["Place 5 clean test tubes in a test tube stand and label them with sample names.", "Add 2-3 mL of each sample solution into its respective test tube.", "Use a clean dropper to place a drop of the sample solution onto a strip of pH paper.", "Observe the color change on the pH paper strip.", "Compare the resulting color with the standard pH color chart to determine the pH value."]', '["Dilute HCl turns the pH paper red (pH ~1-2).", "Dilute NaOH turns the pH paper dark violet (pH ~13-14).", "Pure water turns the pH paper green (pH ~7).", "Lemon juice turns the pH paper orange-red (pH ~3)."]', 'The pH values of the given samples are successfully determined and classified as acidic, basic, or neutral.', '[{"answer": "pH stands for \'potenz\' in German (meaning power) of hydrogen.", "question": "What does pH stand for?"}, {"answer": "Human blood pH is slightly basic, normally ranging between 7.35 and 7.45.", "question": "What is the pH of human blood?"}]', NULL, '2026-06-05 22:22:41');
INSERT INTO `experiments` (`id`, `chapter_id`, `title`, `aim`, `apparatus`, `theory`, `procedure`, `observations`, `result`, `viva_questions`, `simulation_url`, `created_at`) VALUES (5, 6, 'Effect of Concentration on Reaction Rate', 'Study the effect of concentration of sodium thiosulphate on the rate of its reaction with hydrochloric acid.', '["Conical Flasks (250 mL)", "Measuring Cylinders", "Stopwatch", "0.1 M Sodium Thiosulphate (Na2S2O3)", "1 M Hydrochloric Acid (HCl)", "White paper with a cross (X) mark"]', 'The reaction between sodium thiosulphate and hydrochloric acid produces a colloidal precipitate of sulphur: Na2S2O3 + 2 HCl -> 2 NaCl + H2O + SO2 + S. The rate of precipitation increases with increase in concentration of sodium thiosulphate. The time taken for the cross mark under the flask to become invisible is used to measure the rate.', '["Place a clean conical flask on white paper marked with a cross (X).", "Add 50 mL of 0.1 M sodium thiosulphate solution to the flask.", "Add 10 mL of 1 M HCl, start the stopwatch immediately and swirl.", "Look down through the mouth of the flask at the cross mark.", "Stop the watch the moment the cross mark becomes completely invisible due to sulphur turbidity.", "Repeat the experiment by diluting the sodium thiosulphate solution with distilled water (e.g. 40 mL thiosulphate + 10 mL water, etc.)."]', '["As thiosulphate concentration decreases (by dilution), the time taken for the cross mark to disappear increases.", "A graph of 1/t (rate) vs. concentration of sodium thiosulphate shows a linear relationship."]', 'The rate of reaction is directly proportional to the concentration of the reactants.', '[{"answer": "Sulphur precipitate is formed as a colloid, which scatters light and makes the solution turbid/opaque.", "question": "Why does the cross mark disappear in this experiment?"}, {"answer": "Reaction rate is inversely proportional to the time taken (t) for the cross mark to disappear (Rate ∝ 1/t).", "question": "What is the relationship between reaction rate and time in this study?"}]', NULL, '2026-06-05 22:22:41');
