INSERT INTO `quiz_questions` (`id`, `quiz_id`, `question`, `option_a`, `option_b`, `option_c`, `option_d`, `correct_answer`, `explanation`, `created_at`) VALUES (3, 2, 'Who proposed the Bohr Model of the atom?', 'Niels Bohr', 'Ernest Rutherford', 'John Dalton', 'J.J. Thomson', 'A', '', '2026-06-05 22:22:41');
