INSERT INTO `quiz_questions` (`id`, `quiz_id`, `question`, `option_a`, `option_b`, `option_c`, `option_d`, `correct_answer`, `explanation`, `created_at`) VALUES (6, 3, 'The process of change of liquid into vapor state at any temperature below its boiling point is called:', 'Boiling', 'Condensation', 'Evaporation', 'Sublimation', 'C', '', '2026-06-05 22:22:41');
