INSERT INTO `quiz_questions` (`id`, `quiz_id`, `question`, `option_a`, `option_b`, `option_c`, `option_d`, `correct_answer`, `explanation`, `created_at`) VALUES (8, 4, 'Which indicator turns pink in basic solutions?', 'Litmus', 'Methyl orange', 'Phenolphthalein', 'Turmeric', 'C', '', '2026-06-05 22:22:41');
INSERT INTO `quiz_questions` (`id`, `quiz_id`, `question`, `option_a`, `option_b`, `option_c`, `option_d`, `correct_answer`, `explanation`, `created_at`) VALUES (9, 5, 'What is the unit of rate constant for a first order reaction?', 'mol L-1 s-1', 'L mol-1 s-1', 's-1', 'L2 mol-2 s-1', 'C', '', '2026-06-05 22:22:41');
INSERT INTO `quiz_questions` (`id`, `quiz_id`, `question`, `option_a`, `option_b`, `option_c`, `option_d`, `correct_answer`, `explanation`, `created_at`) VALUES (10, 5, 'The Arrhenius equation is expressed as:', 'k = A * e^(Ea/RT)', 'k = A * e^(-Ea/RT)', 'k = -Ea / RT', 'k = ln(A) - Ea / RT', 'B', '', '2026-06-05 22:22:41');
INSERT INTO `quiz_questions` (`id`, `quiz_id`, `question`, `option_a`, `option_b`, `option_c`, `option_d`, `correct_answer`, `explanation`, `created_at`) VALUES (11, 6, 'What shape is methane?', 'Tetrahedral', 'Linear', 'Trigonal Planar', 'Bent', 'A', 'Methane has sp3 hybridization yielding a tetrahedral shape.', '2026-06-07 02:35:50');
