INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r1', NULL, '11', 'Wurtz Reaction', '2CH₃Cl + 2Na → C₂H₆ + 2NaCl', 'organic', '["CH₃Cl", "Na"]', '["C₂H₆", "NaCl"]', 'Dry ether', 'Two alkyl halide molecules react with sodium metal in dry ether. The sodium donates electrons to the carbon-halogen bond, forming a carbanion intermediate. Two carbanion species couple together, forming a new C–C bond and releasing sodium chloride. This is a classic coupling reaction to form alkanes.', '[]', 'Used in synthesis of symmetric alkanes in the laboratory. Important in understanding C–C bond formation.', 'Does not occur with tertiary alkyl halides (forms alkenes instead), aryl halides (C-X bond too strong), or in presence of moisture (Na reacts with water). Ineffective for unsymmetrical alkanes due to mixture of products.', '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r10', NULL, '12', 'Aldol Condensation', '2CH₃CHO → CH₃CH(OH)CH₂CHO (NaOH, H₂O)', 'organic', '["CH₃CHO", "NaOH"]', '["CH₃CH(OH)CH₂CHO"]', 'Dilute NaOH, room temperature', 'NaOH abstracts an alpha-H from acetaldehyde to form an enolate. The enolate acts as a nucleophile and attacks the carbonyl carbon of a second acetaldehyde molecule. This gives a beta-hydroxy aldehyde (aldol product). On heating, water is eliminated to form an alpha,beta-unsaturated aldehyde (condensation product).', '[]', 'Key reaction in biological metabolism (glycolysis/gluconeogenesis). Used in synthesis of perfumes, flavours, and pharmaceuticals.', 'Does not occur with aldehydes having no α-hydrogen (formaldehyde, benzaldehyde - undergo Cannizzaro instead). Fails with strong base at high temperature (resin formation). Does not work with ketones having no α-hydrogen. Sterically hindered ketones react slowly or not at all.', '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r100', NULL, '12', 'Gabriel Phthalimide Synthesis', 'Phthalimide + KOH + RCH₂Br → N-alkylphthalimide → RCH₂NH₂ (hydrazinolysis)', 'organic', '["C₆H₄(CO)₂NK", "KOH", "RCH₂Br"]', '["C₆H₄(CO)₂NCH₂R", "KBr"]', 'KOH, then R-X, then NH₂NH₂', 'Primary amines are prepared from phthalimide by alkylation followed by hydrolysis or hydrazinolysis. The method gives pure primary amines without secondary or tertiary amine contamination.', '[]', 'Preparation of pure primary amines. Used in amino acid synthesis.', 'Does not occur with secondary alkyl halides (elimination dominates). Fails without strong base (KOH). Does not work with tertiary alkyl halides. Aryl halides do not react (need different method).', '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r101', NULL, '12', 'Hoffmann Bromamide Degradation', 'CH₃CONH₂ + Br₂ + 4NaOH → CH₃NH₂ + Na₂CO₃ + 2NaBr + 2H₂O', 'organic', '["CH₃CONH₂", "Br₂", "NaOH"]', '["CH₃NH₂", "Na₂CO₃", "NaBr", "H₂O"]', 'Br₂, aqueous NaOH', 'Primary amides react with bromine and alkali to form primary amines with one carbon less. The reaction proceeds via isocyanate intermediate. This is a degradation reaction.', '[]', 'Conversion of amides to amines with loss of one carbon. Used in amino acid synthesis and structure determination.', NULL, '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r102', NULL, '12', 'Carbylamine Reaction', 'CH₃NH₂ + CHCl₃ + 3KOH → CH₃NC + 3KCl + 3H₂O', 'organic', '["CH₃NH₂", "CHCl₃", "KOH"]', '["CH₃NC", "3KCl", "3H₂O"]', 'CHCl₃, alcoholic KOH, heat', 'Primary amines react with chloroform and alcoholic KOH to form isocyanides (carbylamines) with characteristic offensive odor. This is a test for primary amines. Secondary and tertiary amines do not give this test.', '[]', 'Test for primary amines. Distinguishes primary amines from secondary and tertiary amines.', NULL, '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r103', NULL, '12', 'Hoffmann\'s Mustard Oil Reaction', 'C₆H₅NH₂ + CS₂ + HgCl₂ → C₆H₅NCS + HgS + 2HCl', 'organic', '["C₆H₅NH₂", "CS₂", "HgCl₂"]', '["C₆H₅NCS", "HgS", "HCl"]', 'CS₂, then HgCl₂', 'Primary amines react with carbon disulfide to form dithiocarbamic acid, which decomposes with HgCl₂ to give alkyl isothiocyanate (mustard oil) with characteristic smell. This is a test for primary amines.', '[]', 'Test for primary amines. Used to identify primary amines by their mustard oil smell.', NULL, '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r104', NULL, '12', 'Diazotization of Aniline', 'C₆H₅NH₂ + NaNO₂ + 2HCl → C₆H₅N₂⁺Cl⁻ + NaCl + 2H₂O', 'organic', '["C₆H₅NH₂", "NaNO₂", "HCl"]', '["C₆H₅N₂⁺Cl⁻", "NaCl", "2H₂O"]', '0-5°C, NaNO₂ + HCl', 'Primary aromatic amines react with nitrous acid (generated in situ from NaNO₂ and HCl) at low temperature to form diazonium salts. These are very reactive intermediates used in dye and drug synthesis.', '[]', 'Preparation of diazonium salts. Used in synthesis of azo dyes, phenols, and halobenzenes.', NULL, '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r105', NULL, '12', 'Hydrolysis of Sucrose', 'C₁₂H₂₂O₁₁ + H₂O → C₆H₁₂O₆ (glucose) + C₆H₁₂O₆ (fructose)', 'organic', '["C₁₂H₂₂O₁₁", "H₂O"]', '["C₆H₁₂O₆", "C₆H₁₂O₆"]', 'Dilute H₂SO₄ or enzyme invertase', 'Sucrose (cane sugar) undergoes hydrolysis in the presence of dilute acid or enzyme invertase to give equimolar mixture of glucose and fructose. This mixture is called invert sugar and is laevorotatory.', '[]', 'Preparation of invert sugar. Used in confectionery and brewing industries.', NULL, '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r106', NULL, '12', 'Molisch Test for Carbohydrates', 'Carbohydrate → Furfural/HMF (dehydration) + α-naphthol → Purple ring', 'organic', '["Carbohydrate", "H₂SO₄", "α-naphthol"]', '["Furfural derivatives", "purple complex"]', 'α-naphthol in alcohol, then conc. H₂SO₄', 'Carbohydrates are dehydrated by concentrated H₂SO₄ to form furfural or hydroxymethylfurfural, which condenses with α-naphthol to give a purple-colored complex at the junction of the two liquids.', '[]', 'General test for carbohydrates. Used to detect presence of sugars in solution.', NULL, '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r107', NULL, '12', 'Biuret Test for Proteins', 'Peptide bonds + Cu²⁺ + OH⁻ → Violet complex', 'organic', '["Protein", "CuSO₄", "NaOH"]', '["Violet complex"]', 'Dilute CuSO₄, NaOH', 'Compounds containing two or more peptide bonds form a violet-colored complex with alkaline copper sulfate solution. The color is due to coordination complex formation between Cu²⁺ and peptide nitrogen atoms.', '[]', 'Test for proteins and peptides. Used in biochemical analysis and clinical testing.', NULL, '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r108', NULL, '12', 'Formation of Nylon-6,6', 'nHO₂C(CH₂)₄CO₂H + nH₂N(CH₂)₆NH₂ → [Nylon-6,6]n + 2nH₂O', 'organic', '["HOOC(CH₂)₄COOH", "H₂N(CH₂)₆NH₂"]', '["[-OC(CH₂)₄CONH(CH₂)₆NH-]n", "H₂O"]', 'High temperature, pressure', 'Adipic acid reacts with hexamethylenediamine to form the polyamide Nylon-6,6 through condensation polymerization. Water is eliminated in the process. The numbers indicate the number of carbon atoms in each monomer.', '[]', 'Manufacture of Nylon fibers for textiles, ropes, and engineering plastics.', NULL, '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r109', NULL, '12', 'Formation of Bakelite', 'nC₆H₅OH + nHCHO → Bakelite + nH₂O (acid/base catalyst)', 'organic', '["C₆H₅OH", "HCHO"]', '["[C₆H₃(OH)CH₂]n", "H₂O"]', 'Acid or base catalyst, heat', 'Phenol reacts with formaldehyde to form Bakelite (a thermosetting polymer). Initially a linear novolac is formed, which on further heating cross-links to form a hard, rigid three-dimensional network.', '[]', 'Used for making electrical switches, handles, combs, and decorative items. First synthetic plastic.', NULL, '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r11', NULL, '12', 'Diazotization of Aniline', 'C₆H₅NH₂ + NaNO₂ + HCl → C₆H₅N₂⁺Cl⁻ + NaCl + H₂O', 'organic', '["C₆H₅NH₂", "HNO₂", "HCl"]', '["C₆H₅N₂Cl"]', '0–5°C, NaNO₂/HCl', 'Aniline is dissolved in excess HCl. Sodium nitrite is added below 5°C, generating nitrous acid (HNO₂) in situ. Nitrous acid nitrosonates the amine: the lone pair of nitrogen attacks NO⁺, forming an N-nitroso intermediate, which rearranges and loses water to give the diazonium ion (–N≡N⁺).', '[]', 'The diazonium salt is an intermediate in azo dye synthesis, Sandmeyer reaction, and pharmaceutical manufacturing.', 'Does not occur above 5°C (diazonium salt decomposes explosively). Fails with aliphatic amines (unstable diazonium salts). Does not work without excess acid. Secondary and tertiary aromatic amines give different products (N-nitroso compounds).', '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r110', NULL, '12', 'Formation of Teflon', 'nCF₂=CF₂ → [-CF₂-CF₂-]n (polytetrafluoroethylene)', 'organic', '["CF₂=CF₂"]', '["[-CF₂-CF₂-]n"]', 'High pressure, peroxide catalyst', 'Tetrafluoroethylene undergoes addition polymerization to form Teflon (PTFE). The strong C-F bonds make it chemically inert and heat resistant. It has very low friction coefficient.', '[]', 'Non-stick cookware coatings, gaskets, seals, electrical insulation, and chemical-resistant linings.', NULL, '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r111', NULL, '12', 'Clemmensen Reduction', 'C₆H₅COCH₃ + 4[H] → C₆H₅CH₂CH₃ + H₂O (Zn-Hg/HCl)', 'organic', '["C₆H₅COCH₃", "Zn", "Hg", "HCl"]', '["C₆H₅CH₂CH₃", "ZnCl₂", "H₂O"]', 'Zn-Hg amalgam, concentrated HCl, heat', 'Carbonyl compounds (aldehydes and ketones) are reduced to hydrocarbons using zinc amalgam and concentrated hydrochloric acid. The carbonyl group is reduced to CH₂ group. This works well for acid-stable compounds.', '[]', 'Reduction of carbonyl compounds to hydrocarbons. Alternative to Wolff-Kishner for base-sensitive compounds.', NULL, '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r112', NULL, '12', 'Meerwein-Ponndorf-Verley Reduction', 'R₂C=O + (CH₃)₂CHOH ⇌ R₂CHOH + (CH₃)₂C=O (Al(OCHMe₂)₃)', 'organic', '["(CH₃)₂CHOH", "R₂C=O"]', '["(CH₃)₂C=O", "R₂CHOH"]', 'Aluminum isopropoxide, isopropyl alcohol', 'Aldehydes and ketones are reduced to alcohols by aluminum isopropoxide in isopropyl alcohol. The reaction proceeds via a cyclic transition state. Acetone is formed as byproduct and removed by distillation.', '[]', 'Selective reduction of carbonyl compounds. Does not affect double bonds or other reducible groups.', NULL, '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r113', NULL, '12', 'Acetoacetic Ester Synthesis', 'CH₃COCH₂COOC₂H₅ + NaOC₂H₅ → [CH₃COCHCOOC₂H₅]⁻Na⁺ → CH₃COCHRCOOC₂H₅ (alkylation)', 'organic', '["CH₃COCH₂COOC₂H₅", "NaOC₂H₅", "RX"]', '["CH₃COCHRCOOC₂H₅", "NaX", "C₂H₅OH"]', 'Strong base (NaOEt), then alkyl halide', 'Ethyl acetoacetate has acidic α-hydrogens which are removed by strong base to form an enolate. This nucleophilic enolate attacks alkyl halides to give alkylated products, which can be hydrolyzed and decarboxylated to ketones.', '[]', 'Synthesis of ketones and substituted acetic acids. Important method for carbon-carbon bond formation.', NULL, '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r114', NULL, '12', 'Malonic Ester Synthesis', 'CH₂(COOC₂H₅)₂ + NaOC₂H₅ → [CH(COOC₂H₅)₂]⁻Na⁺ → RCH(COOC₂H₅)₂', 'organic', '["CH₂(COOC₂H₅)₂", "NaOC₂H₅", "RX"]', '["RCH(COOC₂H₅)₂", "NaX", "C₂H₅OH"]', 'Strong base (NaOEt), then alkyl halide', 'Diethyl malonate has acidic α-hydrogens which are removed by strong base. The resulting enolate attacks alkyl halides. The alkylated malonic ester can be hydrolyzed and decarboxylated to give substituted acetic acids.', '[]', 'Synthesis of substituted acetic acids and carboxylic acids with extended carbon chains.', NULL, '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r115', NULL, '12', 'Diels-Alder Reaction', 'CH₂=CH-CH=CH₂ + CH₂=CH₂ → Cyclohexene', 'organic', '["1", "3-butadiene", "ethylene"]', '["cyclohexene"]', 'Heat or pressure', 'A [4+2] cycloaddition reaction between a conjugated diene and a dienophile to form a six-membered ring. The reaction is concerted and stereospecific. It forms two new sigma bonds and one new pi bond.', '[]', 'Formation of six-membered rings in organic synthesis. Used in steroid and natural product synthesis.', NULL, '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r116', NULL, '12', 'Grignard Reaction with Carbonyl Compounds', 'RMgX + R\'CHO → RCH(OMgX)R\' → RCH(OH)R\' (hydrolysis)', 'organic', '["RMgX", "R\'CHO"]', '["RCH(OMgX)R\'"]', 'Dry ether, then H₂O/H⁺', 'Grignard reagents add to the carbonyl carbon of aldehydes and ketones. The reaction forms a new C-C bond. After hydrolysis, alcohols are obtained. Formaldehyde gives primary alcohols, other aldehydes give secondary alcohols.', '[]', 'Synthesis of alcohols with new carbon skeletons. One of the most important C-C bond forming reactions.', 'Does not occur with water or alcohols (Grignard reagent decomposes). Fails with carboxylic acids (acid-base reaction first). Does not work in protic solvents. CO₂ must be dry - moisture destroys Grignard reagent.', '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r117', NULL, '12', 'Cannizzaro Reaction (Crossed)', 'HCHO + C₆H₅CHO + NaOH → CH₃OH + C₆H₅COONa', 'organic', '["HCHO", "C₆H₅CHO", "NaOH"]', '["CH₃OH", "C₆H₅COONa"]', 'Concentrated NaOH', 'In crossed Cannizzaro reaction, one molecule of formaldehyde is oxidized to formic acid (then formate) while another aldehyde (without α-H) is reduced to alcohol. Formaldehyde is always oxidized preferentially.', '[]', 'Preparation of alcohols and acids from aldehydes without α-hydrogens.', NULL, '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r118', NULL, '12', 'Pinacol-Pinacolone Rearrangement', 'Pinacol → Pinacolone (H⁺ catalyst)', 'organic', '["(CH₃)₂C(OH)C(OH)(CH₃)₂"]', '["(CH₃)₃CCOCH₃", "H₂O"]', 'Acid catalyst (H₂SO₄)', 'Vicinal diols (glycols) undergo acid-catalyzed rearrangement to form carbonyl compounds. One -OH group is protonated and leaves as water, forming a carbocation which rearranges by alkyl shift to give a more stable carbocation, then ketone.', '[]', 'Conversion of glycols to ketones. Demonstrates carbocation rearrangements and migratory aptitude.', NULL, '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r119', NULL, '12', 'Beckmann Rearrangement', 'Oxime → Amide (acid catalyst)', 'organic', '["C₆H₅C(=NOH)CH₃", "PCl₅"]', '["C₆H₅NHCOCH₃", "POCl₃", "HCl"]', 'Acid catalyst (H₂SO₄, PCl₅, etc.)', 'Oximes rearrange to amides under acidic conditions. The group anti to the -OH group migrates to nitrogen with simultaneous loss of water. This is a stereospecific rearrangement.', '[]', 'Conversion of ketoximes to amides. Used in the industrial production of caprolactam for Nylon-6.', NULL, '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r12', NULL, '12', 'Iodoform Test (Oxidation)', 'CH₃COCH₃ + 3I₂ + 4NaOH → CHI₃ + CH₃COONa + 3NaI + 3H₂O', 'organic', '["CH₃COCH₃", "I₂", "NaOH"]', '["CHI₃", "CH₃COONa"]', 'NaOH (aq), I₂', 'NaOH generates hypoiodite (IO⁻), which iodinates the methyl group next to the carbonyl three times (triiodomethyl group forms). The resulting –CI₃ group is a good leaving group, and NaOH cleaves the bond to give iodoform (CHI₃) — a yellow precipitate — and sodium acetate.', '[]', 'Qualitative test for methyl ketones and secondary alcohols with CH₃–CHOH– group. Iodoform smells antiseptic; historically used as antiseptic.', 'Does not occur with aldehydes (except acetaldehyde) or ketones without CH₃-CO- group. Fails with tertiary alcohols. Does not work with bromine or chlorine under same conditions (iodine is specific). Benzophenone does not give this test.', '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r120', NULL, '12', 'Hydroboration-Oxidation of Alkenes', '6RCH=CH₂ + B₂H₆ → 2(RCH₂CH₂)₃B → 3RCH₂CH₂OH + B(OH)₃', 'organic', '["RCH=CH₂", "BH₃", "H₂O₂", "NaOH"]', '["RCH₂CH₂OH"]', '1) BH₃·THF, 2) H₂O₂, NaOH', 'Borane adds to alkenes in anti-Markovnikov fashion (H to more substituted carbon). The organoborane is then oxidized with H₂O₂/NaOH to give alcohol. The addition is syn (cis).', '[]', 'Preparation of alcohols from alkenes with anti-Markovnikov regioselectivity. Important synthetic method.', 'Does not occur with alkynes (different products - aldehydes/ketones). Fails without oxidation step (H₂O₂/NaOH). Does not work with hindered alkenes (disubstituted boranes used instead). Requires dry THF - moisture reacts with BH₃.', '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r121', NULL, '12', 'Ozonolysis of Alkenes', 'RCH=CHR\' + O₃ → Ozonide → RCHO + R\'CHO (reductive workup)', 'organic', '["RCH=CHR\'", "O₃"]', '["RCHO", "R\'CHO"]', '1) O₃, 2) Zn/H₂O or (CH₃)₂S', 'Ozone adds to alkenes to form molozonide which rearranges to ozonide. Reductive workup (Zn/H₂O or dimethyl sulfide) cleaves the ozonide to give aldehydes/ketones. Oxidative workup gives carboxylic acids.', '[]', 'Cleavage of double bonds to carbonyl compounds. Used to locate double bonds and in organic synthesis.', NULL, '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r122', NULL, '12', 'Wittig Reaction', 'Ph₃P=CHR + R\'CHO → RCH=CHR\' + Ph₃P=O', 'organic', '["Ph₃P=CHR", "R\'CHO"]', '["RCH=CHR\'", "Ph₃P=O"]', 'Polar aprotic solvent', 'Phosphorus ylides react with aldehydes or ketones to form alkenes and triphenylphosphine oxide. The reaction is stereoselective - unstabilized ylides give Z-alkenes, stabilized ylides give E-alkenes.', '[]', 'Synthesis of alkenes from carbonyl compounds. Used in vitamin A and pheromone synthesis.', 'Does not occur with esters or amides (ylide attacks carbonyl but doesn\'t eliminate). Fails with highly hindered ketones. Does not work with carboxylic acids (deprotonates ylide). Requires anhydrous conditions.', '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r123', NULL, '9', 'Sublimation of Ammonium Chloride', 'NH₄Cl(s) ⇌ NH₄Cl(g)', 'organic', '["NH₄Cl"]', '["NH₄Cl"]', 'Heat and cool', 'Ammonium chloride undergoes sublimation - it changes directly from solid to gas on heating and back to solid on cooling without passing through the liquid state. This is a physical change used to separate mixtures.', '[]', 'Used to demonstrate sublimation. Used in separation techniques to purify NH₄Cl from sand and other non-sublimable substances.', NULL, '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r124', NULL, '9', 'Crystallization of Copper Sulfate', 'CuSO₄ + 5H₂O → CuSO₄·5H₂O', 'organic', '["CuSO₄"]', '["CuSO₄·5H₂O"]', 'Evaporation and cooling', 'When a hot saturated solution of copper sulfate is cooled, blue crystals of copper sulfate pentahydrate form. This is a physical change involving hydration. The water molecules become part of the crystal structure.', '[]', 'Used to obtain pure solids from impure solutions. Used in purification of salts.', NULL, '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r125', NULL, '9', 'Chromatography Separation', 'Separation based on differential adsorption', 'organic', '["Ink mixture"]', '["Separated pigments"]', 'Filter paper, solvent', 'Chromatography separates components of a mixture based on their differential adsorption on a stationary phase and differential solubility in a mobile phase. Different pigments travel at different rates.', '[]', 'Used to separate and identify components of mixtures. Used in forensic science, food testing, and pharmaceutical analysis.', NULL, '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r126', NULL, '9', 'Formation of Water Molecule', '2H₂ + O₂ → 2H₂O', 'organic', '["H₂", "O₂"]', '["H₂O"]', 'Spark/Electric discharge', 'Hydrogen and oxygen combine in a 2:1 ratio by volume to form water. This demonstrates the law of constant proportions and the concept of atoms combining in fixed ratios to form molecules.', '[]', 'Demonstrates chemical combination at molecular level. Used in fuel cells and hydrogen economy concepts.', NULL, '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r127', NULL, '9', 'Formation of Ammonia Molecule', 'N₂ + 3H₂ → 2NH₃', 'organic', '["N₂", "H₂"]', '["NH₃"]', 'High pressure, catalyst', 'Nitrogen and hydrogen combine in a 1:3 ratio to form ammonia molecules. This demonstrates diatomic molecules breaking apart and recombining to form new compounds with different properties.', '[]', 'Introduction to chemical bonding and molecular formulas. Foundation for understanding fertilizer production.', NULL, '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r128', NULL, '9', 'Formation of Carbon Dioxide', 'C + O₂ → CO₂', 'organic', '["C", "O₂"]', '["CO₂"]', 'Burning/Combustion', 'Carbon burns in oxygen to form carbon dioxide. One atom of carbon combines with one molecule of oxygen (two atoms) to form one molecule of carbon dioxide. This illustrates the law of conservation of mass.', '[]', 'Demonstrates atomic theory and conservation of mass. Used in understanding combustion and respiration.', NULL, '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r129', NULL, '9', 'Radioactive Decay of Uranium-238', '²³⁸U → ²³⁴Th + ⁴He (α-decay)', 'organic', '["²³⁸U"]', '["²³⁴Th", "⁴He"]', 'Spontaneous', 'Uranium-238 undergoes alpha decay, emitting an alpha particle (helium nucleus) and transforming into thorium-234. This demonstrates nuclear reactions where elements transform into other elements.', '[]', 'Used in radioactive dating, nuclear power generation, and understanding Earth\'s age.', NULL, '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r13', NULL, '12', 'Finkelstein Reaction', 'CH₃Cl + NaI → CH₃I + NaCl (acetone)', 'organic', '["CH₃Cl", "NaI"]', '["CH₃I", "NaCl"]', 'Dry acetone, heat', 'This is an SN2 nucleophilic substitution. NaI is soluble in acetone while NaCl is not. Iodide ion displaces chloride from the methyl chloride by backside attack. NaCl precipitates driving the equilibrium forward (Le Chatelier\'s principle).', '[]', 'Preparation of alkyl iodides from alkyl chlorides/bromides. Iodides are more reactive in many organic reactions.', 'Does not occur with tertiary alkyl halides (elimination dominates). Fails in protic solvents (water, alcohol). Does not work with aryl halides or vinyl halides. Requires dry acetone - moisture inhibits the reaction.', '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r130', NULL, '9', 'Beta Decay of Carbon-14', '¹⁴C → ¹⁴N + e⁻ + ν̄ (β-decay)', 'organic', '["¹⁴C"]', '["¹⁴N", "e⁻"]', 'Spontaneous', 'Carbon-14 undergoes beta decay where a neutron converts to a proton, emitting an electron (beta particle) and an antineutrino. The atomic number increases by 1 but mass number stays same.', '[]', 'Carbon-14 dating used in archaeology and paleontology to determine age of organic materials.', NULL, '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r131', NULL, '9', 'Formation of Sodium Chloride (Ionic Bond)', '2Na + Cl₂ → 2NaCl', 'organic', '["Na", "Cl₂"]', '["NaCl"]', 'Heat', 'Sodium (metal) loses one electron to form Na⁺ ion, while chlorine (non-metal) gains one electron to form Cl⁻ ion. The electrostatic attraction between oppositely charged ions forms an ionic bond.', '[]', 'Demonstrates ionic bonding. NaCl is common salt used as food preservative and in chemical industries.', NULL, '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r132', NULL, '9', 'Formation of Hydrogen Molecule (Covalent Bond)', 'H· + ·H → H:H or H-H', 'organic', '["H", "H"]', '["H₂"]', 'Normal conditions', 'Two hydrogen atoms share one pair of electrons to form a covalent bond. Each hydrogen atom achieves the stable duplet configuration of helium. This is the simplest covalent bond.', '[]', 'Demonstrates covalent bonding. Hydrogen is used as fuel and in Haber process for ammonia synthesis.', NULL, '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r133', NULL, '9', 'Formation of Water (Covalent Bond)', '2H₂ + O₂ → 2H₂O', 'organic', '["H₂", "O₂"]', '["H₂O"]', 'Spark', 'Oxygen shares two electron pairs with two hydrogen atoms forming two O-H covalent bonds. Oxygen achieves octet configuration while each hydrogen achieves duplet. The molecule has a bent shape.', '[]', 'Demonstrates polar covalent bonding and molecular geometry. Essential for all life processes.', NULL, '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r134', NULL, '9', 'Formation of Magnesium Oxide (Ionic Bond)', '2Mg + O₂ → 2MgO', 'organic', '["Mg", "O₂"]', '["MgO"]', 'Burning', 'Magnesium loses two electrons to form Mg²⁺ ion, while oxygen gains two electrons to form O²⁻ ion. The strong electrostatic attraction between these doubly charged ions forms magnesium oxide with high melting point.', '[]', 'Demonstrates formation of ionic compounds with 2+ and 2- ions. MgO is used as refractory material and antacid.', NULL, '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r135', NULL, '9', 'Evaporation of Water', 'H₂O(l) + Heat → H₂O(g)', 'organic', '["H₂O(l)"]', '["H₂O(g)"]', 'Heat', 'When water is heated, the kinetic energy of molecules increases. Molecules at the surface overcome intermolecular forces and escape into the air as water vapor. This is a physical change.', '[]', 'Cooling effect of evaporation used in sweating, earthen pots, and air conditioning.', NULL, '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r136', NULL, '9', 'Condensation of Steam', 'H₂O(g) → H₂O(l) + Heat', 'organic', '["H₂O(g)"]', '["H₂O(l)"]', 'Cooling', 'When water vapor is cooled, the kinetic energy of molecules decreases. Intermolecular forces bring molecules closer together, forming liquid water. Heat is released in this exothermic process.', '[]', 'Used in power plants, distillation processes, and understanding weather phenomena like cloud formation.', NULL, '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r137', NULL, '9', 'Melting of Ice', 'H₂O(s) + Heat → H₂O(l)', 'organic', '["H₂O(s)"]', '["H₂O(l)"]', '0°C, 1 atm', 'At 0°C, ice absorbs latent heat of fusion (334 J/g) to overcome hydrogen bonding between water molecules and transform into liquid water. Temperature remains constant during phase change.', '[]', 'Understanding phase changes, refrigeration cycles, and climate science (melting glaciers).', NULL, '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r138', NULL, '9', 'Complete Combustion of Methane', 'CH₄ + 2O₂ → CO₂ + 2H₂O', 'organic', '["CH₄", "O₂"]', '["CO₂", "H₂O"]', 'Ignition', 'Methane undergoes complete combustion in excess oxygen to form carbon dioxide and water. This is an exothermic reaction releasing large amount of heat energy. All hydrocarbons produce CO₂ and H₂O on complete combustion.', '[]', 'Natural gas (methane) used for cooking and heating. Basis of fuel energy calculations.', NULL, '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r139', NULL, '9', 'Incomplete Combustion of Methane', '2CH₄ + 3O₂ → 2CO + 4H₂O', 'organic', '["CH₄", "O₂"]', '["CO", "H₂O"]', 'Limited oxygen', 'When methane burns in limited oxygen supply, incomplete combustion occurs producing carbon monoxide (poisonous gas) instead of carbon dioxide. Soot (carbon particles) may also form.', '[]', 'Demonstrates importance of proper ventilation. CO poisoning awareness. Used in production of synthesis gas.', NULL, '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r14', NULL, '12', 'Swarts Reaction', 'CH₃Cl + AgF → CH₃F + AgCl', 'organic', '["CH₃Cl", "AgF"]', '["CH₃F", "AgCl"]', 'AgF or SbF₃, heat', 'Silver fluoride or antimony trifluoride replaces chlorine with fluorine via nucleophilic substitution. The driving force is the insolubility and stability of AgCl (or SbCl₃) formed. Fluoride is small and very electronegative, forming a strong C–F bond.', '[]', 'Used in preparation of organofluorine compounds, refrigerants (Freons), and pharmaceuticals. C–F bond imparts metabolic stability to drugs.', 'Does not occur with NaF or KF (insufficient nucleophilicity). Fails with tertiary alkyl halides. Does not work with aryl halides. Requires heavy metal fluorides (AgF, SbF₃, HgF₂) - simple alkali metal fluorides are ineffective.', '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r140', NULL, '9', 'Combustion of Ethanol', 'C₂H₅OH + 3O₂ → 2CO₂ + 3H₂O', 'organic', '["C₂H₅OH", "O₂"]', '["CO₂", "H₂O"]', 'Ignition', 'Ethanol (alcohol) burns in oxygen to produce carbon dioxide and water. Being an oxygen-containing compound, it burns more cleanly than hydrocarbons with similar carbon number.', '[]', 'Ethanol is used as biofuel (gasohol), in spirit lamps, and as a cleaner burning fuel additive.', NULL, '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r141', NULL, '9', 'Oxidation of Ethanol to Ethanoic Acid', 'C₂H₅OH + O₂ → CH₃COOH + H₂O (catalyst)', 'organic', '["C₂H₅OH", "O₂"]', '["CH₃COOH", "H₂O"]', 'Bacterial oxidation (Acetobacter)', 'Ethanol is oxidized to ethanoic acid (acetic acid) by oxidation with oxygen in presence of acetobacter bacteria. This is the process of vinegar formation from wine.', '[]', 'Manufacture of vinegar. Demonstrates oxidation of alcohols to acids.', NULL, '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r142', NULL, '9', 'Esterification - Formation of Ethyl Ethanoate', 'CH₃COOH + C₂H₅OH ⇌ CH₃COOC₂H₅ + H₂O', 'organic', '["CH₃COOH", "C₂H₅OH"]', '["CH₃COOC₂H₅", "H₂O"]', 'Conc. H₂SO₄, heat', 'Carboxylic acid reacts with alcohol in presence of concentrated sulfuric acid to form ester and water. H₂SO₄ acts as catalyst and dehydrating agent. The reaction is reversible.', '[]', 'Synthesis of esters used in perfumes, flavorings, and solvents. Demonstrates functional group transformation.', NULL, '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r143', NULL, '9', 'Reaction of Zinc with Sulfuric Acid', 'Zn + H₂SO₄ → ZnSO₄ + H₂', 'organic', '["Zn", "H₂SO₄"]', '["ZnSO₄", "H₂"]', 'Dilute acid', 'Zinc metal reacts with dilute sulfuric acid to form zinc sulfate and hydrogen gas. This is a single displacement reaction where more reactive zinc displaces hydrogen from the acid.', '[]', 'Laboratory preparation of hydrogen gas. Demonstrates metal-acid reactions and reactivity series.', NULL, '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r144', NULL, '9', 'Neutralization - HCl and NaOH', 'HCl + NaOH → NaCl + H₂O', 'organic', '["HCl", "NaOH"]', '["NaCl", "H₂O"]', 'Aqueous solution', 'Acid and base react to form salt and water. H⁺ ions from acid combine with OH⁻ ions from base to form water. The solution becomes neutral with pH 7. Heat is evolved (exothermic).', '[]', 'Used in antacids, treating acidic soil, and in chemical industries to produce salts.', NULL, '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r145', NULL, '9', 'Reaction of Metal Oxide with Acid', 'CuO + H₂SO₄ → CuSO₄ + H₂O', 'organic', '["CuO", "H₂SO₄"]', '["CuSO₄", "H₂O"]', 'Warm conditions', 'Basic copper oxide reacts with sulfuric acid to form copper sulfate (blue solution) and water. Metal oxides are basic and react with acids to form salts.', '[]', 'Preparation of copper sulfate. Demonstrates basic nature of metal oxides.', NULL, '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r146', NULL, '9', 'Reaction of Non-metal Oxide with Base', '2NaOH + CO₂ → Na₂CO₃ + H₂O', 'organic', '["CO₂", "NaOH"]', '["Na₂CO₃", "H₂O"]', 'Room temperature', 'Carbon dioxide (acidic oxide) reacts with sodium hydroxide (base) to form sodium carbonate and water. Non-metal oxides are acidic and react with bases to form salts.', '[]', 'Used to absorb CO₂ gas. Demonstrates acidic nature of non-metal oxides.', NULL, '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r147', NULL, '9', 'Preparation of Washing Soda', 'Na₂CO₃ + 10H₂O → Na₂CO₃·10H₂O', 'organic', '["Na₂CO₃", "H₂O"]', '["Na₂CO₃·10H₂O"]', 'Crystallization', 'Sodium carbonate dissolves in water and crystallizes as washing soda (sodium carbonate decahydrate). It contains 10 water molecules in its crystal structure.', '[]', 'Used in glass manufacture, paper industry, and as a cleansing agent.', NULL, '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r148', NULL, '9', 'Preparation of Bleaching Powder', 'Ca(OH)₂ + Cl₂ → CaOCl₂ + H₂O', 'organic', '["Ca(OH)₂", "Cl₂"]', '["CaOCl₂", "H₂O"]', 'Cold', 'Slaked lime reacts with chlorine gas to form bleaching powder (calcium oxychloride). It is a mixture of calcium hypochlorite and basic calcium chloride.', '[]', 'Used as bleaching agent in textile and paper industries, disinfectant, and in water treatment.', NULL, '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r149', NULL, '9', 'Reaction of Iron with Steam', '3Fe + 4H₂O → Fe₃O₄ + 4H₂', 'organic', '["Fe", "H₂O"]', '["Fe₃O₄", "H₂"]', 'Red hot iron + steam', 'Iron reacts with steam at high temperature to form tri-iron tetroxide (magnetite) and hydrogen gas. Iron is less reactive than sodium and calcium which react with cold water.', '[]', 'Demonstrates relative reactivity of metals with water. Used in steam reforming processes.', NULL, '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r15', NULL, '12', 'Perkin Condensation', 'C₆H₅CHO + (CH₃CO)₂O → C₆H₅CH=CHCOOH + CH₃COOH', 'organic', '["C₆H₅CHO", "CH₃COCl"]', '["C₆H₅CH=CHCOOH"]', 'Sodium acetate, acetic anhydride, heat', 'Sodium acetate generates an enolate (nucleophile) from acetic anhydride. This enolate attacks the benzaldehyde carbonyl. After an aldol-type addition, water is eliminated (from the OH and adjacent alpha-H). The product is cinnamic acid — an alpha,beta-unsaturated carboxylic acid.', '[]', 'Synthesis of cinnamic acid and its derivatives. Cinnamic acid is used in perfumes, flavours, and as a starting material for pharmaceuticals.', 'Does not occur with aliphatic aldehydes (self-condensation dominates). Fails without α-hydrogen in the acid anhydride. Does not work with ketones (steric hindrance). Requires weak base (sodium acetate) - strong bases cause side reactions.', '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r150', NULL, '9', 'Reaction of Aluminum with Iron Oxide', '2Al + Fe₂O₃ → Al₂O₃ + 2Fe + Heat', 'organic', '["Al", "Fe₂O₃"]', '["Al₂O₃", "Fe"]', 'Ignition (thermite)', 'Aluminum reduces iron oxide to iron in a highly exothermic reaction (thermite reaction). Aluminum has higher affinity for oxygen than iron. Large amount of heat is released, melting the iron produced.', '[]', 'Used for welding railway tracks, repairing heavy machinery, and in incendiary devices.', NULL, '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r151', NULL, '9', 'Formation of Carbon Monoxide', '2C + O₂ → 2CO', 'organic', '["C", "O₂"]', '["CO"]', 'Limited air supply', 'Carbon burns in limited oxygen to form carbon monoxide instead of carbon dioxide. CO is a poisonous gas that binds to hemoglobin preventing oxygen transport.', '[]', 'Used as reducing agent in metallurgy. Producer gas and water gas contain CO as fuel component.', NULL, '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r152', NULL, '9', 'Reduction of Copper Oxide by Carbon', '2CuO + C → 2Cu + CO₂', 'organic', '["CuO", "C"]', '["Cu", "CO₂"]', 'Strong heat', 'Carbon reduces copper oxide to copper metal. Carbon is more reactive than copper and can displace it from its oxide. This demonstrates reduction of metal oxides by carbon.', '[]', 'Used in extraction of less reactive metals from their oxides. Demonstrates redox reactions.', NULL, '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r153', NULL, '10', 'Thermal Decomposition of Potassium Chlorate', '2KClO₃ → 2KCl + 3O₂', 'organic', '["KClO₃"]', '["KCl", "O₂"]', 'Heat, MnO₂ catalyst', 'Potassium chlorate decomposes on heating in presence of manganese dioxide catalyst to give potassium chloride and oxygen gas. MnO₂ lowers the decomposition temperature and speeds up the reaction.', '[]', 'Laboratory preparation of oxygen gas. Used in matchstick industry and fireworks.', NULL, '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r154', NULL, '10', 'Photochemical Decomposition of Silver Bromide', '2AgBr → 2Ag + Br₂ (sunlight)', 'organic', '["AgBr"]', '["Ag", "Br₂"]', 'Sunlight', 'Silver bromide decomposes in presence of sunlight to form silver metal and bromine. The silver appears as greyish-black stain. This is the basis of black and white photography.', '[]', 'Used in photographic films and papers. Demonstrates photochemical reactions.', NULL, '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r155', NULL, '10', 'Electrolysis of Water', '2H₂O → 2H₂ + O₂ (electrolysis)', 'organic', '["H₂O"]', '["H₂", "O₂"]', 'Electrolysis with acid/base', 'Water decomposes into hydrogen and oxygen gases when electric current is passed through it. Hydrogen is liberated at cathode (double volume) and oxygen at anode. Small amount of acid or base is added to increase conductivity.', '[]', 'Demonstrates composition of water (2:1 H:O ratio). Used in hydrogen production and fuel cells.', NULL, '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r156', NULL, '10', 'Displacement of Copper by Zinc', 'Zn + CuSO₄ → ZnSO₄ + Cu', 'organic', '["Zn", "CuSO₄"]', '["ZnSO₄", "Cu"]', 'Aqueous solution', 'Zinc being more reactive than copper displaces copper from copper sulfate solution. Blue color of CuSO₄ fades as colorless ZnSO₄ forms and reddish-brown copper metal deposits.', '[]', 'Demonstrates reactivity series. Used in metallurgy and electroplating.', NULL, '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r157', NULL, '10', 'Double Displacement - Precipitation of AgCl', 'AgNO₃ + NaCl → AgCl + NaNO₃', 'organic', '["AgNO₃", "NaCl"]', '["AgCl", "NaNO₃"]', 'Aqueous solution', 'Silver nitrate reacts with sodium chloride to form a white curdy precipitate of silver chloride. This is a precipitation reaction where ions exchange partners. AgCl is insoluble in water but soluble in ammonia.', '[]', 'Test for chloride ions. Used in photographic films.', NULL, '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r158', NULL, '10', 'Double Displacement - Precipitation of BaSO₄', 'BaCl₂ + Na₂SO₄ → BaSO₄ + 2NaCl', 'organic', '["BaCl₂", "Na₂SO₄"]', '["BaSO₄", "NaCl"]', 'Aqueous solution', 'Barium chloride reacts with sodium sulfate to form a white precipitate of barium sulfate. This is a test for sulfate ions. BaSO₄ is insoluble in water and acids.', '[]', 'Test for sulfate ions. Barium meal for X-ray imaging of digestive tract.', NULL, '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r159', NULL, '10', 'Dilution of Sulfuric Acid', 'H₂SO₄ + H₂O → H₃O⁺ + HSO₄⁻', 'organic', '["H₂SO₄", "H₂O"]', '["H₂SO₄(aq)"]', 'Always add acid to water', 'Concentrated sulfuric acid releases large amount of heat when mixed with water. Always add acid to water slowly with stirring, never water to acid. The reaction produces hydronium ions.', '[]', 'Preparation of dilute acids. Safety demonstration in handling concentrated acids.', NULL, '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r16', NULL, '12', 'Benzoin Condensation', '2C₆H₅CHO → C₆H₅CH(OH)COC₆H₅ (KCN catalyst)', 'organic', '["C₆H₅CHO", "CHCl₃"]', '["C₆H₅CHOHCOC₆H₅"]', 'KCN (aq-ethanolic), heat', 'Cyanide ion acts as nucleophilic catalyst. CN⁻ attacks one benzaldehyde molecule to form a cyanohydrin anion (the umpolung intermediate). This nucleophile attacks the carbonyl of a second benzaldehyde, and CN⁻ is then expelled to give benzoin.', '[]', 'Synthesis of benzoin for use in pharmaceuticals, fragrance, and as a photoinitiator in polymer chemistry.', 'Does not occur with aliphatic aldehydes (enolizable, undergo aldol). Fails with aldehydes having electron-withdrawing groups. Does not work without cyanide catalyst (thiamine can be used instead). Aldehydes with α-hydrogen give Cannizzaro reaction instead.', '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r160', NULL, '10', 'Reaction of Acid with Metal Carbonate', 'Na₂CO₃ + 2HCl → 2NaCl + H₂O + CO₂', 'organic', '["HCl", "Na₂CO₃"]', '["NaCl", "H₂O", "CO₂"]', 'Room temperature', 'Metal carbonates react with acids to form salt, water, and carbon dioxide gas. The effervescence is due to CO₂ evolution. This is used as a test for carbonate ions.', '[]', 'Test for carbonate ions. Used in fire extinguishers (soda-acid type) and antacids.', NULL, '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r161', NULL, '10', 'Reaction of Acid with Metal Hydrogen Carbonate', 'NaHCO₃ + HCl → NaCl + H₂O + CO₂', 'organic', '["HCl", "NaHCO₃"]', '["NaCl", "H₂O", "CO₂"]', 'Room temperature', 'Metal hydrogen carbonates (bicarbonates) react with acids similarly to carbonates but more vigorously. Baking soda (NaHCO₃) reacts with acids to produce CO₂ which makes cakes and bread rise.', '[]', 'Baking powder, fire extinguishers, and antacids. Test for bicarbonate ions.', NULL, '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r162', NULL, '10', 'Reaction of Base with Ammonium Salt', 'NaOH + NH₄Cl → NaCl + NH₃ + H₂O', 'organic', '["NaOH", "NH₄Cl"]', '["NaCl", "NH₃", "H₂O"]', 'Heat', 'Strong bases react with ammonium salts on heating to liberate ammonia gas. The gas has characteristic pungent smell and turns moist red litmus blue. This is a test for ammonium ions.', '[]', 'Test for ammonium ions in qualitative analysis. Laboratory preparation of ammonia.', NULL, '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r163', NULL, '10', 'Preparation of Plaster of Paris', 'CaSO₄·2H₂O → CaSO₄·½H₂O + 1½H₂O', 'organic', '["CaSO₄·2H₂O"]', '["CaSO₄·½H₂O"]', 'Heat at 373K', 'Gypsum (calcium sulfate dihydrate) on heating at 373K loses water molecules to form plaster of Paris (calcium sulfate hemihydrate). It regains water on mixing with water and hardens.', '[]', 'Used for making toys, statues, casts for sealing broken limbs, and in dentistry.', NULL, '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r164', NULL, '10', 'Setting of Plaster of Paris', 'CaSO₄·½H₂O + 1½H₂O → CaSO₄·2H₂O', 'organic', '["CaSO₄·½H₂O", "H₂O"]', '["CaSO₄·2H₂O"]', 'Mixing with water', 'When plaster of Paris is mixed with water, it sets into a hard solid mass of gypsum. The setting is due to interlocking of crystals and slight expansion. Heat is evolved during setting.', '[]', 'Used for immobilizing fractured bones, making decorative items, and in dentistry.', NULL, '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r165', NULL, '10', 'Bleaching Action of Chlorine', 'Cl₂ + H₂O → HCl + HClO (hypochlorous acid bleaches)', 'organic', '["Cl₂", "H₂O"]', '["HCl", "HClO"]', 'Moist conditions', 'Chlorine bleaches by oxidation. In presence of water, chlorine forms hypochlorous acid (HClO) which gives oxygen to colored matter, oxidizing it to colorless products. The bleaching is permanent.', '[]', 'Bleaching cotton, linen, and wood pulp. Water treatment and disinfection.', NULL, '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r166', NULL, '10', 'Reaction of Sodium with Water', '2Na + 2H₂O → 2NaOH + H₂', 'organic', '["Na", "H₂O"]', '["NaOH", "H₂"]', 'Room temperature', 'Sodium reacts vigorously with cold water to form sodium hydroxide and hydrogen gas. The reaction is highly exothermic. Sodium melts into a silvery ball that darts on water surface due to H₂ gas evolution.', '[]', 'Demonstrates high reactivity of alkali metals. Laboratory preparation of hydrogen.', NULL, '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r167', NULL, '10', 'Reaction of Calcium with Water', 'Ca + 2H₂O → Ca(OH)₂ + H₂', 'organic', '["Ca", "H₂O"]', '["Ca(OH)₂", "H₂"]', 'Room temperature', 'Calcium reacts less vigorously than sodium with cold water, forming calcium hydroxide (slaked lime) and hydrogen gas. The reaction produces enough heat to ignite hydrogen.', '[]', 'Demonstrates reactivity of alkaline earth metals. Preparation of calcium hydroxide.', NULL, '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r168', NULL, '10', 'Reaction of Aluminum with Steam', '2Al + 3H₂O → Al₂O₃ + 3H₂', 'organic', '["Al", "H₂O"]', '["Al₂O₃", "H₂"]', 'High temperature steam', 'Aluminum reacts with steam at high temperature to form aluminum oxide and hydrogen gas. The protective oxide layer on aluminum prevents reaction at room temperature.', '[]', 'Demonstrates amphoteric nature of aluminum oxide. Used in some hydrogen generation systems.', NULL, '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r169', NULL, '10', 'Reaction of Zinc with Dilute HCl', 'Zn + 2HCl → ZnCl₂ + H₂', 'organic', '["Zn", "HCl"]', '["ZnCl₂", "H₂"]', 'Room temperature', 'Zinc reacts with dilute hydrochloric acid to form zinc chloride and hydrogen gas. Zinc is above hydrogen in reactivity series and can displace it from acids.', '[]', 'Laboratory preparation of hydrogen. Demonstrates metal-acid reactions.', NULL, '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r17', NULL, '12', 'Cannizzaro Reaction', '2HCHO + NaOH → CH₃OH + HCOONa', 'organic', '["HCHO", "NaOH"]', '["CH₃OH", "HCOONa"]', 'Conc. NaOH, no alpha-H', 'In concentrated NaOH, two molecules of formaldehyde undergo simultaneous oxidation and reduction (disproportionation). One molecule is oxidised to formate (reducing agent), and the other is reduced to methanol (oxidising agent). Requires an aldehyde with no alpha-H so aldol condensation cannot compete.', '[]', 'Industrial production of methanol and formic acid. Key in understanding redox reactions of carbonyl compounds.', 'Does not occur with aldehydes having α-hydrogen (aldol condensation dominates). Fails with dilute NaOH. Does not work with ketones. Benzaldehyde with electron-donating groups reacts slowly.', '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r170', NULL, '10', 'Reaction of Iron with Copper Sulfate', 'Fe + CuSO₄ → FeSO₄ + Cu', 'organic', '["Fe", "CuSO₄"]', '["FeSO₄", "Cu"]', 'Aqueous solution', 'Iron being more reactive than copper displaces copper from copper sulfate solution. Blue color fades to pale green (FeSO₄) and reddish-brown copper deposits form.', '[]', 'Demonstrates reactivity series. Used in copper recovery and electroplating.', NULL, '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r171', NULL, '10', 'Reaction of Zinc with Iron Sulfate', 'Zn + FeSO₄ → ZnSO₄ + Fe', 'organic', '["Zn", "FeSO₄"]', '["ZnSO₄", "Fe"]', 'Aqueous solution', 'Zinc being more reactive than iron displaces iron from iron(II) sulfate solution. Pale green color fades to colorless and grey iron metal deposits.', '[]', 'Demonstrates displacement reactions and reactivity series.', NULL, '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r172', NULL, '10', 'Extraction of Iron in Blast Furnace', 'Fe₂O₃ + 3CO → 2Fe + 3CO₂', 'organic', '["Fe₂O₃", "CO"]', '["Fe", "CO₂"]', 'High temperature (1500°C)', 'Carbon monoxide acts as reducing agent in the blast furnace, reducing iron oxide to iron metal. This is the main reaction in iron extraction from hematite ore.', '[]', 'Industrial extraction of iron from its ores. Foundation of steel industry.', NULL, '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r173', NULL, '10', 'Formation of Slag in Blast Furnace', 'CaCO₃ + SiO₂ → CaSiO₃ + CO₂', 'organic', '["CaCO₃", "SiO₂"]', '["CaSiO₃", "CO₂"]', 'High temperature', 'Limestone (CaCO₃) decomposes to CaO which reacts with sand (SiO₂) to form calcium silicate (slag). Slag being lighter floats on molten iron and protects it from oxidation.', '[]', 'Removal of impurities (gangue) during iron extraction. Slag is used in cement manufacture.', NULL, '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r174', NULL, '10', 'Combustion of Ethane', '2C₂H₆ + 7O₂ → 4CO₂ + 6H₂O', 'organic', '["C₂H₆", "O₂"]', '["CO₂", "H₂O"]', 'Ignition', 'Ethane undergoes complete combustion to form carbon dioxide and water. Like all hydrocarbons, it produces CO₂ and H₂O on complete combustion with a blue flame.', '[]', 'Natural gas component used as fuel. Demonstrates combustion of alkanes.', NULL, '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r175', NULL, '10', 'Combustion of Ethene', 'C₂H₄ + 3O₂ → 2CO₂ + 2H₂O', 'organic', '["C₂H₄", "O₂"]', '["CO₂", "H₂O"]', 'Ignition', 'Ethene burns with a luminous flame producing carbon dioxide and water. The luminous flame is due to higher carbon content and incomplete combustion producing carbon particles that glow.', '[]', 'Ethene is used as fuel and in oxy-ethylene torches for cutting and welding.', NULL, '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r176', NULL, '10', 'Combustion of Ethyne (Acetylene)', '2C₂H₂ + 5O₂ → 4CO₂ + 2H₂O', 'organic', '["C₂H₂", "O₂"]', '["CO₂", "H₂O"]', 'Ignition', 'Acetylene burns with a very hot sooty flame. When burned with oxygen (oxy-acetylene flame), temperature reaches about 3000°C, hot enough to melt metals.', '[]', 'Oxy-acetylene torches for cutting and welding metals. Used in portable lamps.', NULL, '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r177', NULL, '10', 'Addition of Bromine to Ethene', 'C₂H₄ + Br₂ → C₂H₄Br₂', 'organic', '["C₂H₄", "Br₂"]', '["C₂H₄Br₂"]', 'Room temperature', 'Ethene (unsaturated hydrocarbon) undergoes addition reaction with bromine. The orange-brown color of bromine disappears as 1,2-dibromoethane forms. This is a test for unsaturation.', '[]', 'Test for unsaturation (double/triple bonds). Used in organic synthesis.', NULL, '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r178', NULL, '10', 'Hydrogenation of Vegetable Oils', 'Unsaturated fat + H₂ → Saturated fat (Ni catalyst)', 'organic', '["Vegetable oil", "H₂"]', '["Vanaspati ghee"]', 'Nickel catalyst, 473K', 'Unsaturated vegetable oils undergo addition of hydrogen in presence of nickel catalyst to form saturated fats (vanaspati ghee/dalda). The process is called hydrogenation or hardening of oils.', '[]', 'Manufacture of vanaspati ghee from vegetable oils. Margarine production.', NULL, '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r179', NULL, '10', 'Oxidation of Ethanol to Ethanoic Acid', 'C₂H₅OH + O₂ → CH₃COOH + H₂O (catalyst)', 'organic', '["C₂H₅OH", "O₂"]', '["CH₃COOH", "H₂O"]', 'Alkaline KMnO₄ or K₂Cr₂O₇', 'Ethanol is oxidized to ethanoic acid by strong oxidizing agents like acidified potassium dichromate or alkaline potassium permanganate. The orange dichromate turns green due to Cr³⁺ formation.', '[]', 'Manufacture of vinegar. Breathalyzer test for alcohol.', NULL, '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r18', NULL, '12', 'Hofmann Bromamide Reaction', 'RCONH₂ + Br₂ + 4NaOH → RNH₂ + Na₂CO₃ + 2NaBr + 2H₂O', 'organic', '["CH₃COCl", "NaOH", "Br₂"]', '["CH₃NH₂", "CO₂"]', 'Br₂, NaOH (aq), heat', 'Bromine in NaOH converts the amide to an N-bromoamide. Base removes the remaining N–H to form an anion. A 1,2-shift (rearrangement) of the R group from C to N occurs (with loss of bromide), forming an isocyanate intermediate. Water then hydrolyses the isocyanate to give an amine with one fewer carbon.', '[]', 'Preparation of primary amines from amides, with carbon chain shortening by one. Used in synthesis of amino acids and pharmaceuticals.', 'Does not occur with N-substituted amides (secondary, tertiary). Fails with urea (different products). Does not work with acid chlorides or esters. Requires aqueous NaOH - alcoholic NaOH gives different products.', '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r180', NULL, '10', 'Reaction of Ethanol with Sodium', '2C₂H₅OH + 2Na → 2C₂H₅ONa + H₂', 'organic', '["C₂H₅OH", "Na"]', '["C₂H₅ONa", "H₂"]', 'Room temperature', 'Sodium reacts with ethanol to form sodium ethoxide and hydrogen gas. The reaction is less vigorous than with water because the O-H bond in alcohol is less polar than in water.', '[]', 'Preparation of sodium ethoxide. Demonstrates acidic nature of alcohols.', NULL, '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r181', NULL, '10', 'Dehydration of Ethanol', 'C₂H₅OH → C₂H₄ + H₂O (conc. H₂SO₄, 443K)', 'organic', '["C₂H₅OH"]', '["C₂H₄", "H₂O"]', 'Conc. H₂SO₄, 443K', 'Ethanol loses a water molecule when heated with concentrated sulfuric acid at 443K to form ethene. At 413K, ether is formed instead. This is an elimination reaction.', '[]', 'Laboratory preparation of ethene. Demonstrates dehydration of alcohols.', NULL, '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r182', NULL, '10', 'Reaction of Ethanoic Acid with Sodium Carbonate', '2CH₃COOH + Na₂CO₃ → 2CH₃COONa + H₂O + CO₂', 'organic', '["CH₃COOH", "Na₂CO₃"]', '["CH₃COONa", "H₂O", "CO₂"]', 'Room temperature', 'Weak acetic acid reacts with sodium carbonate to form sodium acetate, water, and carbon dioxide. Brisk effervescence confirms the presence of acid.', '[]', 'Test for carboxylic acids. Demonstrates acidic nature of weak acids.', NULL, '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r183', NULL, '10', 'Reaction of Ethanoic Acid with Sodium Hydroxide', 'CH₃COOH + NaOH → CH₃COONa + H₂O', 'organic', '["CH₃COOH", "NaOH"]', '["CH₃COONa", "H₂O"]', 'Room temperature', 'Acetic acid undergoes neutralization with sodium hydroxide to form sodium acetate and water. Being a weak acid, the neutralization releases less heat than strong acid-strong base reactions.', '[]', 'Preparation of sodium acetate. Used in buffer solutions.', NULL, '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r184', NULL, '10', 'Esterification of Ethanoic Acid with Ethanol', 'CH₃COOH + C₂H₅OH ⇌ CH₃COOC₂H₅ + H₂O', 'organic', '["CH₃COOH", "C₂H₅OH"]', '["CH₃COOC₂H₅", "H₂O"]', 'Conc. H₂SO₄, heat', 'Carboxylic acid reacts with alcohol in presence of concentrated sulfuric acid to form ester with fruity smell and water. H₂SO₄ acts as catalyst and dehydrating agent. Reaction is reversible.', '[]', 'Synthesis of esters used in perfumes, flavorings, and as solvents.', NULL, '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r185', NULL, '10', 'Saponification of Ethyl Ethanoate', 'CH₃COOC₂H₅ + NaOH → CH₃COONa + C₂H₅OH', 'organic', '["CH₃COOC₂H₅", "NaOH"]', '["CH₃COONa", "C₂H₅OH"]', 'Heat', 'Esters react with alkalis (sodium hydroxide) to form salt of carboxylic acid and alcohol. This reaction is called saponification and is used in soap making.', '[]', 'Soap manufacture. Hydrolysis of esters under alkaline conditions.', NULL, '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r186', NULL, '10', 'Reaction of Ethanol with Conc. Sulfuric Acid at 413K', '2C₂H₅OH → C₂H₅OC₂H₅ + H₂O (conc. H₂SO₄, 413K)', 'organic', '["C₂H₅OH"]', '["C₂H₅OC₂H₅", "H₂O"]', 'Conc. H₂SO₄, 413K', 'At 413K, two molecules of ethanol undergo intermolecular dehydration to form diethyl ether and water. This is a substitution reaction where one alcohol displaces -OH from another.', '[]', 'Laboratory preparation of diethyl ether. Demonstrates temperature-dependent products.', NULL, '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r187', NULL, '10', 'Oxidation of Methanol to Methanal', '2CH₃OH + O₂ → 2HCHO + 2H₂O (catalyst)', 'organic', '["CH₃OH", "O₂"]', '["HCHO", "H₂O"]', ' Heated copper catalyst', 'Methanol is oxidized by passing its vapor over heated copper to form methanal (formaldehyde) and water. The hot copper acts as catalyst and oxidizing agent.', '[]', 'Manufacture of formaldehyde used in plastics, resins, and preservatives.', NULL, '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r188', NULL, '10', 'Oxidation of Methanal to Methanoic Acid', '2HCHO + O₂ → 2HCOOH', 'organic', '["HCHO", "O₂"]', '["HCOOH"]', 'Oxidizing agent', 'Formaldehyde is further oxidized to formic acid (methanoic acid) by strong oxidizing agents. This demonstrates the oxidation of aldehydes to carboxylic acids.', '[]', 'Demonstrates oxidation states of carbon compounds. Used in organic synthesis.', NULL, '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r189', NULL, '10', 'Reaction of Methanoic Acid with Tollens Reagent', 'HCOOH + 2[Ag(NH₃)₂]⁺ + 2OH⁻ → CO₂ + 2Ag + 4NH₃ + 2H₂O', 'organic', '["HCOOH", "AgNO₃", "NH₄OH"]', '["CO₂", "Ag", "H₂O"]', 'Warm', 'Formic acid reduces Tollens\' reagent (ammoniacal silver nitrate) to metallic silver, forming a silver mirror. This is because formic acid has an aldehyde-like structure (contains -CHO group).', '[]', 'Test for formic acid and aldehydes. Silver mirror test.', NULL, '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r19', NULL, '12', 'Mendius Reduction', 'RCN + 2[H₂] → RCH₂NH₂ (Na + C₂H₅OH or H₂/Ni)', 'organic', '["C₆H₅CN", "Na"]', '["C₆H₅CH₂NH₂"]', 'Na/C₂H₅OH or H₂/Ni', 'The nitrile (–C≡N) is reduced in two steps: first to an imine (–CH=NH), then to a primary amine (–CH₂–NH₂). Sodium in ethanol generates nascent hydrogen (Na + C₂H₅OH → NaOC₂H₅ + H). The amine has one more carbon than the corresponding acid from which CN was derived.', '[]', 'Preparation of primary amines from nitriles. Useful in synthesis of amino acids and pharmaceutical intermediates.', 'Does not occur with isocyanides (isonitriles). Fails with partial reduction conditions (stops at imine). Does not work with aqueous Na (nitrile hydrolysis occurs). Requires anhydrous conditions - moisture inhibits reduction.', '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r190', NULL, '10', 'Reaction of Ethanol with Phosphorus Pentachloride', 'C₂H₅OH + PCl₅ → C₂H₅Cl + POCl₃ + HCl', 'organic', '["C₂H₅OH", "PCl₅"]', '["C₂H₅Cl", "POCl₃", "HCl"]', 'Room temperature', 'Ethanol reacts with phosphorus pentachloride to form chloroethane, phosphoryl chloride, and hydrogen chloride. This demonstrates the replacement of -OH group by -Cl.', '[]', 'Preparation of alkyl chlorides from alcohols. Test for -OH group.', NULL, '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r191', NULL, '10', 'Decarboxylation of Sodium Ethanoate', 'CH₃COONa + NaOH → CH₄ + Na₂CO₃ (CaO, heat)', 'organic', '["CH₃COONa", "NaOH"]', '["CH₄", "Na₂CO₃"]', 'Soda lime (NaOH + CaO), heat', 'Sodium salts of carboxylic acids lose CO₂ when heated with soda lime to form alkanes with one carbon less. This is called decarboxylation or soda lime decarboxylation.', '[]', 'Laboratory preparation of methane. Method to descend homologous series.', NULL, '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r192', NULL, '10', 'Substitution Reaction of Methane with Chlorine', 'CH₄ + Cl₂ → CH₃Cl + HCl (UV light)', 'organic', '["CH₄", "Cl₂"]', '["CH₃Cl", "HCl"]', 'UV light or heat', 'Methane undergoes free radical substitution with chlorine in presence of UV light. Hydrogen atoms are replaced one by one by chlorine atoms. The reaction can continue to form CH₂Cl₂, CHCl₃, and CCl₄.', '[]', 'Manufacture of chloromethanes used as solvents and refrigerants.', NULL, '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r193', NULL, '9', 'Freezing of Water', 'H₂O(l) → H₂O(s) + Heat', 'organic', '["H₂O(l)"]', '["H₂O(s)"]', '0°C or below', 'Water releases latent heat of fusion (334 J/g) and transforms into ice at 0°C. The molecules arrange in a hexagonal crystal structure with hydrogen bonds holding them in fixed positions.', '[]', 'Ice formation, refrigeration, preservation of food.', NULL, '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r194', NULL, '9', 'Boiling of Water', 'H₂O(l) + Heat → H₂O(g)', 'organic', '["H₂O(l)"]', '["H₂O(g)"]', '100°C at 1 atm', 'At boiling point, water absorbs latent heat of vaporization (2260 J/g) and transforms into steam. Bubbles of water vapor form throughout the liquid and rise to the surface.', '[]', 'Steam generation, cooking, sterilization.', NULL, '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r195', NULL, '9', 'Dissolution of Sugar in Water', 'C₁₂H₂₂O₁₁(s) + H₂O → C₁₂H₂₂O₁₁(aq)', 'organic', '["C₁₂H₂₂O₁₁", "H₂O"]', '["C₁₂H₂₂O₁₁(aq)"]', 'Room temperature, stirring', 'Sugar molecules separate from the crystal lattice and disperse uniformly among water molecules. This is a physical change - no new substance is formed.', '[]', 'Food preparation, pharmaceuticals, beverages.', NULL, '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r196', NULL, '9', 'Dissolution of Salt in Water', 'NaCl(s) → Na⁺(aq) + Cl⁻(aq)', 'organic', '["NaCl", "H₂O"]', '["Na⁺", "Cl⁻"]', 'Room temperature', 'Sodium chloride dissociates into sodium and chloride ions when dissolved in water. The ions become surrounded by water molecules (hydration).', '[]', 'Electrolyte solutions, saline solutions, chemical reactions.', NULL, '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r197', NULL, '9', 'Evaporation of Alcohol', 'C₂H₅OH(l) → C₂H₅OH(g)', 'organic', '["C₂H₅OH(l)"]', '["C₂H₅OH(g)"]', 'Room temperature', 'Ethanol evaporates at room temperature because it has weaker intermolecular forces than water. The process is faster than water evaporation and produces cooling.', '[]', 'Cooling effect in fever treatment, hand sanitizers, perfumes.', NULL, '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r198', NULL, '9', 'Melting of Wax', 'Wax(s) + Heat → Wax(l)', 'organic', '["Wax(s)"]', '["Wax(l)"]', '60-70°C', 'Wax melts when heated, changing from solid to liquid state. This is a physical change - the chemical composition remains the same. Different waxes have different melting points.', '[]', 'Candle making, sealing, polishes.', NULL, '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r199', NULL, '9', 'Condensation of Water Vapor on Cold Surface', 'H₂O(g) → H₂O(l) + Heat', 'organic', '["H₂O(g)"]', '["H₂O(l)"]', 'Cold surface', 'Water vapor loses heat when it contacts a cold surface and condenses into liquid water droplets. This is the reverse of evaporation and releases latent heat.', '[]', 'Water harvesting, air conditioning, dew formation.', NULL, '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r2', NULL, '12', 'Friedel-Crafts Alkylation', 'C₆H₆ + CH₃Cl → C₆H₅CH₃ + HCl (AlCl₃ catalyst)', 'organic', '["C₆H₆", "CH₃Cl", "AlCl₃"]', '["C₆H₅CH₃", "HCl"]', 'Anhydrous AlCl₃', 'AlCl₃ acts as a Lewis acid and forms a carbocation (CH₃⁺) from CH₃Cl. The highly electrophilic carbocation attacks the electron-rich benzene ring. A sigma complex (arenium ion) forms, then loses H⁺ to restore aromaticity. The result is toluene.', '[]', 'Industrial production of ethylbenzene for styrene manufacture. Synthesis of alkylbenzenes in perfumes and detergents.', 'Does not occur on benzene rings with strong electron-withdrawing groups (NO₂, SO₃H, CN, COR). Fails with aryl halides and vinyl halides. Rearrangement of carbocations occurs with primary alkyl halides. Does not work with deactivated aromatic rings.', '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r20', NULL, '12', 'Gattermann-Koch Reaction', 'C₆H₆ + CO + HCl → C₆H₅CHO + HCl (AlCl₃/CuCl)', 'organic', '["C₆H₆", "CO"]', '["C₆H₅CHO"]', 'CO + HCl, AlCl₃ + CuCl, high pressure', 'Carbon monoxide and HCl in the presence of AlCl₃ and CuCl form formyl cation (HCO⁺), which is a powerful electrophile. This electrophile undergoes Friedel-Crafts type attack on the benzene ring, introducing a –CHO group. The result is benzaldehyde.', '[]', 'Direct formylation of arenes to give aromatic aldehydes. Industrial route to benzaldehyde for flavouring and chemical synthesis.', 'Does not occur with activated aromatic rings (phenols, anilines - coordinate with catalyst). Fails with deactivated rings (nitrobenzene). Does not work without CuCl co-catalyst. Requires high pressure CO - fails at atmospheric pressure.', '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r200', NULL, '9', 'Sublimation of Iodine', 'I₂(s) ⇌ I₂(g)', 'organic', '["I₂(s)"]', '["I₂(g)"]', 'Gentle heating', 'Iodine sublimes when heated, changing directly from solid to purple vapor without melting. On cooling, the vapor deposits as shiny crystals. This demonstrates sublimation.', '[]', 'Demonstrating sublimation, iodine purification, fingerprint detection.', NULL, '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r201', NULL, '9', 'Sublimation of Dry Ice', 'CO₂(s) → CO₂(g)', 'organic', '["CO₂(s)"]', '["CO₂(g)"]', 'Room temperature', 'Solid carbon dioxide (dry ice) sublimes at room temperature, changing directly from solid to gas. It never becomes liquid at atmospheric pressure.', '[]', 'Refrigeration, fog effects, cooling agents.', NULL, '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r202', NULL, '9', 'Distillation of Water', 'H₂O(l) → H₂O(g) → H₂O(l)', 'organic', '["Impure H₂O"]', '["Pure H₂O", "Impurities"]', 'Heat, condensation', 'Water is heated to form steam, which is then cooled and condensed back to liquid. Impurities remain behind, producing pure water.', '[]', 'Water purification, production of distilled water, separation of mixtures.', NULL, '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r203', NULL, '9', 'Formation of Hydrogen Molecule', '2H → H₂', 'organic', '["H", "H"]', '["H₂"]', 'Normal conditions', 'Two hydrogen atoms share their electrons to form a covalent bond, achieving stable duplet configuration. The shared pair is attracted by both nuclei.', '[]', 'Understanding chemical bonding, hydrogen fuel.', NULL, '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r204', NULL, '9', 'Formation of Chlorine Molecule', '2Cl → Cl₂', 'organic', '["Cl", "Cl"]', '["Cl₂"]', 'Normal conditions', 'Two chlorine atoms share one pair of electrons to form a single covalent bond. Each atom achieves stable octet configuration of argon.', '[]', 'Understanding halogen bonding, chlorine chemistry.', NULL, '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r205', NULL, '9', 'Formation of Oxygen Molecule', '2O → O₂', 'organic', '["O", "O"]', '["O₂"]', 'Normal conditions', 'Two oxygen atoms share two pairs of electrons forming a double bond. This makes oxygen molecule more stable and less reactive than atomic oxygen.', '[]', 'Understanding diatomic molecules, oxygen chemistry.', NULL, '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r206', NULL, '9', 'Formation of Nitrogen Molecule', '2N → N₂', 'organic', '["N", "N"]', '["N₂"]', 'Normal conditions', 'Two nitrogen atoms share three pairs of electrons forming a triple bond. This makes N₂ very stable and explains why nitrogen is inert.', '[]', 'Understanding triple bonds, nitrogen fixation, inert atmosphere.', NULL, '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r207', NULL, '9', 'Formation of Lithium Fluoride', 'Li + F → Li⁺F⁻', 'organic', '["Li", "F"]', '["LiF"]', 'Reaction', 'Lithium loses one electron to form Li⁺ ion, fluorine gains one electron to form F⁻ ion. The electrostatic attraction forms ionic bond in LiF.', '[]', 'Understanding ionic bonding, battery electrolytes.', NULL, '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r208', NULL, '9', 'Formation of Sodium Fluoride', 'Na + F → Na⁺F⁻', 'organic', '["Na", "F"]', '["NaF"]', 'Reaction', 'Sodium donates one electron to fluorine, forming Na⁺ and F⁻ ions. The strong ionic bond makes NaF stable with high melting point.', '[]', 'Toothpaste ingredient, water fluoridation, understanding ionic radii.', NULL, '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r209', NULL, '9', 'Formation of Potassium Chloride', 'K + Cl → K⁺Cl⁻', 'organic', '["K", "Cl"]', '["KCl"]', 'Reaction', 'Potassium (group 1) loses one electron and chlorine (group 17) gains one electron. The resulting ions form KCl through ionic bonding.', '[]', 'Fertilizers, medicine, food additive (low sodium salt).', NULL, '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r21', NULL, '9', 'Combustion of Methane', 'CH₄ + 2O₂ → CO₂ + 2H₂O', 'organic', '["CH₄", "O₂"]', '["CO₂", "H₂O"]', 'Ignition, excess O₂', 'Methane undergoes complete combustion in the presence of excess oxygen. The C–H bonds are broken and new C=O and O–H bonds form, releasing a large amount of heat energy (exothermic). This is a free-radical chain reaction at high temperature.', '[]', 'Natural gas (mainly methane) used for cooking, heating, and electricity generation worldwide. CNG in vehicles.', 'Does not occur without ignition source (spark/flame). Fails with limited oxygen (incomplete combustion produces CO). Does not occur at room temperature without activation energy. Requires sufficient oxygen for complete combustion.', '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r210', NULL, '9', 'Formation of Calcium Fluoride', 'Ca + F₂ → Ca²⁺ + 2F⁻', 'organic', '["Ca", "F₂"]', '["CaF₂"]', 'Reaction', 'Calcium loses two electrons to form Ca²⁺, two fluorine atoms each gain one electron. The 1:2 ratio balances the charges in CaF₂.', '[]', 'Fluorite mineral, optical materials, source of fluorine.', NULL, '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r211', NULL, '9', 'Formation of Hydrogen Chloride', 'H₂ + Cl₂ → 2HCl', 'organic', '["H₂", "Cl₂"]', '["HCl"]', 'Light or heat', 'Hydrogen and chlorine gases react to form hydrogen chloride. The H-Cl bond is polar covalent due to electronegativity difference.', '[]', 'Hydrochloric acid production, understanding polar bonds.', NULL, '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r212', NULL, '9', 'Formation of Ammonia Molecule', 'N₂ + 3H₂ → 2NH₃', 'organic', '["N₂", "H₂"]', '["NH₃"]', 'High pressure, catalyst', 'Nitrogen triple bond breaks and each nitrogen forms three N-H bonds. The molecule has pyramidal shape with lone pair on nitrogen.', '[]', 'Fertilizer production, understanding coordinate bonds.', NULL, '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r213', NULL, '9', 'Formation of Methane Molecule', 'C + 2H₂ → CH₄', 'organic', '["C", "H₂"]', '["CH₄"]', 'Reaction conditions', 'Carbon forms four covalent bonds with hydrogen atoms. The molecule has tetrahedral geometry with bond angle of 109.5°.', '[]', 'Natural gas, understanding tetrahedral structure.', NULL, '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r214', NULL, '9', 'Formation of Water Molecule', '2H₂ + O₂ → 2H₂O', 'organic', '["H₂", "O₂"]', '["H₂O"]', 'Spark', 'Oxygen forms two covalent bonds with two hydrogen atoms. The molecule is bent with bond angle of 104.5° due to lone pairs.', '[]', 'Understanding VSEPR theory, hydrogen bonding, life processes.', NULL, '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r215', NULL, '9', 'Formation of Carbon Dioxide Molecule', 'C + O₂ → CO₂', 'organic', '["C", "O₂"]', '["CO₂"]', 'Combustion', 'Carbon forms two double bonds with oxygen atoms. The molecule is linear with bond angle of 180°.', '[]', 'Understanding double bonds, photosynthesis, greenhouse gas.', NULL, '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r216', NULL, '9', 'Formation of Magnesium Chloride', 'Mg + Cl₂ → MgCl₂', 'organic', '["Mg", "Cl₂"]', '["MgCl₂"]', 'Burning', 'Magnesium loses two electrons to form Mg²⁺, each chlorine gains one electron. The 1:2 ratio forms ionic lattice.', '[]', 'De-icing agent, magnesium source, understanding ionic crystals.', NULL, '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r217', NULL, '9', 'Formation of Aluminum Oxide', '4Al + 3O₂ → 2Al₂O₃', 'organic', '["Al", "O₂"]', '["Al₂O₃"]', 'Heat', 'Aluminum loses 3 electrons (Al³⁺), oxygen gains 2 electrons (O²⁻). The 2:3 ratio balances charges in Al₂O₃.', '[]', 'Alumina, ceramics, abrasives, protective coating.', NULL, '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r218', NULL, '9', 'Formation of Calcium Oxide', '2Ca + O₂ → 2CaO', 'organic', '["Ca", "O₂"]', '["CaO"]', 'Heat', 'Calcium loses two electrons to form Ca²⁺, oxygen gains two electrons to form O²⁻. The 1:1 ratio forms CaO with high melting point.', '[]', 'Quicklime, cement, steel making, water treatment.', NULL, '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r219', NULL, '9', 'Rusting of Iron', '4Fe + 3O₂ + nH₂O → 2Fe₂O₃·nH₂O', 'organic', '["Fe", "O₂", "H₂O"]', '["Fe₂O₃·nH₂O"]', 'Moist air', 'Iron reacts with oxygen in presence of water to form hydrated iron(III) oxide (rust). This is a slow oxidation process.', '[]', 'Understanding corrosion, protective coatings, galvanization.', NULL, '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r22', NULL, '11', 'Halogenation of Methane (Free Radical)', 'CH₄ + Cl₂ → CH₃Cl + HCl (hν or heat)', 'organic', '["CH₄", "Cl₂"]', '["CH₃Cl", "HCl"]', 'UV light or high temperature', 'A free radical substitution reaction. UV light or heat homolyticaly cleaves Cl₂ into two Cl• radicals (initiation). A chlorine radical abstracts H from CH₄ forming CH₃• and HCl (propagation step 1). CH₃• then reacts with Cl₂ to give CH₃Cl and another Cl• (propagation step 2). The chain continues until termination.', '[]', 'Industrial production of chloromethanes (CH₃Cl, CH₂Cl₂, CHCl₃, CCl₄) as solvents and intermediates.', 'Does not occur in dark at room temperature. Fails without UV light or heat (no radical initiation). Does not occur with fluorine in controlled manner (too reactive, explosion risk). Iodination is not favorable (HI is strong reducing agent).', '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r220', NULL, '9', 'Burning of Magnesium Ribbon', '2Mg + O₂ → 2MgO', 'organic', '["Mg", "O₂"]', '["MgO"]', 'Burning', 'Magnesium burns with dazzling white flame to form magnesium oxide. The reaction is highly exothermic and produces bright light.', '[]', 'Flash photography, fireworks, understanding combustion.', NULL, '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r221', NULL, '9', 'Reaction of Zinc with Oxygen', '2Zn + O₂ → 2ZnO', 'organic', '["Zn", "O₂"]', '["ZnO"]', 'Heat', 'Zinc reacts with oxygen when heated to form zinc oxide. The oxide is white when hot and yellow when cold.', '[]', 'Zinc white pigment, sunscreens, rubber manufacturing.', NULL, '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r222', NULL, '9', 'Reaction of Copper with Oxygen', '2Cu + O₂ → 2CuO', 'organic', '["Cu", "O₂"]', '["CuO"]', 'Strong heat', 'Copper reacts with oxygen on strong heating to form black copper(II) oxide. The shiny copper surface turns black.', '[]', 'Understanding metal oxidation, catalyst, pigments.', NULL, '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r223', NULL, '9', 'Reaction of Sulfur with Oxygen', 'S + O₂ → SO₂', 'organic', '["S", "O₂"]', '["SO₂"]', 'Burning', 'Sulfur burns in oxygen with blue flame to form sulfur dioxide gas. The gas has choking smell and is acidic.', '[]', 'Sulfuric acid production, preservative, understanding non-metal combustion.', NULL, '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r224', NULL, '9', 'Reaction of Phosphorus with Oxygen', 'P₄ + 5O₂ → P₄O₁₀', 'organic', '["P₄", "O₂"]', '["P₄O₁₀"]', 'Burning', 'White phosphorus burns in oxygen with bright yellow flame to form phosphorus pentoxide. The reaction produces dense white fumes.', '[]', 'Smoke screens, fertilizer production, safety matches.', NULL, '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r225', NULL, '9', 'Reaction of Hydrogen with Chlorine', 'H₂ + Cl₂ → 2HCl', 'organic', '["H₂", "Cl₂"]', '["HCl"]', 'Sunlight', 'Hydrogen and chlorine react explosively in sunlight to form hydrogen chloride. This is a photochemical reaction initiated by light.', '[]', 'HCl production, understanding photochemical reactions.', NULL, '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r226', NULL, '9', 'Reaction of Nitrogen with Oxygen', 'N₂ + O₂ → 2NO', 'organic', '["N₂", "O₂"]', '["NO"]', 'High temperature (3000°C)', 'Nitrogen and oxygen combine at very high temperatures to form nitrogen monoxide. This occurs in lightning and combustion engines.', '[]', 'Understanding atmospheric chemistry, acid rain formation.', NULL, '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r227', NULL, '9', 'Reaction of Carbon with Steam', 'C + H₂O → CO + H₂', 'organic', '["C", "H₂O"]', '["CO", "H₂"]', '1000°C', 'Carbon reacts with steam at high temperature to form water gas (CO + H₂ mixture). This is an important industrial fuel.', '[]', 'Water gas production, synthetic fuel, hydrogen production.', NULL, '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r228', NULL, '9', 'Reaction of Calcium with Nitrogen', '3Ca + N₂ → Ca₃N₂', 'organic', '["Ca", "N₂"]', '["Ca₃N₂"]', 'Heat', 'Calcium reacts with nitrogen when heated to form calcium nitride. This demonstrates that active metals can react with nitrogen.', '[]', 'Fertilizer production, understanding metal-nitrogen compounds.', NULL, '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r229', NULL, '9', 'Reaction of Sodium with Sulfur', '2Na + S → Na₂S', 'organic', '["Na", "S"]', '["Na₂S"]', 'Heat', 'Sodium reacts vigorously with sulfur to form sodium sulfide. This is a highly exothermic reaction.', '[]', 'Understanding reactivity of alkali metals, sulfide chemistry.', NULL, '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r23', NULL, '9', 'Formation of Calcium Oxide', '2Ca + O₂ → 2CaO', 'organic', '["Ca", "O₂"]', '["CaO"]', 'Heat', 'Calcium metal burns in oxygen with a bright white flame to form calcium oxide (quicklime). This is a combination reaction where two substances combine to form a single product. The reaction is highly exothermic and releases bright white light.', '[]', 'Used in cement manufacture, steel making, and as a drying agent. Calcium oxide is also used in water treatment and flue gas desulfurization.', 'Does not occur at room temperature (requires ignition). Fails in absence of oxygen. Does not occur with calcium carbonate (requires decomposition, not combination). Less reactive metals like iron require higher temperatures.', '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r230', NULL, '9', 'Reaction of Aluminum with Sulfur', '2Al + 3S → Al₂S₃', 'organic', '["Al", "S"]', '["Al₂S₃"]', 'Heat', 'Aluminum reacts with sulfur when heated to form aluminum sulfide. The compound hydrolyzes readily in water.', '[]', 'Understanding aluminum compounds, sulfide chemistry.', NULL, '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r231', NULL, '9', 'Reaction of Magnesium with Dilute HCl', 'Mg + 2HCl → MgCl₂ + H₂', 'organic', '["Mg", "HCl"]', '["MgCl₂", "H₂"]', 'Room temperature', 'Magnesium reacts with dilute hydrochloric acid to form magnesium chloride and hydrogen gas. The reaction is vigorous.', '[]', 'Laboratory preparation of hydrogen, understanding metal-acid reactions.', NULL, '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r232', NULL, '9', 'Reaction of Aluminum with Dilute H₂SO₄', '2Al + 3H₂SO₄ → Al₂(SO₄)₃ + 3H₂', 'organic', '["Al", "H₂SO₄"]', '["Al₂(SO₄)₃", "H₂"]', 'Room temperature', 'Aluminum reacts with dilute sulfuric acid to form aluminum sulfate and hydrogen. The oxide layer must be removed for reaction to start.', '[]', 'Hydrogen production, understanding amphoteric nature.', NULL, '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r233', NULL, '9', 'Reaction of Iron with Dilute HCl', 'Fe + 2HCl → FeCl₂ + H₂', 'organic', '["Fe", "HCl"]', '["FeCl₂", "H₂"]', 'Room temperature', 'Iron reacts slowly with dilute HCl to form ferrous chloride and hydrogen. The solution turns pale green due to Fe²⁺ ions.', '[]', 'Understanding metal reactivity, iron chemistry.', NULL, '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r234', NULL, '9', 'Neutralization of H₂SO₄ with NaOH', 'H₂SO₄ + 2NaOH → Na₂SO₄ + 2H₂O', 'organic', '["H₂SO₄", "NaOH"]', '["Na₂SO₄", "H₂O"]', 'Aqueous solution', 'Sulfuric acid reacts with sodium hydroxide to form sodium sulfate and water. Being diprotic, one mole of H₂SO₄ neutralizes two moles of NaOH.', '[]', 'Production of sodium sulfate, pH control, understanding diprotic acids.', NULL, '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r235', NULL, '9', 'Neutralization of HNO₃ with KOH', 'HNO₃ + KOH → KNO₃ + H₂O', 'organic', '["HNO₃", "KOH"]', '["KNO₃", "H₂O"]', 'Aqueous solution', 'Nitric acid reacts with potassium hydroxide to form potassium nitrate and water. This is a typical strong acid-strong base neutralization.', '[]', 'Production of potassium nitrate (fertilizer), pH control.', NULL, '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r236', NULL, '9', 'Reaction of CaO with H₂O', 'CaO + H₂O → Ca(OH)₂', 'organic', '["CaO", "H₂O"]', '["Ca(OH)₂"]', 'Room temperature', 'Calcium oxide (quicklime) reacts vigorously with water to form calcium hydroxide (slaked lime). The reaction is highly exothermic.', '[]', 'Whitewashing, cement production, water treatment.', NULL, '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r237', NULL, '9', 'Reaction of Na₂O with H₂O', 'Na₂O + H₂O → 2NaOH', 'organic', '["Na₂O", "H₂O"]', '["NaOH"]', 'Room temperature', 'Sodium oxide reacts with water to form sodium hydroxide. The resulting solution is strongly alkaline.', '[]', 'Caustic soda production, understanding basic oxides.', NULL, '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r238', NULL, '9', 'Reaction of SO₂ with H₂O', 'SO₂ + H₂O ⇌ H₂SO₃', 'organic', '["SO₂", "H₂O"]', '["H₂SO₃"]', 'Room temperature', 'Sulfur dioxide dissolves in water to form sulfurous acid. This is a reversible reaction - the acid decomposes back to SO₂ and water.', '[]', 'Understanding acidic oxides, food preservation, bleaching.', NULL, '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r239', NULL, '9', 'Reaction of CO₂ with CaO', 'CaO + CO₂ → CaCO₃', 'organic', '["CO₂", "CaO"]', '["CaCO₃"]', 'Room temperature', 'Calcium oxide reacts with carbon dioxide to form calcium carbonate. This is the reverse of thermal decomposition of limestone.', '[]', 'Cement setting, carbon dioxide absorption, understanding reversible reactions.', NULL, '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r24', NULL, '9', 'Formation of Magnesium Oxide', '2Mg + O₂ → 2MgO', 'organic', '["Mg", "O₂"]', '["MgO"]', 'Burning/Heat', 'Magnesium ribbon burns with a dazzling white flame when heated in air, forming magnesium oxide. This combination reaction releases a large amount of heat and light energy. The white powder formed is basic magnesium oxide.', '[]', 'Magnesium oxide is used as an antacid, in refractory materials for furnace linings, and as a supplement for magnesium deficiency.', 'Does not occur at room temperature (requires ignition). Fails in nitrogen atmosphere (Mg also reacts with N₂ at high temp). Does not occur with moist magnesium (surface oxide layer protects). Requires clean magnesium surface.', '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r240', NULL, '9', 'Preparation of Gypsum from CaCO₃', 'CaCO₃ + H₂SO₄ → CaSO₄ + H₂O + CO₂', 'organic', '["CaCO₃", "H₂SO₄"]', '["CaSO₄", "H₂O", "CO₂"]', 'Room temperature', 'Calcium carbonate reacts with sulfuric acid to form calcium sulfate, water, and carbon dioxide. This is used to produce gypsum.', '[]', 'Gypsum production, understanding acid-carbonate reactions.', NULL, '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r241', NULL, '9', 'Reaction of ZnO with NaOH', 'ZnO + 2NaOH → Na₂ZnO₂ + H₂O', 'organic', '["ZnO", "NaOH"]', '["Na₂ZnO₂", "H₂O"]', 'Aqueous solution', 'Zinc oxide reacts with sodium hydroxide to form sodium zincate and water. This demonstrates the amphoteric nature of ZnO.', '[]', 'Understanding amphoteric oxides, zinc chemistry.', NULL, '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r242', NULL, '9', 'Reaction of PbO with NaOH', 'PbO + 2NaOH → Na₂PbO₂ + H₂O', 'organic', '["PbO", "NaOH"]', '["Na₂PbO₂", "H₂O"]', 'Heat', 'Lead(II) oxide reacts with sodium hydroxide to form sodium plumbite. This shows amphoteric character of PbO.', '[]', 'Understanding amphoteric oxides, lead chemistry.', NULL, '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r243', NULL, '10', 'Thermal Decomposition of Limestone', 'CaCO₃ → CaO + CO₂', 'organic', '["CaCO₃"]', '["CaO", "CO₂"]', 'Strong heat (>825°C)', 'Calcium carbonate decomposes on strong heating to give calcium oxide (quicklime) and carbon dioxide. This is the basis of lime production.', '[]', 'Cement manufacture, lime production, steel making.', NULL, '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r244', NULL, '10', 'Decomposition of Silver Chloride', '2AgCl → 2Ag + Cl₂ (sunlight)', 'organic', '["AgCl"]', '["Ag", "Cl₂"]', 'Sunlight', 'Silver chloride is sensitive to light and decomposes to form silver metal and chlorine gas. The silver appears as greyish-black.', '[]', 'Photography, understanding photochemical decomposition.', NULL, '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r245', NULL, '10', 'Decomposition of Hydrogen Peroxide', '2H₂O₂ → 2H₂O + O₂', 'organic', '["H₂O₂"]', '["H₂O", "O₂"]', 'MnO₂ catalyst', 'Hydrogen peroxide decomposes into water and oxygen gas. The reaction is catalyzed by MnO₂ and produces bubbles of oxygen.', '[]', 'Antiseptic, bleaching, rocket propellant, oxygen source.', NULL, '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r246', NULL, '10', 'Displacement of Silver by Copper', 'Cu + 2AgNO₃ → Cu(NO₃)₂ + 2Ag', 'organic', '["Cu", "AgNO₃"]', '["Cu(NO₃)₂", "Ag"]', 'Aqueous solution', 'Copper being more reactive than silver displaces silver from silver nitrate solution. Blue color appears and silver metal deposits.', '[]', 'Understanding reactivity series, silver recovery.', NULL, '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r247', NULL, '10', 'Displacement of Mercury by Silver', '2Ag + Hg(NO₃)₂ → 2AgNO₃ + Hg', 'organic', '["Ag", "Hg(NO₃)₂"]', '["AgNO₃", "Hg"]', 'Aqueous solution', 'Silver being more reactive than mercury displaces mercury from mercury(II) nitrate solution. Silvery mercury droplets form.', '[]', 'Understanding reactivity series, mercury extraction.', NULL, '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r248', NULL, '10', 'Double Displacement - Lead Chloride Precipitation', 'Pb(NO₃)₂ + 2NaCl → PbCl₂ + 2NaNO₃', 'organic', '["Pb(NO₃)₂", "NaCl"]', '["PbCl₂", "NaNO₃"]', 'Aqueous solution', 'Lead nitrate reacts with sodium chloride to form a white precipitate of lead chloride. This is a precipitation reaction.', '[]', 'Test for lead ions, understanding solubility rules.', NULL, '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r249', NULL, '10', 'Double Displacement - Calcium Phosphate Precipitation', '3CaCl₂ + 2Na₃PO₄ → Ca₃(PO₄)₂ + 6NaCl', 'organic', '["CaCl₂", "Na₃PO₄"]', '["Ca₃(PO₄)₂", "NaCl"]', 'Aqueous solution', 'Calcium chloride reacts with sodium phosphate to form a white precipitate of calcium phosphate. This is the basis of bone formation.', '[]', 'Fertilizers, bone chemistry, water treatment.', NULL, '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r25', NULL, '9', 'Formation of Calcium Hydroxide', 'CaO + H₂O → Ca(OH)₂', 'organic', '["CaO", "H₂O"]', '["Ca(OH)₂"]', 'Room temperature', 'Calcium oxide (quicklime) reacts vigorously with water to form calcium hydroxide (slaked lime). This reaction is highly exothermic and produces hissing sounds. The product is alkaline and used in whitewashing.', '[]', 'Used in whitewashing walls, in the manufacture of bleaching powder, and as a cheap base in many chemical industries.', 'Does not occur with calcium carbonate (insoluble). Fails with calcium sulfate (different product). Does not react with oils or organic solvents. Requires water - reaction is slow with atmospheric moisture only.', '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r250', NULL, '10', 'Neutralization of Oxalic Acid with NaOH', 'H₂C₂O₄ + 2NaOH → Na₂C₂O₄ + 2H₂O', 'organic', '["H₂C₂O₄", "NaOH"]', '["Na₂C₂O₄", "H₂O"]', 'Aqueous solution', 'Oxalic acid (diprotic) reacts with sodium hydroxide to form sodium oxalate and water. It is used to standardize NaOH solutions.', '[]', 'Standardization of bases, removing rust stains.', NULL, '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r251', NULL, '10', 'Reaction of Acid with Metal Sulfide', 'FeS + 2HCl → FeCl₂ + H₂S', 'organic', '["HCl", "FeS"]', '["FeCl₂", "H₂S"]', 'Room temperature', 'Iron sulfide reacts with hydrochloric acid to form ferrous chloride and hydrogen sulfide gas. The gas has rotten egg smell.', '[]', 'Laboratory preparation of H₂S, qualitative analysis.', NULL, '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r252', NULL, '10', 'Reaction of Acid with Metal Sulfite', 'Na₂SO₃ + 2HCl → 2NaCl + H₂O + SO₂', 'organic', '["HCl", "Na₂SO₃"]', '["NaCl", "H₂O", "SO₂"]', 'Room temperature', 'Sodium sulfite reacts with hydrochloric acid to form sodium chloride, water, and sulfur dioxide gas. This is used to generate SO₂.', '[]', 'Laboratory preparation of SO₂, understanding sulfite chemistry.', NULL, '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r253', NULL, '10', 'Reaction of Concentrated H₂SO₄ with Sugar', 'C₁₂H₂₂O₁₁ → 12C + 11H₂O (dehydration)', 'organic', '["H₂SO₄", "C₁₂H₂₂O₁₁"]', '["C", "H₂O"]', 'Concentrated acid', 'Concentrated sulfuric acid dehydrates sugar, removing water and leaving behind black carbon. The mixture expands dramatically.', '[]', 'Demonstrating dehydrating property, understanding concentrated acids.', NULL, '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r254', NULL, '10', 'Reaction of Concentrated H₂SO₄ with Copper', 'Cu + 2H₂SO₄ → CuSO₄ + SO₂ + 2H₂O', 'organic', '["Cu", "H₂SO₄"]', '["CuSO₄", "SO₂", "H₂O"]', 'Heat', 'Hot concentrated sulfuric acid oxidizes copper to copper sulfate, itself getting reduced to sulfur dioxide. Brown fumes of SO₂ are evolved.', '[]', 'Preparation of copper sulfate, understanding oxidizing acids.', NULL, '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r255', NULL, '10', 'Reaction of Dilute HNO₃ with Magnesium', 'Mg + 2HNO₃ → Mg(NO₃)₂ + H₂', 'organic', '["Mg", "HNO₃"]', '["Mg(NO₃)₂", "H₂"]', 'Very dilute', 'Very dilute nitric acid reacts with magnesium to form magnesium nitrate and hydrogen gas. Magnesium is one of the few metals that can liberate H₂ from HNO₃.', '[]', 'Understanding behavior of dilute HNO₃, hydrogen production.', NULL, '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r256', NULL, '10', 'Reaction of Zinc with Concentrated HNO₃', 'Zn + 4HNO₃ → Zn(NO₃)₂ + 2NO₂ + 2H₂O', 'organic', '["Zn", "HNO₃"]', '["Zn(NO₃)₂", "NO₂", "H₂O"]', 'Concentrated', 'Concentrated nitric acid reacts with zinc to form zinc nitrate and brown fumes of nitrogen dioxide. The acid acts as oxidizing agent.', '[]', 'Understanding oxidizing nature of concentrated HNO₃.', NULL, '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r257', NULL, '10', 'Reaction of Aluminum with Concentrated HNO₃', 'Al + HNO₃ → No reaction (passivation)', 'organic', '["Al", "HNO₃"]', '["Passive layer"]', 'Concentrated, cold', 'Concentrated nitric acid makes aluminum passive by forming a protective oxide layer. This prevents further reaction.', '"Passivation by oxide-film formation"', 'Understanding passivation, storing concentrated HNO₃ in aluminum containers.', 'Concentrated nitric acid rapidly oxidizes the aluminum surface and forms a tightly adherent Al₂O₃ protective film. This oxide layer blocks fresh acid from reaching the metal surface, suppresses electron transfer, and stops the normal metal-acid reaction, so no regular reaction products are observed.', '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r258', NULL, '10', 'Reaction of NaOH with Aluminum', '2Al + 2NaOH + 2H₂O → 2NaAlO₂ + 3H₂', 'organic', '["NaOH", "Al", "H₂O"]', '["NaAlO₂", "H₂"]', 'Aqueous solution', 'Aluminum reacts with sodium hydroxide to form sodium aluminate and hydrogen gas. This shows the amphoteric nature of aluminum.', '[]', 'Understanding amphoteric metals, drain cleaners.', NULL, '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r259', NULL, '10', 'Reaction of NaOH with Zinc', 'Zn + 2NaOH → Na₂ZnO₂ + H₂', 'organic', '["NaOH", "Zn", "H₂O"]', '["Na₂ZnO₂", "H₂"]', 'Aqueous solution', 'Zinc reacts with sodium hydroxide to form sodium zincate and hydrogen gas. This demonstrates amphoteric behavior of zinc.', '[]', 'Understanding amphoteric metals, hydrogen production.', NULL, '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r26', NULL, '10', 'Formation of Ammonia', 'N₂ + 3H₂ ⇌ 2NH₃', 'organic', '["N₂", "H₂"]', '["NH₃"]', 'High pressure (200-300 atm), 450°C, Iron catalyst', 'Nitrogen and hydrogen combine in the Haber\'s process to form ammonia. This reversible reaction is the basis of the fertilizer industry. The iron catalyst speeds up the reaction without being consumed.', '[]', 'Used to manufacture nitrogenous fertilizers like urea, ammonium nitrate, and ammonium phosphate. Also used in refrigeration and chemical synthesis.', 'Does not occur at room temperature (very slow kinetics). Fails without catalyst (extremely slow). Does not proceed at atmospheric pressure (low yield). Requires 1:3 N₂:H₂ ratio - other ratios give poor conversion.', '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r260', NULL, '10', 'Preparation of Alum from Aluminum', '2Al + 3H₂SO₄ → Al₂(SO₄)₃ + 3H₂, then Al₂(SO₄)₃ + K₂SO₄ → 2KAl(SO₄)₂', 'organic', '["Al", "H₂SO₄", "K₂SO₄"]', '["KAl(SO₄)₂·12H₂O"]', 'Reaction then crystallization', 'Aluminum sulfate reacts with potassium sulfate to form potash alum, a double salt. It forms octahedral crystals.', '[]', 'Water purification, dyeing, baking powder.', NULL, '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r261', NULL, '10', 'Preparation of Mohr\'s Salt', 'FeSO₄ + (NH₄)₂SO₄ + 6H₂O → FeSO₄·(NH₄)₂SO₄·6H₂O', 'organic', '["FeSO₄", "(NH₄)₂SO₄"]', '["FeSO₄·(NH₄)₂SO₄·6H₂O"]', 'Crystallization', 'Ferrous sulfate and ammonium sulfate combine to form Mohr\'s salt, a double salt. It is more stable than ferrous sulfate alone.', '[]', 'Volumetric analysis, standard solution preparation.', NULL, '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r262', NULL, '10', 'Reaction of Chlorine with Water', 'Cl₂ + H₂O ⇌ HCl + HOCl', 'organic', '["Cl₂", "H₂O"]', '["HCl", "HOCl"]', 'Room temperature', 'Chlorine dissolves in water to form hydrochloric acid and hypochlorous acid. This is a disproportionation reaction.', '[]', 'Water treatment, bleaching, understanding chlorine chemistry.', NULL, '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r263', NULL, '10', 'Reaction of Chlorine with NaOH (Cold)', 'Cl₂ + 2NaOH → NaCl + NaClO + H₂O', 'organic', '["Cl₂", "NaOH"]', '["NaCl", "NaClO", "H₂O"]', 'Cold dilute', 'Chlorine undergoes disproportionation in cold dilute NaOH to form sodium chloride and sodium hypochlorite (bleaching powder component).', '[]', 'Bleach production, understanding disproportionation.', NULL, '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r264', NULL, '10', 'Reaction of Chlorine with Ca(OH)₂', '2Cl₂ + 2Ca(OH)₂ → CaOCl₂ + CaCl₂ + 2H₂O', 'organic', '["Cl₂", "Ca(OH)₂"]', '["CaOCl₂", "CaCl₂", "H₂O"]', 'Cold', 'Chlorine reacts with slaked lime to form bleaching powder (calcium oxychloride), calcium chloride, and water.', '[]', 'Bleaching powder manufacture, water treatment.', NULL, '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r265', NULL, '10', 'Reaction of Potassium with Water', '2K + 2H₂O → 2KOH + H₂', 'organic', '["K", "H₂O"]', '["KOH", "H₂"]', 'Room temperature', 'Potassium reacts explosively with cold water to form potassium hydroxide and hydrogen. The reaction is more vigorous than sodium.', '[]', 'Understanding alkali metal reactivity, hydrogen production.', NULL, '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r266', NULL, '10', 'Reaction of Lithium with Water', '2Li + 2H₂O → 2LiOH + H₂', 'organic', '["Li", "H₂O"]', '["LiOH", "H₂"]', 'Room temperature', 'Lithium reacts with water to form lithium hydroxide and hydrogen gas. The reaction is less vigorous than other alkali metals.', '[]', 'Understanding alkali metal trends, battery chemistry.', NULL, '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r267', NULL, '10', 'Reaction of Beryllium with Steam', 'Be + 2H₂O → Be(OH)₂ + H₂', 'organic', '["Be", "H₂O"]', '["Be(OH)₂", "H₂"]', 'Steam, high temperature', 'Beryllium reacts with steam at high temperature to form beryllium hydroxide and hydrogen. It does not react with cold water.', '[]', 'Understanding alkaline earth metal reactivity.', NULL, '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r268', NULL, '10', 'Reaction of Strontium with Water', 'Sr + 2H₂O → Sr(OH)₂ + H₂', 'organic', '["Sr", "H₂O"]', '["Sr(OH)₂", "H₂"]', 'Room temperature', 'Strontium reacts vigorously with cold water to form strontium hydroxide and hydrogen gas. The hydroxide is sparingly soluble.', '[]', 'Understanding alkaline earth metal trends, fireworks (red color).', NULL, '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r269', NULL, '10', 'Reaction of Barium with Water', 'Ba + 2H₂O → Ba(OH)₂ + H₂', 'organic', '["Ba", "H₂O"]', '["Ba(OH)₂", "H₂"]', 'Room temperature', 'Barium reacts vigorously with water to form barium hydroxide and hydrogen. The hydroxide is soluble and strongly alkaline.', '[]', 'Understanding alkaline earth metal trends, green fireworks.', NULL, '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r27', NULL, '9', 'Decomposition of Calcium Carbonate', 'CaCO₃ → CaO + CO₂', 'organic', '["CaCO₃"]', '["CaO", "CO₂"]', 'Strong heat (>825°C)', 'Calcium carbonate decomposes on strong heating to give calcium oxide and carbon dioxide gas. This thermal decomposition is used to produce quicklime on an industrial scale. The CO₂ gas turns limewater milky.', '[]', 'Used in cement manufacture, extraction of metals, and production of lime for agriculture and construction.', 'Does not occur below 825°C. Fails in open system with high CO₂ pressure (Le Chatelier\'s principle). Does not decompose at room temperature. Requires continuous heat supply - stops if temperature drops.', '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r270', NULL, '10', 'Reaction of Tin with Steam', 'Sn + 2H₂O → SnO₂ + 2H₂', 'organic', '["Sn", "H₂O"]', '["SnO₂", "H₂"]', 'Steam, heat', 'Tin reacts with steam when heated to form tin(IV) oxide and hydrogen gas. It does not react with cold or hot water.', '[]', 'Understanding metal reactivity series, tin chemistry.', NULL, '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r271', NULL, '10', 'Reaction of Lead with Steam', 'Pb + H₂O → PbO + H₂', 'organic', '["Pb", "H₂O"]', '["PbO", "H₂"]', 'Steam, heat', 'Lead reacts slowly with steam to form lead(II) oxide and hydrogen. The reaction is reversible at high temperatures.', '[]', 'Understanding metal reactivity, lead chemistry.', NULL, '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r272', NULL, '10', 'Reaction of Silver with Sulfur', '2Ag + S → Ag₂S', 'organic', '["Ag", "S"]', '["Ag₂S"]', 'Room temperature (slow)', 'Silver reacts slowly with sulfur in air to form black silver sulfide. This is why silver tarnishes over time.', '[]', 'Understanding silver tarnishing, jewelry care.', NULL, '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r273', NULL, '10', 'Reaction of Gold with Aqua Regia', 'Au + HNO₃ + 4HCl → HAuCl₄ + NO + 2H₂O', 'organic', '["Au", "HNO₃", "HCl"]', '["HAuCl₄", "NO", "H₂O"]', 'Aqua regia', 'Gold dissolves in aqua regia (3:1 HCl:HNO₃) to form chloroauric acid. Neither acid alone can dissolve gold.', '[]', 'Gold refining, understanding noble metal chemistry.', NULL, '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r274', NULL, '10', 'Reaction of Platinum with Aqua Regia', '3Pt + 4HNO₃ + 18HCl → 3H₂PtCl₆ + 4NO + 8H₂O', 'organic', '["Pt", "HNO₃", "HCl"]', '["H₂PtCl₆", "NO", "H₂O"]', 'Aqua regia', 'Platinum dissolves in aqua regia to form chloroplatinic acid. This is used to purify platinum.', '[]', 'Platinum refining, catalyst preparation.', NULL, '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r275', NULL, '10', 'Reduction of Iron Oxide by Carbon Monoxide', 'Fe₂O₃ + 3CO → 2Fe + 3CO₂', 'organic', '["Fe₂O₃", "CO"]', '["Fe", "CO₂"]', 'High temperature', 'Carbon monoxide reduces iron(III) oxide to iron metal in the blast furnace. This is the primary iron extraction reaction.', '[]', 'Iron extraction, metallurgy, steel production.', NULL, '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r276', NULL, '10', 'Reduction of Zinc Oxide by Carbon', 'ZnO + C → Zn + CO', 'organic', '["ZnO", "C"]', '["Zn", "CO"]', 'High temperature', 'Carbon reduces zinc oxide to zinc metal. This is used in the extraction of zinc from its oxide ore.', '[]', 'Zinc extraction, understanding reduction with carbon.', NULL, '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r277', NULL, '10', 'Complete Combustion of Propane', 'C₃H₈ + 5O₂ → 3CO₂ + 4H₂O', 'organic', '["C₃H₈", "O₂"]', '["CO₂", "H₂O"]', 'Ignition', 'Propane undergoes complete combustion to form carbon dioxide and water. It is a clean-burning fuel used in LPG.', '[]', 'LPG fuel, heating, cooking.', NULL, '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r278', NULL, '10', 'Complete Combustion of Butane', '2C₄H₁₀ + 13O₂ → 8CO₂ + 10H₂O', 'organic', '["C₄H₁₀", "O₂"]', '["CO₂", "H₂O"]', 'Ignition', 'Butane burns completely to form CO₂ and H₂O. It is the main component of lighter fuel and cooking gas.', '[]', 'Lighter fuel, portable stoves, camping gas.', NULL, '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r279', NULL, '10', 'Incomplete Combustion of Ethane', '2C₂H₆ + 5O₂ → 4CO + 6H₂O', 'organic', '["C₂H₆", "O₂"]', '["CO", "H₂O"]', 'Limited oxygen', 'Ethane undergoes incomplete combustion in limited oxygen to form carbon monoxide and water. The flame is sooty.', '[]', 'Understanding incomplete combustion, carbon monoxide poisoning.', NULL, '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r28', NULL, '10', 'Decomposition of Hydrogen Peroxide', '2H₂O₂ → 2H₂O + O₂', 'organic', '["H₂O₂"]', '["H₂O", "O₂"]', 'MnO₂ catalyst or heat', 'Hydrogen peroxide decomposes into water and oxygen gas. The reaction is catalyzed by manganese dioxide (MnO₂). Oxygen gas is released as bubbles, which can be tested with a glowing splint that relights.', '[]', 'Used as a bleaching agent, disinfectant, and in rocket propulsion. The oxygen released is used in breathing apparatus.', 'Does not occur at room temperature without catalyst (very slow). Fails with strong acids (stabilizes H₂O₂). Does not decompose in dark at low temperature. Some metal ions (Fe³⁺) catalyze decomposition - storage containers must be clean.', '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r280', NULL, '10', 'Reaction of Ethene with Hydrogen', 'C₂H₄ + H₂ → C₂H₆', 'organic', '["C₂H₄", "H₂"]', '["C₂H₆"]', 'Ni/Pt catalyst, heat', 'Ethene undergoes catalytic hydrogenation to form ethane. This is an addition reaction across the double bond.', '[]', 'Hydrogenation of oils, understanding catalytic addition.', NULL, '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r281', NULL, '10', 'Reaction of Ethene with Chlorine', 'C₂H₄ + Cl₂ → C₂H₄Cl₂', 'organic', '["C₂H₄", "Cl₂"]', '["C₂H₄Cl₂"]', 'Room temperature', 'Ethene reacts with chlorine to form 1,2-dichloroethane. The red-brown color of chlorine disappears.', '[]', 'PVC production, understanding addition reactions.', NULL, '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r282', NULL, '10', 'Reaction of Ethene with HCl', 'C₂H₄ + HCl → C₂H₅Cl', 'organic', '["C₂H₄", "HCl"]', '["C₂H₅Cl"]', 'Catalyst', 'Ethene reacts with hydrogen chloride to form chloroethane. This follows Markovnikov\'s rule.', '[]', 'Production of ethyl chloride, understanding electrophilic addition.', NULL, '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r283', NULL, '10', 'Reaction of Ethene with Water', 'C₂H₄ + H₂O → C₂H₅OH', 'organic', '["C₂H₄", "H₂O"]', '["C₂H₅OH"]', 'H₃PO₄ catalyst, 300°C, 60 atm', 'Ethene reacts with steam in presence of phosphoric acid catalyst to form ethanol. This is hydration of alkene.', '[]', 'Industrial ethanol production, understanding hydration.', NULL, '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r284', NULL, '10', 'Reaction of Ethyne with Hydrogen', 'C₂H₂ + H₂ → C₂H₄', 'organic', '["C₂H₂", "H₂"]', '["C₂H₄"]', 'Lindlar\'s catalyst', 'Ethyne undergoes partial hydrogenation to form ethene. Using Lindlar\'s catalyst stops at the alkene stage.', '[]', 'Controlled hydrogenation, understanding selective reduction.', NULL, '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r285', NULL, '10', 'Reaction of Ethyne with Chlorine', 'C₂H₂ + Cl₂ → C₂H₂Cl₂', 'organic', '["C₂H₂", "Cl₂"]', '["C₂H₂Cl₂"]', 'Room temperature', 'Ethyne reacts with chlorine to form dichloroethene. Further addition gives tetrachloroethane.', '[]', 'Understanding addition to alkynes, solvent production.', NULL, '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r286', NULL, '10', 'Reaction of Ethyne with HCl', 'C₂H₂ + HCl → C₂H₃Cl', 'organic', '["C₂H₂", "HCl"]', '["C₂H₃Cl"]', 'HgCl₂ catalyst', 'Ethyne reacts with HCl in presence of mercuric chloride to form vinyl chloride. This is the first step in PVC production.', '[]', 'PVC production, understanding Markovnikov addition to alkynes.', NULL, '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r287', NULL, '10', 'Trimerization of Ethyne', '3C₂H₂ → C₆H₆', 'organic', '["C₂H₂"]', '["C₆H₆"]', 'Red hot iron tube', 'Three molecules of ethyne polymerize to form benzene when passed through red hot iron tube. This is cyclic polymerization.', '[]', 'Benzene production, understanding polymerization.', NULL, '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r288', NULL, '10', 'Oxidation of Methanol to Formaldehyde', '2CH₃OH + O₂ → 2HCHO + 2H₂O', 'organic', '["CH₃OH", "O₂"]', '["HCHO", "H₂O"]', 'Ag catalyst, 600°C', 'Methanol is oxidized by passing over silver catalyst to form formaldehyde. This is an industrial process.', '[]', 'Formaldehyde production, plastics, resins.', NULL, '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r289', NULL, '10', 'Oxidation of Ethanol to Acetaldehyde', '2C₂H₅OH + O₂ → 2CH₃CHO + 2H₂O', 'organic', '["C₂H₅OH", "O₂"]', '["CH₃CHO", "H₂O"]', 'Cu catalyst, 300°C', 'Ethanol vapor is passed over heated copper to form acetaldehyde. This is catalytic dehydrogenation.', '[]', 'Acetaldehyde production, understanding oxidation of alcohols.', NULL, '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r29', NULL, '10', 'Decomposition of Ferrous Sulfate', '2FeSO₄ → Fe₂O₃ + SO₂ + SO₃', 'organic', '["FeSO₄"]', '["Fe₂O₃", "SO₂", "SO₃"]', 'Strong heat', 'Green crystals of ferrous sulfate decompose on heating to form ferric oxide (brown), sulfur dioxide, and sulfur trioxide. The color change from green to brown indicates the formation of iron(III) oxide.', '[]', 'Used to demonstrate decomposition reactions and to produce sulfur dioxide in laboratories. Ferric oxide is used as a pigment.', 'Does not occur at room temperature (requires strong heating). Fails in aqueous solution (different decomposition). Does not occur with ferric sulfate (already oxidized). Requires anhydrous ferrous sulfate.', '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r290', NULL, '10', 'Reaction of Ethanol with PCl₃', '3C₂H₅OH + PCl₃ → 3C₂H₅Cl + H₃PO₃', 'organic', '["C₂H₅OH", "PCl₃"]', '["C₂H₅Cl", "H₃PO₃"]', 'Room temperature', 'Ethanol reacts with phosphorus trichloride to form chloroethane and phosphorous acid. The -OH group is replaced by -Cl.', '[]', 'Preparation of alkyl chlorides, understanding substitution.', NULL, '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r291', NULL, '10', 'Reaction of Ethanol with SOCl₂', 'C₂H₅OH + SOCl₂ → C₂H₅Cl + SO₂ + HCl', 'organic', '["C₂H₅OH", "SOCl₂"]', '["C₂H₅Cl", "SO₂", "HCl"]', 'Room temperature', 'Thionyl chloride converts ethanol to chloroethane. The byproducts (SO₂ and HCl) are gases, making purification easy.', '[]', 'Preferred method for preparing alkyl chlorides from alcohols.', NULL, '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r292', NULL, '10', 'Dehydration of Ethanol to Ethene', 'C₂H₅OH → C₂H₄ + H₂O', 'organic', '["C₂H₅OH"]', '["C₂H₄", "H₂O"]', 'Conc. H₂SO₄, 170°C', 'Ethanol loses water molecule when heated with concentrated sulfuric acid at 170°C to form ethene. This is intramolecular dehydration.', '[]', 'Laboratory preparation of ethene, understanding elimination reactions.', NULL, '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r293', NULL, '12', 'Benzene Bromination (EAS)', 'C₆H₆ + Br₂ → C₆H₅Br + HBr (AlBr₃ catalyst)', 'organic', '["C₆H₆", "Br₂"]', '["C₆H₅Br", "HBr"]', 'Anhydrous AlBr₃ (Lewis acid)', 'AlBr₃ polarises the Br–Br bond, generating a bromonium species (Br⁺-AlBr₄⁻). This electrophile attacks the benzene π-system, forming a resonance-stabilised arenium (Wheland) intermediate. AlBr₄⁻ then abstracts a proton to restore aromaticity, yielding bromobenzene and HBr. Aromaticity is preserved throughout the substitution rather than addition pathway.', '[]', 'Bromobenzene is an important intermediate in pharmaceutical synthesis and as a precursor to Grignard reagents (C₆H₅MgBr) for C–C bond-forming reactions.', NULL, '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r294', NULL, '12', 'Benzene Chlorination (EAS)', 'C₆H₆ + Cl₂ → C₆H₅Cl + HCl (FeCl₃ catalyst)', 'organic', '["C₆H₆", "Cl₂"]', '["C₆H₅Cl", "HCl"]', 'Anhydrous FeCl₃ or AlCl₃', 'FeCl₃ coordinates to Cl₂ to polarise the Cl–Cl bond, making one Cl atom strongly electrophilic. It attacks the benzene π-system to form an arenium sigma-complex, which then loses H⁺ (taken by FeCl₄⁻) to regenerate aromaticity and yield chlorobenzene. This is a classic electrophilic aromatic substitution.', '[]', 'Chlorobenzene is used to manufacture phenol (via hydrolysis), as a high-boiling solvent, and as a precursor to pharmaceuticals and pesticides.', NULL, '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r295', NULL, '12', 'Benzene Nitration (EAS)', 'C₆H₆ + HNO₃ → C₆H₅NO₂ + H₂O (H₂SO₄ catalyst)', 'organic', '["C₆H₆", "HNO₃"]', '["C₆H₅NO₂", "H₂O"]', 'Mixed acid: conc. HNO₃/conc. H₂SO₄, 50–55°C', 'Conc. H₂SO₄ protonates HNO₃, generating the nitronium ion (NO₂⁺) — the active electrophile. NO₂⁺ attacks the benzene ring forming a resonance-stabilised arenium intermediate across three structures. HSO₄⁻ abstracts H⁺ to restore aromaticity. Temperature is held below 55°C to prevent dinitration.', '[]', 'Nitrobenzene is reduced to aniline — foundation of the synthetic dye and pharmaceutical industries. Also used in polyurethane manufacture via MDI.', NULL, '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r296', NULL, '12', 'Benzene Sulfonation (EAS)', 'C₆H₆ + SO₃ → C₆H₅SO₃H (fuming H₂SO₄)', 'organic', '["C₆H₆", "SO₃"]', '["C₆H₅SO₃H"]', 'Fuming H₂SO₄ (oleum) or SO₃, heat', 'SO₃ (from oleum) is the electrophile — its sulfur atom attacks the benzene π-system. Unlike other EAS reactions, sulfonation is reversible: the –SO₃H group is removed by steam hydrolysis at higher temperatures. This reversibility makes sulfonation invaluable as a temporary blocking group in multi-step synthesis to direct other substituents.', '[]', 'Benzenesulfonic acid is a precursor to saccharin, sulfa drugs, ion-exchange resins, and detergents. Reversibility is exploited in synthetic strategies.', NULL, '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r297', NULL, '12', 'Friedel-Crafts Acylation of Benzene', 'C₆H₆ + CH₃COCl → C₆H₅COCH₃ + HCl (AlCl₃)', 'organic', '["C₆H₆", "CH₃COCl", "AlCl₃"]', '["C₆H₅COCH₃", "HCl"]', 'Anhydrous AlCl₃, room temperature, inert solvent', 'AlCl₃ abstracts Cl⁻ from the acyl chloride to form a resonance-stabilised acylium ion (CH₃C≡O⁺). This electrophile attacks benzene forming a sigma-complex. Loss of H⁺ restores aromaticity yielding acetophenone. Unlike alkylation, acylation does not suffer polysubstitution because –COR is electron-withdrawing and deactivates the ring.', '[]', 'Key route to aromatic ketones (acetophenone, benzophenone). Used in fragrance industry and as precursors to secondary alcohols via reduction.', NULL, '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r298', NULL, '12', 'Benzene Catalytic Hydrogenation', 'C₆H₆ + 3H₂ → C₆H₁₂ (cyclohexane)', 'organic', '["C₆H₆", "H₂"]', '["C₆H₁₂"]', 'Pt, Pd, or Ni catalyst; high pressure H₂, elevated temperature', 'Three equivalents of H₂ are added across all three double bonds of benzene on a metal catalyst surface. Forcing conditions are required because the aromatic resonance energy (~150 kJ/mol) must be overcome. Selective partial hydrogenation to cyclohexene is possible over specialised Ru catalysts with water as modifier (Asahi process).', '[]', 'Cyclohexane is the primary feedstock for nylon-6 and nylon-6,6 manufacture via cyclohexanone and caprolactam/adipic acid.', NULL, '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r299', NULL, '12', 'Birch Reduction of Benzene', 'C₆H₆ + 2Na + 2ROH → 1,4-cyclohexadiene + 2NaOR', 'organic', '["C₆H₆", "Na"]', '["C₆H₈"]', 'Na or Li metal in liquid NH₃ (−33°C), alcohol (ROH) as proton source', 'Alkali metal dissolves in liquid NH₃ to give solvated electrons (e⁻aq). A solvated electron adds to benzene forming a radical anion. Protonation by ROH gives a cyclohexadienyl radical, which accepts another electron to form a carbanion, then is protonated again to give 1,4-cyclohexadiene. Electron-donating substituents direct reduction to unsubstituted positions; electron-withdrawing groups direct reduction to substituted positions.', '[]', 'One of the most powerful methods in total synthesis to access partially unsaturated six-membered rings. Widely used in steroid synthesis and natural product chemistry.', NULL, '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r3', NULL, '12', 'Sandmeyer Reaction', 'C₆H₅N₂⁺Cl⁻ + CuCl → C₆H₅Cl + N₂ + CuCl₂', 'organic', '["C₆H₅NH₂", "HNO₂", "HCl", "CuCl"]', '["C₆H₅Cl", "N₂"]', '0–5°C, then CuCl', 'Aniline is first diazotised with NaNO₂/HCl at 0–5°C to form a diazonium salt. The unstable diazonium ion is then treated with cuprous chloride (CuCl) in a copper-catalysed substitution, replacing the –N₂⁺ group with –Cl while releasing nitrogen gas.', '[]', 'Important method for introducing halogens onto aromatic rings. Used in dye synthesis and pharmaceutical manufacturing.', 'Does not occur at room temperature or higher temperatures (diazonium salt decomposes). Fails without cuprous halide catalyst. Does not work with aliphatic amines (they form unstable diazonium salts that decompose immediately).', '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r30', NULL, '10', 'Decomposition of Lead Nitrate', '2Pb(NO₃)₂ → 2PbO + 4NO₂ + O₂', 'organic', '["Pb(NO₃)₂"]', '["PbO", "NO₂", "O₂"]', 'Heat', 'Colorless lead nitrate crystals decompose on heating to form lead oxide (yellow), brown nitrogen dioxide gas, and oxygen. The brown fumes of NO₂ are characteristic of this reaction.', '[]', 'Used in laboratory preparation of nitrogen dioxide and to demonstrate thermal decomposition of nitrates.', NULL, '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r300', NULL, '12', 'Benzene Photochemical Halogen Addition', 'C₆H₆ + 3Cl₂ → C₆H₆Cl₆ (BHC, benzene hexachloride)', 'organic', '["C₆H₆", "Cl₂"]', '["C₆H₆Cl₆"]', 'UV (hν) light, no Lewis acid catalyst', 'UV irradiation causes homolytic cleavage of Cl₂ to form two Cl• radicals (initiation). Cl• adds across a C=C bond of benzene giving a ring radical, which reacts with another Cl₂ to continue the chain. 1,2,3,4,5,6-Addition across all three double bonds via a radical mechanism (not ionic EAS) gives hexachlorocyclohexane. The γ-isomer (lindane) has insecticidal properties.', '[]', 'The γ-isomer (lindane) was used as an insecticide, now banned due to environmental persistence. Important for contrasting radical addition vs. ionic substitution mechanisms.', NULL, '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r301', NULL, '11', 'Benzene Complete Combustion', '2C₆H₆ + 15O₂ → 12CO₂ + 6H₂O', 'organic', '["C₆H₆", "O₂"]', '["CO₂", "H₂O"]', 'Ignition, excess O₂', 'In excess oxygen, benzene undergoes complete combustion. Benzene burns with a characteristically sooty yellow flame due to its high C:H ratio (1:1), causing incomplete combustion in normal air. Complete combustion requires 7.5 mol O₂ per mol benzene. The reaction is highly exothermic (ΔH°comb ≈ −3268 kJ/mol). Singlet oxygen reduces the activation energy of initiation and accelerates chain-branching mechanisms.', '[]', 'Combustion stoichiometry and thermochemistry of aromatic fuels. Benzene vapour is flammable and a known carcinogen — relevant to fire hazard and environmental pollution assessment.', NULL, '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r302', NULL, '12', 'Benzene Catalytic Oxidation to Maleic Anhydride', 'C₆H₆ + 4.5O₂ → C₄H₂O₃ + 2CO₂ + 2H₂O (V₂O₅, 400–500°C)', 'organic', '["C₆H₆", "O₂"]', '["C₄H₂O₃", "CO₂", "H₂O"]', 'V₂O₅ catalyst, 400–500°C, air', 'Over a V₂O₅ catalyst, benzene undergoes partial oxidation. The ring is cleaved and four carbons become maleic anhydride while two are lost as CO₂. The Mars–van Krevelen mechanism operates: V⁵⁺ oxidises the substrate (V⁵⁺ → V⁴⁺), and O₂ re-oxidises V⁴⁺ back to V⁵⁺. Temperature and contact time are controlled to prevent complete combustion.', '[]', 'Maleic anhydride is used in unsaturated polyester resins (fibreglass), alkyd resins, agricultural chemicals, and as a Diels–Alder dienophile.', NULL, '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r303', NULL, '12', 'Benzene to Phenol (Cumene Process)', 'C₆H₆ + C₃H₆ → C₆H₅CH(CH₃)₂ → C₆H₅OH + CH₃COCH₃', 'organic', '["C₆H₆", "O₂"]', '["C₆H₅OH", "CH₃COCH₃"]', 'Step 1: H₃PO₄/SiO₂; Step 2: Air (O₂); Step 3: Dilute H₂SO₄', 'Step 1: Benzene undergoes acid-catalysed Friedel-Crafts alkylation with propylene to give cumene (isopropylbenzene). Step 2: Cumene is oxidised by air via a free-radical mechanism to cumene hydroperoxide (ROOH). Step 3: H₂SO₄ cleaves the hydroperoxide by Hock rearrangement to give phenol and acetone simultaneously. Both products are commercially valuable.', '[]', '>90% of the world\'s phenol comes from this process. Phenol is used in Bakelite, bisphenol A (polycarbonates), aspirin. Acetone is used as solvent and for PMMA (Perspex) manufacture.', NULL, '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r304', NULL, '12', 'Benzene Ozonolysis', 'C₆H₆ + 3O₃ → 3 glyoxal fragments (workup gives OHC-CHO etc.)', 'organic', '["C₆H₆", "O₃"]', '["OHCCHO"]', 'O₃ in CH₂Cl₂, low temperature; reductive workup (Zn/AcOH) or oxidative workup (H₂O₂)', 'Benzene reacts slowly with ozone (slower than alkenes due to aromatic stabilisation). Each C=C unit of benzene undergoes 1,3-dipolar cycloaddition with O₃ to give a molozonide, which rearranges to a carbonyl oxide/aldehyde pair. Complete ozonolysis of all three bonds and hydrolytic workup cleaves the ring to give glyoxal (OHC-CHO) and glyoxylic acid. In the atmosphere, OH-radical oxidation of benzene leads to ring-opening yielding muconaldehyde.', '[]', 'Rarely used preparatively. Important in atmospheric chemistry — benzene ozonolysis contributes to secondary organic aerosol (SOA) formation and photochemical smog in urban environments.', NULL, '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r305', NULL, '12', 'Benzene Photochemical Dearomatization', 'C₆H₆ + ¹O₂ → benzene oxide / muconaldehyde (hν, sensitiser)', 'organic', '["C₆H₆", "O₂"]', '["C₆H₆O₂"]', 'UV light, photosensitiser (rose bengal), or direct irradiation', 'Under UV irradiation, benzene undergoes dearomative reactions that break the aromatic π-system. Photooxygenation with singlet oxygen (¹O₂) gives benzene 1,2-dioxetane intermediates rearranging to muconaldehyde. Direct photoisomerisation gives highly strained isomers: Dewar benzene, benzvalene, and prismane. These dearomative pathways provide access to 3D building blocks (bicyclic/polycyclic frameworks) inaccessible by ground-state chemistry.', '[]', 'Total synthesis of natural products (terpenoids, alkaloids) to generate molecular complexity from flat rings. Also relevant in understanding photocarcinogenesis of benzene in biological systems.', NULL, '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r306', NULL, '12', 'Benzene Direct C–H Functionalization', 'C₆H₆ + R–X → C₆H₅–R + HX (TM or photoredox catalyst)', 'organic', '["C₆H₆", "O₂"]', '["C₆H₅R"]', 'Transition-metal (Pd, Rh, Ru) or photoredox catalyst, visible light or heat', 'Direct C–H functionalization bypasses the need to pre-halogenate benzene. In TM-catalysed CMD (concerted metalation-deprotonation) mechanism, the metal inserts into the C–H bond giving an arylmetal intermediate that undergoes reductive elimination to form the new C–C or C–X bond. In photoredox pathways, visible light generates benzene radical cation (C₆H₆•⁺) enabling oxidative cross-coupling with a radical partner. Radical–radical cross-coupling gives modular direct arene C–H alkylation.', '[]', 'Atom-economical green chemistry. Growing importance in pharmaceutical manufacturing as an alternative to pre-functionalisation. Direct alkylation of benzene gives alkylbenzenes used in detergents.', NULL, '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r307', NULL, '12', 'Benzene Ring C–C Bond Cleavage (Enzymatic/Catalytic)', 'C₆H₆ + O₂ → catechol → muconic acid (dioxygenase enzymes)', 'organic', '["C₆H₆", "O₂"]', '["OHCCHO"]', 'Enzymatic: dioxygenase enzymes in bacteria; Abiotic: Rh/Fe/Cu catalysts', 'Dioxygenase enzymes in soil bacteria first hydroxylate benzene to benzene-1,2-diol (catechol) using O₂ and NADH. A second dioxygenase cleaves the aromatic ring by inserting both O₂ atoms between the two –OH groups (extradiol or intradiol cleavage), giving cis,cis-muconic acid or 2-hydroxymuconate semialdehyde. Abiotic catalytic ring cleavage has been achieved with specialised Rh, Fe, and Cu complexes in research settings.', '[]', 'Bioremediation of benzene-contaminated soil and groundwater (benzene is a carcinogen). Muconic acid is a bio-based platform chemical for bio-nylon and bio-PET production.', NULL, '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r308', NULL, '12', 'Toluene Benzylic Bromination (Radical)', 'C₆H₅CH₃ + Br₂ → C₆H₅CH₂Br + HBr (hν, CCl₄)', 'organic', '["C₆H₅CH₃", "Br₂"]', '["C₆H₅CH₂Br", "HBr"]', 'UV light or radical initiator (peroxide), CCl₄ solvent, reflux', 'Under photochemical conditions (not Lewis acid, which would give ring bromination), Br• radical selectively abstracts the benzylic H from toluene because the resulting benzyl radical is stabilised by resonance delocalisation into the π-system. The benzyl radical then reacts with Br₂ to give benzyl bromide and regenerate Br•, propagating the chain. NBS (N-bromosuccinimide) is a milder and more selective alternative reagent.', '[]', 'Benzyl bromide is a versatile electrophile for SN2 reactions, used for benzyl protecting groups in sugar/amino acid chemistry, and as a building block in pharmaceutical and fragrance synthesis.', NULL, '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r309', NULL, '12', 'Benzene Dearomative Partial Reduction (Crich/SmI₂)', 'C₆H₆ → 1,3-cyclohexadiene or 1,4-cyclohexadiene (controlled conditions)', 'organic', '["C₆H₆", "H₂"]', '["C₆H₈"]', 'SmI₂/proton source, or dissolving metal with controlled stoichiometry', 'Beyond classical Birch reduction, dearomative partial reductions of benzene using SmI₂ or controlled dissolving-metal conditions can selectively give 1,3-cyclohexadiene (conjugated) in addition to the classical 1,4-isomer. Selectivity depends on relative acidities of proton donors and stability of radical anion intermediates. Recent ammonia-free Birch-type reductions use silanes or boron hydrides as H-donors under photoredox catalysis, avoiding hazardous liquid NH₃ and alkali metals.', '[]', '1,3-Cyclohexadiene is a valuable diene for Diels–Alder cycloadditions. 1,4-Cyclohexadiene is used in steroid and natural product total synthesis.', NULL, '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r31', NULL, '9', 'Zinc with Copper Sulfate', 'Zn + CuSO₄ → ZnSO₄ + Cu', 'organic', '["Zn", "CuSO₄"]', '["ZnSO₄", "Cu"]', 'Aqueous solution, room temperature', 'More reactive zinc displaces copper from copper sulfate solution. The blue color of copper sulfate fades as colorless zinc sulfate forms, and reddish-brown copper metal deposits on the zinc strip. This proves zinc is more reactive than copper.', '[]', 'Used in metallurgy for extraction of metals, in electric batteries (Daniell cell), and to demonstrate the reactivity series of metals.', 'Does not occur if zinc is coated with oxide/grease (surface must be clean). Fails with solid CuSO₄ (needs aqueous solution). Does not occur with less reactive metals than copper (Ag, Au). Reverse reaction (Cu + ZnSO₄) does not occur.', '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r310', NULL, '12', 'Benzene Iodination (EAS)', 'C₆H₆ + I₂ → C₆H₅I + HI (HNO₃ or HIO₃ oxidant)', 'organic', '["C₆H₆", "I₂"]', '["C₆H₅I", "HI"]', 'I₂ with oxidising agent (HNO₃, HIO₃, or H₂O₂); or I₂/Lewis acid (ICl)', 'Iodine alone is too weak an electrophile to carry out EAS on benzene because iodination is thermodynamically reversible and the Wheland intermediate is not stabilised enough to lose HI. An oxidising agent (HNO₃, HIO₃) is required to drive the reaction forward by oxidising the HI byproduct or by generating a more reactive iodonium species (I⁺). Alternatively, ICl (iodine monochloride) with a Lewis acid generates a more reactive I⁺ species.', '[]', 'Iodobenzene is an important partner in palladium-catalysed cross-coupling reactions (Heck, Suzuki, Sonogashira) — key methods in pharmaceutical and material synthesis.', NULL, '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r311', NULL, '12', 'Nucleophilic Aromatic Substitution (NAS) on Nitrobenzene', '2,4-dinitrochlorobenzene + OH⁻ → 2,4-dinitrophenol + Cl⁻ (SNAr)', 'organic', '["C₆H₅NO₂", "NaOH"]', '["C₆H₅OH", "NaNO₂"]', 'Strongly electron-withdrawing groups on ring (NO₂), nucleophile (OH⁻, NH₃, RNH₂), heat', 'Unlike EAS, nucleophilic aromatic substitution (SNAr) proceeds by addition-elimination (Meisenheimer complex mechanism). A nucleophile (Nu⁻) attacks the ipso carbon bearing the leaving group (e.g., Cl), forming a negatively charged Meisenheimer complex stabilised by electron-withdrawing groups (NO₂) at ortho/para positions. The leaving group (Cl⁻) then departs to restore aromaticity. Multiple electron-withdrawing groups greatly activate the ring toward Nu attack.', '[]', 'SNAr is crucial in synthesis of pharmaceuticals and agrochemicals with heteroatom substituents. Used to introduce –OH, –OR, –NR₂, –SR groups onto electron-poor arenes.', NULL, '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r312', NULL, '12', 'Benzene Friedel-Crafts Alkylation with Chloromethane', 'C₆H₆ + CH₃Cl → C₆H₅CH₃ + HCl (AlCl₃ catalyst)', 'organic', '["C₆H₆", "CH₃Cl", "AlCl₃"]', '["C₆H₅CH₃", "HCl"]', 'Anhydrous AlCl₃, room temperature', 'AlCl₃ acts as a Lewis acid and polarizes the C–Cl bond in chloromethane, generating a methyl carbocation (CH₃⁺) or polarized complex. This electrophile attacks the electron-rich benzene ring, forming a sigma complex (arenium ion). Loss of a proton restores aromaticity, yielding toluene. This is the fundamental Friedel-Crafts alkylation reaction for introducing alkyl groups to benzene.', '[]', 'Industrial synthesis of toluene from benzene. Toluene is a key starting material for TNT, benzoic acid, benzaldehyde, and polyurethane production.', NULL, '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r313', NULL, '12', 'Benzene Methylation (Methane to Toluene)', 'C₆H₆ + CH₄ → C₆H₅CH₃ + H₂', 'organic', '["C₆H₆", "CH₄"]', '["C₆H₅CH₃", "H₂"]', 'High temperature (600-700°C), metal catalyst (Pt, Mo, or ZnO-Al₂O₃), pressure', 'Direct methylation of benzene with methane is a challenging reaction due to the high stability of methane. At high temperatures with metal catalysts, methane undergoes C–H activation to generate methyl radicals or surface-bound methyl species. These attack the benzene ring, displacing hydrogen to form toluene. This represents a direct C–H functionalization approach using abundant methane as the methyl source.', '[]', 'Emerging green chemistry route to toluene using methane (natural gas) instead of chloromethane. Reduces chloride waste and uses abundant feedstock. Research focus for sustainable chemical synthesis.', NULL, '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r314', NULL, '12', 'Benzene Hydrodealkylation (Reverse: Toluene to Benzene + Methane)', 'C₆H₅CH₃ + H₂ → C₆H₆ + CH₄', 'organic', '["C₆H₅CH₃", "H₂"]', '["C₆H₆", "CH₄"]', 'High temperature (500-600°C), hydrogen pressure (20-50 atm), Cr₂O₃ or MoO₃ catalyst', 'Hydrodealkylation is the reverse of methylation. Toluene reacts with hydrogen at high temperature over a metal oxide catalyst. The methyl group is removed as methane, regenerating benzene. This is an important industrial process for converting toluene (often in excess) back to benzene when benzene demand is high. The reaction proceeds via radical or surface-mediated C–C bond cleavage.', '[]', 'Industrial process to produce benzene from toluene when benzene prices are high relative to toluene. Used in petroleum refineries and petrochemical plants for benzene-toluene-xylene (BTX) interconversion.', NULL, '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r315', NULL, '12', 'Benzene Steam Reforming with Methane', 'C₆H₆ + CH₄ + H₂O → C₆H₅CH₃ + CO + 2H₂', 'organic', '["C₆H₆", "CH₄", "H₂O"]', '["CO", "H₂", "C₆H₅CH₃"]', 'High temperature (800-900°C), Ni catalyst, steam', 'In this combined reforming and methylation process, methane and steam react with benzene. The steam reforming of methane generates syngas (CO + H₂), while the methyl species from methane activate benzene to form toluene. This complex process represents an integrated approach to utilize both aromatic and aliphatic hydrocarbons from natural gas and petroleum feedstocks.', '[]', 'Advanced petrochemical processing for integrated BTX and syngas production. Potential route for utilizing natural gas and benzene together in chemical plants.', NULL, '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r316', NULL, '11', 'Benzene Nitration (Standard NCERT)', 'C₆H₆ + HNO₃ → C₆H₅NO₂ + H₂O (conc. H₂SO₄)', 'organic', '["C₆H₆", "HNO₃"]', '["C₆H₅NO₂", "H₂O"]', 'Conc. HNO₃ + Conc. H₂SO₄ (mixed acid), 50-60°C', 'This is the standard nitration reaction of benzene as per NCERT curriculum. Concentrated sulfuric acid acts as a catalyst and dehydrating agent, generating the nitronium ion (NO₂⁺) electrophile from nitric acid. The NO₂⁺ attacks the benzene ring in an electrophilic aromatic substitution, forming nitrobenzene. The reaction is kept below 60°C to prevent dinitration.', '[]', 'Laboratory and industrial preparation of nitrobenzene. Nitrobenzene is reduced to aniline, which is the starting material for dyes, drugs, and explosives.', NULL, '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r317', NULL, '11', 'Benzene Sulfonation (Standard NCERT)', 'C₆H₆ + H₂SO₄ → C₆H₅SO₃H + H₂O', 'organic', '["C₆H₆", "H₂SO₄"]', '["C₆H₅SO₃H", "H₂O"]', 'Conc. H₂SO₄ or fuming H₂SO₄ (oleum), heat', 'Benzene reacts with concentrated sulfuric acid to form benzenesulfonic acid. The electrophile is sulfur trioxide (SO₃) or protonated sulfuric acid. This is a reversible reaction - sulfonation can be reversed by heating with steam. The sulfonic acid group is electron-withdrawing and meta-directing in further substitutions.', '[]', 'Preparation of benzenesulfonic acid for detergents, dyes, and ion-exchange resins. The reversible nature is used in synthetic strategies.', NULL, '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r318', NULL, '11', 'Benzene Halogenation with Cl₂ (Standard NCERT)', 'C₆H₆ + Cl₂ → C₆H₅Cl + HCl (FeCl₃ or AlCl₃)', 'organic', '["C₆H₆", "Cl₂"]', '["C₆H₅Cl", "HCl"]', 'Anhydrous FeCl₃ or AlCl₃ catalyst, room temperature', 'Chlorine reacts with benzene in the presence of a Lewis acid catalyst (FeCl₃ or AlCl₃) to form chlorobenzene. The catalyst polarizes the Cl–Cl bond, generating Cl⁺ electrophile. This is electrophilic aromatic substitution where one hydrogen is replaced by chlorine. The HCl byproduct is formed when the catalyst abstracts a proton from the sigma complex.', '[]', 'Industrial production of chlorobenzene, used to make phenol, DDT, and aniline. Important intermediate in organic synthesis.', NULL, '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r319', NULL, '11', 'Benzene Halogenation with Br₂ (Standard NCERT)', 'C₆H₆ + Br₂ → C₆H₅Br + HBr (FeBr₃ or AlBr₃)', 'organic', '["C₆H₆", "Br₂"]', '["C₆H₅Br", "HBr"]', 'Anhydrous FeBr₃, AlBr₃, or Lewis acid catalyst', 'Bromine reacts with benzene in presence of Lewis acid catalyst to form bromobenzene. The mechanism is similar to chlorination - the catalyst generates Br⁺ electrophile which attacks the benzene ring. The reaction is slower than chlorination and requires a catalyst. Without catalyst, bromine does not react with benzene at room temperature.', '[]', 'Preparation of bromobenzene for Grignard reagents, pharmaceuticals, and dyes. Used as a solvent and intermediate in organic synthesis.', NULL, '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r32', NULL, '9', 'Iron with Copper Sulfate', 'Fe + CuSO₄ → FeSO₄ + Cu', 'organic', '["Fe", "CuSO₄"]', '["FeSO₄", "Cu"]', 'Aqueous solution', 'Iron being more reactive than copper displaces it from copper sulfate solution. The blue solution turns pale green due to formation of iron(II) sulfate, and copper gets deposited on the iron nail. This is the basis of the \'copper plating\' experiment.', '[]', 'Used in extraction of less reactive metals, in electroplating, and to demonstrate metal reactivity series in classroom experiments.', 'Does not occur with solid CuSO₄ (needs aqueous solution). Fails if iron is coated with grease/paint. Does not occur with less reactive metals (Cu, Ag, Au). Reverse reaction (Cu + FeSO₄) does not occur.', '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r320', NULL, '11', 'Benzene Hydrogenation to Cyclohexane (Standard NCERT)', 'C₆H₆ + 3H₂ → C₆H₁₂ (cyclohexane)', 'organic', '["C₆H₆", "H₂"]', '["C₆H₁₂"]', 'Ni, Pt, or Pd catalyst, 200-300°C, high pressure', 'Benzene undergoes catalytic hydrogenation to form cyclohexane. Three molecules of hydrogen add across the three double bonds. This is an addition reaction (not substitution) where the aromatic character is lost. High temperature and pressure are needed to overcome the resonance stabilization energy of benzene (~150 kJ/mol).', '[]', 'Industrial production of cyclohexane, which is oxidized to cyclohexanone and adipic acid for nylon-6,6 production. Major industrial process.', NULL, '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r321', NULL, '11', 'Benzene Addition with Chlorine (UV Light)', 'C₆H₆ + 3Cl₂ → C₆H₆Cl₆ (Benzene hexachloride, BHC)', 'organic', '["C₆H₆", "Cl₂"]', '["C₆H₆Cl₆"]', 'UV light or sunlight, no catalyst', 'In presence of UV light (not Lewis acid catalyst), chlorine adds to benzene rather than substituting. This is a free radical addition reaction across all three double bonds, forming benzene hexachloride (BHC). The gamma isomer is called lindane, an insecticide. This reaction demonstrates how conditions determine substitution vs addition.', '[]', 'Production of BHC (lindane) as an insecticide. Important example of photochemical addition to aromatic rings.', NULL, '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r322', NULL, '11', 'Benzene Combustion (Standard NCERT)', '2C₆H₆ + 15O₂ → 12CO₂ + 6H₂O', 'organic', '["C₆H₆", "O₂"]', '["CO₂", "H₂O"]', 'Ignition, excess oxygen', 'Benzene undergoes complete combustion in excess oxygen to form carbon dioxide and water. Due to its high carbon content (C:H = 1:1), benzene burns with a sooty yellow flame. The reaction is highly exothermic. Incomplete combustion produces carbon (soot) and carbon monoxide.', '[]', 'Demonstrates the high carbon content of aromatic hydrocarbons. Important for understanding air pollution from aromatic fuel combustion.', NULL, '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r33', NULL, '10', 'Aluminium with Iron Oxide', '2Al + Fe₂O₃ → Al₂O₃ + 2Fe', 'organic', '["Al", "Fe₂O₃"]', '["Al₂O₃", "Fe"]', 'Ignition by magnesium ribbon', 'This is the thermite reaction. Aluminium being more reactive than iron reduces iron oxide to molten iron. The reaction is highly exothermic and produces temperatures around 2500°C, sufficient to melt the iron produced.', '[]', 'Used for welding railway tracks, repairing heavy machinery, and in incendiary devices. Also used to extract pure metals from their oxides.', 'Does not occur at room temperature (requires high activation energy). Fails without ignition source (Mg ribbon). Does not occur with wet aluminum (oxide layer prevents reaction). Powdered aluminum required - solid pieces won\'t react.', '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r34', NULL, '9', 'Barium Chloride with Sodium Sulfate', 'BaCl₂ + Na₂SO₄ → BaSO₄ + 2NaCl', 'organic', '["BaCl₂", "Na₂SO₄"]', '["BaSO₄", "NaCl"]', 'Aqueous solution', 'When barium chloride and sodium sulfate solutions are mixed, a white precipitate of barium sulfate forms. This is a double displacement reaction where the ions exchange partners. BaSO₄ is insoluble in water and acids.', '[]', 'Used as a test for sulfate ions (SO₄²⁻) in qualitative analysis. Barium sulfate is used in X-ray imaging (barium meal) due to its insolubility.', 'Does not occur with solid reactants (need aqueous solutions). Fails with soluble sulfates that form complexes. Does not occur if BaCl₂ solution is acidic (different products). Requires ionic form of both compounds.', '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r35', NULL, '9', 'Silver Nitrate with Sodium Chloride', 'AgNO₃ + NaCl → AgCl + NaNO₃', 'organic', '["AgNO₃", "NaCl"]', '["AgCl", "NaNO₃"]', 'Aqueous solution', 'Silver nitrate reacts with sodium chloride to form a curdy white precipitate of silver chloride. This is a double displacement reaction and a precipitation reaction. AgCl turns grey in sunlight due to decomposition.', '[]', 'Used as a test for chloride ions (Cl⁻) in qualitative analysis. Silver chloride is used in photographic films due to its light sensitivity.', 'Does not occur with solid reactants (need aqueous solutions). Fails with complex chlorides that don\'t dissociate. Does not occur in presence of strong ammonia (forms complex). Requires free Cl⁻ ions.', '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r36', NULL, '10', 'Lead Nitrate with Potassium Iodide', 'Pb(NO₃)₂ + 2KI → PbI₂ + 2KNO₃', 'organic', '["Pb(NO₃)₂", "KI"]', '["PbI₂", "KNO₃"]', 'Aqueous solution', 'When colorless lead nitrate and potassium iodide solutions are mixed, a bright yellow precipitate of lead iodide forms. This \'golden rain\' experiment is a classic double displacement reaction. The precipitate dissolves on heating and recrystallizes on cooling.', '[]', 'Used as a test for lead(II) ions or iodide ions. Lead iodide is used in solar cells and as a pigment.', 'Does not occur with solid reactants (need aqueous solutions). Fails with excess KI (forms soluble complex). Does not occur with lead(IV) compounds. Requires 2:1 ratio of KI to Pb(NO₃)₂.', '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r37', NULL, '10', 'HCl with NaOH', 'HCl + NaOH → NaCl + H₂O', 'organic', '["HCl", "NaOH"]', '["NaCl", "H₂O"]', 'Aqueous solution', 'Hydrochloric acid (strong acid) reacts with sodium hydroxide (strong base) to form sodium chloride (salt) and water. This is a neutralization reaction where H⁺ from acid combines with OH⁻ from base to form water. The solution becomes neutral (pH 7).', '[]', 'Used in antacid tablets, treatment of acidic soil, and in chemical industries to produce salts. Also used to adjust pH in swimming pools.', 'Does not occur in non-aqueous solvents (no free H⁺/OH⁻ ions). Fails if one reactant is in solid state (needs dissolution). Does not occur with insoluble bases like Cu(OH)₂ (slow reaction). Requires ionic form of reactants.', '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r38', NULL, '10', 'Sulfuric Acid with Copper Oxide', 'H₂SO₄ + CuO → CuSO₄ + H₂O', 'organic', '["H₂SO₄", "CuO"]', '["CuSO₄", "H₂O"]', 'Warm conditions', 'Black copper oxide dissolves in dilute sulfuric acid to form blue copper sulfate solution and water. This is a neutralization reaction between a basic oxide and an acid. The color change from black to blue indicates the reaction.', '[]', 'Used to prepare copper sulfate crystals, in electroplating, and as a fungicide in agriculture.', 'Does not occur with concentrated H₂SO₄ (different reaction, SO₂ produced). Fails with copper metal (needs oxidation). Does not occur at room temperature (needs warming). Requires dilute acid, not concentrated.', '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r39', NULL, '10', 'Acetic Acid with Sodium Hydroxide', 'CH₃COOH + NaOH → CH₃COONa + H₂O', 'organic', '["CH₃COOH", "NaOH"]', '["CH₃COONa", "H₂O"]', 'Aqueous solution', 'Weak acetic acid (vinegar) reacts with strong sodium hydroxide to form sodium acetate and water. This is a neutralization reaction. The heat released is less than strong acid-strong base neutralization due to weak acid.', '[]', 'Used in food preservation, buffer solutions, and in the production of dyes and pharmaceuticals.', NULL, '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r4', NULL, '12', 'Rosenmund Reduction', 'CH₃COCl + H₂ → CH₃CHO + HCl (Pd/BaSO₄)', 'organic', '["CH₃COCl", "H₂"]', '["CH₃CHO", "HCl"]', 'Pd/BaSO₄, H₂ gas, toluene', 'The acid chloride is hydrogenated over a poisoned palladium catalyst (Pd on BaSO₄). The catalyst is partially deactivated by BaSO₄ and quinoline to prevent over-reduction to the alcohol. One mole of H₂ selectively reduces the –COCl to –CHO, releasing HCl.', '[]', 'Selective synthesis of aldehydes from acid chlorides. The poisoning prevents full reduction. Used in fine chemicals and fragrance industry.', 'Does not occur without catalyst poisoning (over-reduction to alcohol occurs). Fails with unpoisoned Pd catalyst. Does not work with formyl chloride (unstable). Reaction stops at aldehyde stage only with proper catalyst poisoning.', '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r40', NULL, '9', 'Combustion of Hydrogen', '2H₂ + O₂ → 2H₂O', 'organic', '["H₂", "O₂"]', '["H₂O"]', 'Ignition/spark', 'Hydrogen burns in oxygen with a pale blue flame to form water. This is a highly exothermic combustion reaction. The \'pop\' sound when burning hydrogen is used as a test for hydrogen gas. The reaction releases large amounts of energy.', '[]', 'Used in oxy-hydrogen torches for cutting and welding metals. Hydrogen fuel cells use this reaction to generate electricity for vehicles.', 'Does not occur at room temperature without spark (kinetically stable mixture). Fails with limited oxygen (incomplete combustion). Does not occur with inert gases. Requires 2:1 H₂:O₂ ratio for complete combustion.', '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r41', NULL, '9', 'Combustion of Sulfur', 'S + O₂ → SO₂', 'organic', '["S", "O₂"]', '["SO₂"]', 'Burning', 'Sulfur burns in oxygen with a blue flame to form sulfur dioxide gas. This is a combustion reaction. SO₂ has a choking smell of burning sulfur and is acidic in nature, turning moist litmus paper red.', '[]', 'Used in the manufacture of sulfuric acid (Contact process), as a preservative in dried fruits, and in bleaching wool and silk.', NULL, '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r42', NULL, '9', 'Combustion of Magnesium', '2Mg + O₂ → 2MgO', 'organic', '["Mg", "O₂"]', '["MgO"]', 'Burning', 'Magnesium burns with a dazzling white flame in oxygen, forming magnesium oxide. This combustion reaction releases very bright light and is used in flash photography and fireworks. The white ash formed is basic magnesium oxide.', '[]', 'Used in flash powders, fireworks, and emergency flares. Magnesium oxide is used as a refractory material and antacid.', NULL, '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r43', NULL, '10', 'Zinc with Dilute HCl', 'Zn + 2HCl → ZnCl₂ + H₂', 'organic', '["Zn", "HCl"]', '["ZnCl₂", "H₂"]', 'Room temperature', 'Zinc metal reacts with dilute hydrochloric acid to form zinc chloride and hydrogen gas. Bubbles of hydrogen gas are evolved. This is a single displacement reaction where zinc displaces hydrogen from the acid. Zinc is above hydrogen in the reactivity series.', '[]', 'Used in laboratory preparation of hydrogen gas. The reactivity of metals with acids is used to determine their position in the reactivity series.', 'Does not occur with concentrated HCl (different reaction pathway). Fails with copper, silver, gold (below hydrogen in reactivity series). Does not occur if zinc surface is passivated. Lead reacts slowly due to insoluble PbCl₂ coating.', '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r44', NULL, '10', 'Iron with Dilute HCl', 'Fe + 2HCl → FeCl₂ + H₂', 'organic', '["Fe", "HCl"]', '["FeCl₂", "H₂"]', 'Room temperature', 'Iron reacts slowly with dilute hydrochloric acid to form ferrous chloride (light green solution) and hydrogen gas. The reaction is less vigorous than zinc. This confirms iron is less reactive than zinc but more reactive than hydrogen.', '[]', 'Used to demonstrate the reactivity series and to prepare ferrous salts. Iron containers should not be used to store acids.', 'Does not occur with concentrated HCl (forms FeCl₃). Fails with oxidizing acids (HNO₃, concentrated H₂SO₄). Does not occur if iron is rusted (oxide layer protects). Very slow with cold dilute acid.', '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r45', NULL, '10', 'Magnesium with Dilute HCl', 'Mg + 2HCl → MgCl₂ + H₂', 'organic', '["Mg", "HCl"]', '["MgCl₂", "H₂"]', 'Room temperature', 'Magnesium reacts vigorously with dilute hydrochloric acid, producing magnesium chloride and hydrogen gas. The reaction is highly exothermic. Magnesium is highly reactive and displaces hydrogen rapidly from acids.', '[]', 'Used to prepare hydrogen gas in laboratories. The vigorous reaction demonstrates the high position of magnesium in the reactivity series.', 'Does not occur with concentrated HNO₃ (passivation, NO₂ formed). Fails with very dilute acid (slow). Does not occur if magnesium is coated with oxide (needs cleaning). Reaction stops if acid is consumed.', '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r46', NULL, '10', 'Aluminium with Dilute HCl', '2Al + 6HCl → 2AlCl₃ + 3H₂', 'organic', '["Al", "HCl"]', '["AlCl₃", "H₂"]', 'Room temperature (after removing oxide layer)', 'Aluminium reacts with dilute hydrochloric acid to form aluminium chloride and hydrogen gas. Initially, the reaction may be slow due to the protective oxide layer, but once removed, the reaction proceeds vigorously. Aluminium is more reactive than it appears due to this protective layer.', '[]', 'Used in the production of hydrogen and aluminium salts. Important in understanding why aluminium is corrosion-resistant despite being highly reactive.', NULL, '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r47', NULL, '10', 'Zinc with Dilute H₂SO₄', 'Zn + H₂SO₄ → ZnSO₄ + H₂', 'organic', '["Zn", "H₂SO₄"]', '["ZnSO₄", "H₂"]', 'Room temperature', 'Zinc reacts with dilute sulfuric acid to form zinc sulfate (colorless solution) and hydrogen gas. This is similar to the reaction with HCl. The hydrogen gas can be collected and tested with a burning splint.', '[]', 'Laboratory preparation of hydrogen gas. Zinc sulfate is used as a dietary supplement and in agriculture as a fertilizer.', NULL, '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r48', NULL, '10', 'Iron with Dilute H₂SO₄', 'Fe + H₂SO₄ → FeSO₄ + H₂', 'organic', '["Fe", "H₂SO₄"]', '["FeSO₄", "H₂"]', 'Room temperature', 'Iron reacts with dilute sulfuric acid to form ferrous sulfate (pale green solution) and hydrogen gas. The reaction is moderate in speed. Concentrated sulfuric acid would produce different products (SO₂ instead of H₂).', '[]', 'Used to prepare ferrous sulfate (green vitriol) which is used as a fertilizer, in water treatment, and as a dietary supplement for iron.', NULL, '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r49', NULL, '10', 'Magnesium with Dilute H₂SO₄', 'Mg + H₂SO₄ → MgSO₄ + H₂', 'organic', '["Mg", "H₂SO₄"]', '["MgSO₄", "H₂"]', 'Room temperature', 'Magnesium reacts vigorously with dilute sulfuric acid, producing magnesium sulfate (Epsom salt) and hydrogen gas. The reaction is highly exothermic and produces hydrogen rapidly.', '[]', 'Magnesium sulfate is used as Epsom salt for medicinal purposes, in agriculture as a fertilizer, and in fireproofing.', NULL, '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r5', NULL, '12', 'Clemmensen Reduction', 'CH₃COCH₃ + 4[H] → CH₃CH₂CH₃ + H₂O (Zn-Hg, conc. HCl)', 'organic', '["CH₃COCH₃", "Zn"]', '["CH₃CH₂CH₃", "ZnO"]', 'Zn amalgam, conc. HCl, reflux', 'The carbonyl group (C=O) of a ketone is reduced to a methylene group (–CH₂–) using zinc amalgam in concentrated HCl. The zinc surface generates nascent hydrogen which attacks the carbonyl. Water is eliminated and the C=O is replaced by C–H bonds, lowering oxidation state by two.', '[]', 'Reduces ketones to alkanes without affecting C=C double bonds. Used in steroid synthesis and conversion of Friedel-Crafts ketones to alkylbenzenes.', 'Does not occur with acid-sensitive functional groups (esters, ethers, acetals). Fails with phenols (decomposition occurs). Not suitable for pyridine derivatives. Does not work with concentrated H₂SO₄ instead of HCl.', '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r50', NULL, '10', 'Sodium with Cold Water', '2Na + 2H₂O → 2NaOH + H₂', 'organic', '["Na", "H₂O"]', '["NaOH", "H₂"]', 'Room temperature', 'Sodium reacts vigorously with cold water, forming sodium hydroxide and hydrogen gas. The reaction is highly exothermic. Sodium melts into a silvery ball that darts around on the water surface. The solution turns pink with phenolphthalein, showing it is alkaline.', '[]', 'Demonstrates the high reactivity of alkali metals. Used to prepare sodium hydroxide and hydrogen. Caution: Sodium must be handled carefully due to violent reaction.', 'Does not occur with heavy metals (Cu, Ag, Au - no reaction). Fails with hot water (reaction too violent, explosion risk). Does not occur if sodium is coated with oxide (must be freshly cut). Kerosene-protected sodium must be cleaned before use.', '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r51', NULL, '10', 'Calcium with Cold Water', 'Ca + 2H₂O → Ca(OH)₂ + H₂', 'organic', '["Ca", "H₂O"]', '["Ca(OH)₂", "H₂"]', 'Room temperature', 'Calcium reacts less vigorously than sodium with cold water, forming calcium hydroxide (limewater) and hydrogen gas. The reaction produces enough heat to make hydrogen burn with a orange-red flame. Calcium hydroxide solution is weakly alkaline.', '[]', 'Used to prepare calcium hydroxide (slaked lime) and demonstrate the reactivity of alkaline earth metals. Less violent than sodium reaction.', NULL, '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r52', NULL, '10', 'Magnesium with Hot Water', 'Mg + 2H₂O → Mg(OH)₂ + H₂', 'organic', '["Mg", "H₂O"]', '["Mg(OH)₂", "H₂"]', 'Hot water/Steam', 'Magnesium reacts slowly with cold water but reacts readily with hot water or steam to form magnesium hydroxide and hydrogen gas. This shows magnesium is less reactive than calcium but still reacts with water when heated. The reaction is used to demonstrate steam reactions.', '[]', 'Demonstrates the relative reactivity of metals with water. Magnesium hydroxide is used as an antacid (milk of magnesia).', NULL, '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r53', NULL, '10', 'Iron with Steam', '3Fe + 4H₂O → Fe₃O₄ + 4H₂', 'organic', '["Fe", "H₂O"]', '["Fe₃O₄", "H₂"]', 'Red hot iron + steam', 'When red-hot iron is passed over steam, it reacts to form tri-iron tetroxide (magnetite, Fe₃O₄) and hydrogen gas. This reaction shows that iron can react with steam but not with cold or hot water. The reaction is reversible.', '[]', 'Used in the Haber process to produce hydrogen. Demonstrates that iron is less reactive than magnesium, calcium, and sodium.', NULL, '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r54', NULL, '10', 'Copper with Concentrated H₂SO₄', 'Cu + 2H₂SO₄ → CuSO₄ + SO₂ + 2H₂O', 'organic', '["Cu", "H₂SO₄"]', '["CuSO₄", "SO₂", "H₂O"]', 'Heat', 'Copper, being below hydrogen in the reactivity series, does not react with dilute acids. However, with hot concentrated sulfuric acid, copper is oxidized to copper sulfate, and sulfuric acid is reduced to sulfur dioxide. Brown fumes of SO₂ are evolved.', '[]', 'Used to prepare copper sulfate in laboratories. Demonstrates the oxidizing nature of concentrated sulfuric acid.', NULL, '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r55', NULL, '10', 'Zinc with Concentrated H₂SO₄', 'Zn + 2H₂SO₄ → ZnSO₄ + SO₂ + 2H₂O', 'organic', '["Zn", "H₂SO₄"]', '["ZnSO₄", "SO₂", "H₂O"]', 'Heat', 'With concentrated sulfuric acid, zinc produces sulfur dioxide gas instead of hydrogen. The hot concentrated acid acts as an oxidizing agent, oxidizing zinc to zinc sulfate while itself getting reduced to SO₂. This is different from the reaction with dilute acid.', '[]', 'Demonstrates the dual nature of sulfuric acid - as an acid with dilute solutions and as an oxidizing agent when concentrated.', NULL, '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r56', NULL, '10', 'Sodium Oxide with Water', 'Na₂O + H₂O → 2NaOH', 'organic', '["Na₂O", "H₂O"]', '["NaOH"]', 'Room temperature', 'Sodium oxide reacts vigorously with water to form sodium hydroxide (caustic soda). The reaction is highly exothermic. The resulting solution is strongly alkaline and turns red litmus blue and phenolphthalein pink.', '[]', 'Used to prepare sodium hydroxide. Demonstrates that basic oxides of active metals react with water to form strong bases.', NULL, '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r57', NULL, '10', 'Potassium Oxide with Water', 'K₂O + H₂O → 2KOH', 'organic', '["K₂O", "H₂O"]', '["KOH"]', 'Room temperature', 'Potassium oxide reacts vigorously with water to form potassium hydroxide (caustic potash). The reaction is similar to sodium oxide but even more vigorous. The solution is strongly alkaline.', '[]', 'Used to prepare potassium hydroxide, which is used in making soft soaps, alkaline batteries, and as a laboratory reagent.', NULL, '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r58', NULL, '10', 'Carbon Dioxide with Water', 'CO₂ + H₂O ⇌ H₂CO₃', 'organic', '["CO₂", "H₂O"]', '["H₂CO₃"]', 'Room temperature', 'Carbon dioxide dissolves in water to form carbonic acid, a weak acid. This is a reversible reaction. The acid turns blue litmus slightly red. Carbonic acid is unstable and decomposes back to CO₂ and water when heated.', '[]', 'Explains why rainwater is slightly acidic. Carbonic acid is found in carbonated drinks. Important in the carbon cycle and ocean acidification.', NULL, '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r59', NULL, '10', 'Sulfur Dioxide with Water', 'SO₂ + H₂O ⇌ H₂SO₃', 'organic', '["SO₂", "H₂O"]', '["H₂SO₃"]', 'Room temperature', 'Sulfur dioxide dissolves in water to form sulfurous acid. This is a reversible reaction. Sulfurous acid is a weak acid that turns blue litmus red. It acts as a reducing agent and is used as a preservative.', '[]', 'Used as a preservative in jams and dried fruits. Sulfurous acid and its salts (sulfites) prevent oxidation and bacterial growth in food.', NULL, '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r6', NULL, '11', 'Etard Reaction', 'C₆H₅CH₃ + [O] → C₆H₅CHO (CrO₂Cl₂, CS₂)', 'organic', '["C₆H₅CH₃", "K₂Cr₂O₇"]', '["C₆H₅CHO", "Cr₂O₃"]', 'Chromyl chloride CrO₂Cl₂, CS₂', 'The methyl group of toluene is oxidised directly to an aldehyde using chromyl chloride in carbon disulfide. A chromium ester complex (Etard complex) forms first, then is hydrolysed to give benzaldehyde. This is selective — the ring is unaffected.', '[]', 'Selective oxidation of methyl groups on aromatic rings to aldehydes. Useful in perfumery (benzaldehyde synthesis).', 'Does not occur with methoxy or amino substituted toluenes (side reactions dominate). Fails with nitro-substituted toluenes. Does not oxidize tertiary alkyl groups. Requires careful control to prevent over-oxidation to acids.', '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r60', NULL, '10', 'Sulfur Trioxide with Water', 'SO₃ + H₂O → H₂SO₄', 'organic', '["SO₃", "H₂O"]', '["H₂SO₄"]', 'Room temperature', 'Sulfur trioxide reacts vigorously with water to form sulfuric acid. This is a highly exothermic reaction. Sulfuric acid is a strong acid and is called the \'king of chemicals\' due to its extensive industrial use.', '[]', 'This is the final step in the Contact process for manufacturing sulfuric acid. Sulfuric acid is used in fertilizers, dyes, detergents, and many industrial processes.', NULL, '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r61', NULL, '10', 'CO₂ with Calcium Hydroxide', 'CO₂ + Ca(OH)₂ → CaCO₃ + H₂O', 'organic', '["CO₂", "Ca(OH)₂"]', '["CaCO₃", "H₂O"]', 'Room temperature', 'Carbon dioxide reacts with calcium hydroxide (limewater) to form calcium carbonate (white precipitate) and water. This is the test for CO₂ gas - limewater turns milky. If excess CO₂ is passed, the precipitate dissolves forming calcium bicarbonate.', '[]', 'Used as a test for carbon dioxide gas. Also used in water softening and in the manufacture of cement and glass.', NULL, '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r62', NULL, '10', 'CO₂ with Sodium Hydroxide', '2NaOH + CO₂ → Na₂CO₃ + H₂O', 'organic', '["CO₂", "NaOH"]', '["Na₂CO₃", "H₂O"]', 'Room temperature', 'Sodium hydroxide reacts with carbon dioxide to form sodium carbonate (washing soda) and water. This reaction explains why sodium hydroxide solutions cannot be stored in open containers - they absorb CO₂ from air and form carbonate.', '[]', 'Used to prepare sodium carbonate. Also explains why NaOH solutions must be stored in airtight containers. Important in the Solvay process.', NULL, '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r63', NULL, '11', 'Preparation of Sodium Peroxide', '2Na + O₂ → Na₂O₂', 'organic', '["Na", "O₂"]', '["Na₂O₂"]', 'Burning in excess air', 'When sodium metal burns in excess air or oxygen, it forms sodium peroxide (Na₂O₂) instead of the oxide. This is different from lithium which forms normal oxide and potassium which forms superoxide. The peroxide ion O₂²⁻ contains an O-O single bond.', '[]', 'Sodium peroxide is used as a bleaching agent, in oxygen masks for submarines and spacecraft, and as an oxidizing agent.', 'Does not occur with limited air (forms Na₂O instead). Fails with lithium (forms Li₂O). Does not occur at room temperature (requires ignition). Potassium forms superoxide (KO₂), not peroxide.', '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r64', NULL, '11', 'Preparation of Sodium Hydroxide (Castner-Kellner)', '2NaCl + 2H₂O → 2NaOH + H₂ + Cl₂ (electrolysis)', 'organic', '["NaCl", "H₂O"]', '["NaOH", "H₂", "Cl₂"]', 'Electrolysis of brine using mercury cathode', 'In the Castner-Kellner process, electrolysis of aqueous NaCl (brine) produces sodium hydroxide, hydrogen gas at the cathode, and chlorine gas at the anode. Mercury acts as a cathode forming sodium amalgam which reacts with water to form NaOH.', '[]', 'Industrial production of caustic soda (NaOH), chlorine gas, and hydrogen. Used in paper, textile, and soap industries.', NULL, '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r65', NULL, '11', 'Reaction of Calcium Carbide with Water', 'CaC₂ + 2H₂O → Ca(OH)₂ + C₂H₂', 'organic', '["CaC₂", "H₂O"]', '["Ca(OH)₂", "C₂H₂"]', 'Room temperature', 'Calcium carbide reacts with water to produce acetylene gas (ethyne) and calcium hydroxide. This is a hydrolysis reaction. The reaction is highly exothermic and acetylene burns with a sooty flame due to high carbon content.', '[]', 'Laboratory preparation of acetylene. Calcium carbide is used in carbide lamps and as a ripening agent for fruits. Acetylene is used in oxy-acetylene torches.', NULL, '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r66', NULL, '11', 'Plaster of Paris Setting', 'CaSO₄·½H₂O + 1½H₂O → CaSO₄·2H₂O', 'organic', '["CaSO₄·½H₂O", "H₂O"]', '["CaSO₄·2H₂O"]', 'Mixing with water', 'When plaster of Paris (calcium sulfate hemihydrate) is mixed with water, it hardens to form gypsum (calcium sulfate dihydrate). The setting process involves interlocking of crystals and slight expansion, making it useful for casts.', '[]', 'Used for making toys, statues, casts for sealing broken limbs, and in dentistry for making molds.', NULL, '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r67', NULL, '11', 'Hydrolysis of Boron Trifluoride', 'BF₃ + 3H₂O → H₃BO₃ + 3HF', 'organic', '["BF₃", "H₂O"]', '["H₃BO₃", "HF"]', 'Room temperature', 'Boron trifluoride undergoes hydrolysis to form boric acid and hydrogen fluoride. BF₃ is an electron-deficient compound and acts as a Lewis acid, accepting electron pairs from water molecules.', '[]', 'Demonstrates Lewis acid behavior of BF₃. Used in organic synthesis as a catalyst.', NULL, '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r68', NULL, '11', 'Reaction of Aluminum with Sodium Hydroxide', '2Al + 2NaOH + 2H₂O → 2NaAlO₂ + 3H₂', 'organic', '["Al", "NaOH", "H₂O"]', '["NaAlO₂", "H₂"]', 'Room temperature', 'Aluminum reacts with aqueous sodium hydroxide to form sodium meta-aluminate and hydrogen gas. The protective oxide layer on aluminum dissolves in NaOH, allowing the metal to react. This shows the amphoteric nature of aluminum.', '[]', 'Used to demonstrate amphoteric nature of aluminum. Used in drain cleaners and in the production of hydrogen.', NULL, '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r69', NULL, '11', 'Preparation of Silicones (Hydrolysis of Alkyl Chlorosilanes)', 'nR₂SiCl₂ + nH₂O → (R₂SiO)n + 2nHCl', 'organic', '["R₂SiCl₂", "H₂O"]', '["(R₂SiO)n", "HCl"]', 'Hydrolysis followed by polymerization', 'Dialkyldichlorosilanes undergo hydrolysis to form silanols which condense to form silicones (polysiloxanes). The Si-O-Si linkage gives silicones their unique properties like thermal stability and water repellency.', '[]', 'Silicones are used as lubricants, sealants, medical implants, water-repellent coatings, and in cosmetics.', NULL, '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r7', NULL, '12', 'Reimer-Tiemann Reaction', 'C₆H₅OH + CHCl₃ + NaOH → 2-HOC₆H₄CHO + NaCl + H₂O', 'organic', '["C₆H₅OH", "CHCl₃", "NaOH"]', '["C₆H₄OHCHO", "NaCl"]', 'NaOH (aq), CHCl₃, heat', 'NaOH deprotonates CHCl₃ to form a highly reactive dichlorocarbene (:CCl₂). The phenoxide ion (from phenol + NaOH) acts as a nucleophile and attacks the carbene at the ortho position. After hydrolysis of the intermediate, an aldehyde group (–CHO) is introduced onto the ring.', '[]', 'Classic method to introduce formyl groups onto phenols. Salicylaldehyde (2-hydroxybenzaldehyde) is produced this way — used in perfumes.', 'Does not occur with aniline (different products form). Fails with p-nitrophenol (electron-withdrawing group inhibits). Does not work with alcohols (only phenols). Ortho position must be free for reaction to proceed.', '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r70', NULL, '11', 'Haber Process (Ammonia Synthesis)', 'N₂ + 3H₂ ⇌ 2NH₃', 'organic', '["N₂", "H₂"]', '["NH₃"]', '200-300 atm, 450°C, Iron catalyst', 'Nitrogen and hydrogen combine in a reversible exothermic reaction to form ammonia. High pressure favors the forward reaction (Le Chatelier\'s principle). Iron with promoters (Al₂O₃, K₂O) acts as catalyst.', '[]', 'Industrial production of ammonia for fertilizers (urea, ammonium nitrate), nitric acid production, and refrigeration.', 'Does not occur at room temperature (kinetically hindered). Fails without catalyst (practically no reaction). Does not proceed at atmospheric pressure (poor yield). Impurities (CO, H₂O) poison the catalyst.', '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r71', NULL, '11', 'Ostwald Process (Nitric Acid Production)', '4NH₃ + 5O₂ → 4NO + 6H₂O (Pt catalyst)', 'organic', '["NH₃", "O₂"]', '["NO", "H₂O"]', '850-900°C, Pt-Rh catalyst', 'Ammonia is catalytically oxidized to nitric oxide using platinum-rhodium catalyst at high temperature. NO is further oxidized to NO₂ and absorbed in water to form HNO₃. This is the basis of nitric acid manufacture.', '[]', 'Industrial production of nitric acid for fertilizers, explosives (TNT, nitroglycerin), and dyes.', NULL, '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r72', NULL, '11', 'Contact Process (Sulfuric Acid Production)', '2SO₂ + O₂ ⇌ 2SO₃', 'organic', '["SO₂", "O₂"]', '["SO₃"]', '450°C, 1-2 atm, V₂O₅ catalyst', 'Sulfur dioxide is oxidized to sulfur trioxide using vanadium pentoxide catalyst. This is a reversible exothermic reaction. Lower temperature favors higher yield but V₂O₅ works best at 450°C (compromise temperature).', '[]', 'Industrial production of sulfuric acid - the most important industrial chemical used in fertilizers, dyes, detergents, and petroleum refining.', NULL, '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r73', NULL, '11', 'Preparation of Chlorine (Deacon\'s Process)', '4HCl + O₂ → 2Cl₂ + 2H₂O', 'organic', '["HCl", "O₂"]', '["Cl₂", "H₂O"]', '400-450°C, CuCl₂ catalyst', 'Hydrogen chloride is oxidized by oxygen in the presence of CuCl₂ catalyst to produce chlorine gas and water. This is an older process now largely replaced by electrolysis but still important.', '[]', 'Production of chlorine gas for bleaching, water treatment, and PVC manufacture.', NULL, '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r74', NULL, '11', 'Reaction of Chlorine with Cold Dilute NaOH', 'Cl₂ + 2NaOH → NaCl + NaClO + H₂O', 'organic', '["Cl₂", "NaOH"]', '["NaCl", "NaClO", "H₂O"]', 'Cold dilute alkali', 'Chlorine undergoes disproportionation in cold dilute sodium hydroxide to form sodium chloride and sodium hypochlorite. This is a comproportionation-disproportionation reaction where chlorine is both oxidized and reduced.', '[]', 'Used to manufacture bleaching powder and bleach solutions. Sodium hypochlorite is used as a disinfectant and bleaching agent.', 'Does not occur with hot concentrated NaOH (forms chlorate). Fails with fluorine (different products). Does not occur in acidic medium (Cl₂ + H₂O reaction). Requires cold conditions - warm conditions favor chlorate formation.', '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r75', NULL, '11', 'Reaction of Chlorine with Hot Concentrated NaOH', '3Cl₂ + 6NaOH → 5NaCl + NaClO₃ + 3H₂O', 'organic', '["Cl₂", "NaOH"]', '["NaCl", "NaClO₃", "H₂O"]', 'Hot concentrated alkali (>70°C)', 'With hot concentrated sodium hydroxide, chlorine disproportionates to form sodium chloride and sodium chlorate instead of hypochlorite. The higher temperature favors the formation of chlorate over hypochlorite.', '[]', 'Used to produce sodium chlorate, which is used in matches, explosives, and as a herbicide.', NULL, '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r76', NULL, '11', 'Preparation of Hydrogen Chloride (Direct Synthesis)', 'H₂ + Cl₂ → 2HCl', 'organic', '["H₂", "Cl₂"]', '["HCl"]', 'Burning in UV light or heat', 'Hydrogen burns in chlorine to form hydrogen chloride gas. The reaction is explosive when initiated by light or heat. HCl dissolves in water to form hydrochloric acid. This is a chain reaction.', '[]', 'Industrial production of HCl for pickling steel, production of chlorides, and as a laboratory reagent.', NULL, '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r77', NULL, '11', 'Preparation of Xenon Fluorides', 'Xe + F₂ → XeF₂ (1:1 ratio)', 'organic', '["Xe", "F₂"]', '["XeF₂"]', '400°C, 1 atm, Ni or Monel vessel', 'Xenon reacts with fluorine to form xenon fluorides. Different products (XeF₂, XeF₄, XeF₆) are obtained by varying the ratio of reactants and conditions. This demonstrates that noble gases can form compounds.', '[]', 'XeF₂ is used as a fluorinating agent in organic chemistry. Xenon compounds are used in specialized lasers and as oxidizing agents.', NULL, '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r78', NULL, '11', 'Hydrolysis of Xenon Tetrafluoride', '6XeF₄ + 12H₂O → 4XeO₃ + 2Xe + 24HF + 3O₂', 'organic', '["XeF₄", "H₂O"]', '["XeO₃", "Xe", "HF", "O₂"]', 'Room temperature', 'Xenon tetrafluoride undergoes hydrolysis to form xenon trioxide, xenon gas, hydrogen fluoride, and oxygen. This is a complex disproportionation reaction where xenon is both oxidized and reduced.', '[]', 'Demonstrates the reactivity of noble gas compounds. Xenon trioxide is a powerful explosive.', NULL, '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r79', NULL, '11', 'Preparation of Potassium Dichromate from Chromite Ore', '4FeCr₂O₄ + 8Na₂CO₃ + 7O₂ → 8Na₂CrO₄ + 2Fe₂O₃ + 8CO₂', 'organic', '["FeCr₂O₄", "Na₂CO₃", "O₂"]', '["Na₂CrO₄", "Fe₂O₃", "CO₂"]', 'Fusion at high temperature', 'Chromite ore is fused with sodium carbonate in the presence of air to convert chromium(III) to sodium chromate. The product is leached with water and acidified to form sodium dichromate, which is then converted to potassium dichromate using KCl.', '[]', 'Potassium dichromate is used as an oxidizing agent in organic chemistry, in volumetric analysis, and in chrome tanning.', NULL, '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r8', NULL, '12', 'Kolbe\'s Reaction', 'C₆H₅ONa + CO₂ → C₆H₄(OH)COONa → C₆H₄(OH)COOH', 'organic', '["C₆H₅OH", "CO₂", "NaOH"]', '["C₆H₄OHCOOH"]', 'CO₂ under pressure, 125°C, then H⁺', 'Sodium phenoxide is heated with CO₂ under pressure. CO₂, being electrophilic, attacks the ortho position of the phenoxide ring. After acidification, salicylic acid (2-hydroxybenzoic acid) is obtained. This is a classic electrophilic substitution on a phenoxide anion.', '[]', 'Industrial synthesis of salicylic acid, the precursor to aspirin (acetylsalicylic acid).', 'Does not occur at atmospheric pressure (requires 4-7 atm). Fails with cresols (substituted phenols give mixtures). Does not work with alcohols. Requires high temperature (125°C) - fails at room temperature.', '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r80', NULL, '11', 'Reaction of Potassium Permanganate with Oxalic Acid', '2KMnO₄ + 5H₂C₂O₄ + 3H₂SO₄ → 2MnSO₄ + 10CO₂ + K₂SO₄ + 8H₂O', 'organic', '["KMnO₄", "H₂C₂O₄", "H₂SO₄"]', '["MnSO₄", "CO₂", "K₂SO₄", "H₂O"]', 'Room temperature, acidic medium', 'Potassium permanganate oxidizes oxalic acid to carbon dioxide in acidic medium, while itself getting reduced to manganese(II) sulfate. The purple color of KMnO₄ disappears as the reaction proceeds. This is an autocatalytic reaction (Mn²⁺ catalyzes it).', '[]', 'Used in volumetric analysis for estimating oxalates and iron(II) salts. Demonstrates redox titration.', 'Does not occur in alkaline medium (different products - MnO₂). Fails without acid (H₂SO₄ required). Does not occur with HCl (KMnO₄ oxidizes HCl). Requires heating initially - very slow at room temperature until Mn²⁺ builds up.', '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r81', NULL, '11', 'Preparation of Potassium Permanganate from Pyrolusite', '2MnO₂ + 4KOH + O₂ → 2K₂MnO₄ + 2H₂O', 'organic', '["MnO₂", "KOH", "O₂"]', '["K₂MnO₄", "H₂O"]', 'Fusion at high temperature (green color)', 'Pyrolusite (MnO₂) is fused with KOH in presence of oxidizing agent (O₂ or KNO₃) to form potassium manganate (green). This is then electrolytically oxidized or treated with Cl₂ to form potassium permanganate (purple).', '[]', 'Industrial preparation of KMnO₄, a powerful oxidizing agent used in water treatment, disinfection, and organic synthesis.', NULL, '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r82', NULL, '11', 'Reaction of Copper with Concentrated Nitric Acid', 'Cu + 4HNO₃ → Cu(NO₃)₂ + 2NO₂ + 2H₂O', 'organic', '["Cu", "HNO₃"]', '["Cu(NO₃)₂", "NO₂", "H₂O"]', 'Concentrated acid', 'Copper reacts with concentrated nitric acid to form copper nitrate, nitrogen dioxide (brown gas), and water. The brown fumes of NO₂ are characteristic. Concentrated HNO₃ acts as an oxidizing agent.', '[]', 'Laboratory preparation of nitrogen dioxide. Demonstrates the oxidizing nature of concentrated nitric acid.', 'Does not occur with dilute HNO₃ (produces NO instead of NO₂). Fails with very dilute acid (reaction stops). Does not occur with gold or platinum (noble metals). Passivated with concentrated HNO₃ if iron/aluminum.', '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r83', NULL, '11', 'Reaction of Copper with Dilute Nitric Acid', '3Cu + 8HNO₃ → 3Cu(NO₃)₂ + 2NO + 4H₂O', 'organic', '["Cu", "HNO₃"]', '["Cu(NO₃)₂", "NO", "H₂O"]', 'Dilute acid', 'With dilute nitric acid, copper forms copper nitrate and nitric oxide (colorless gas) which turns brown in air due to oxidation to NO₂. This shows the concentration-dependent behavior of nitric acid.', '[]', 'Laboratory preparation of nitric oxide. Used in qualitative analysis.', NULL, '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r84', NULL, '11', 'Reaction of Silver Nitrate with Sodium Thiosulfate', 'AgNO₃ + 2Na₂S₂O₃ → Na₃[Ag(S₂O₃)₂] + NaNO₃', 'organic', '["AgNO₃", "Na₂S₂O₃"]', '["Na₃[Ag(S₂O₃)₂]", "NaNO₃"]', 'Aqueous solution', 'Silver nitrate reacts with excess sodium thiosulfate to form a soluble complex salt sodium dithiosulfatoargentate(I). Initially a white precipitate of Ag₂S₂O₃ forms which dissolves in excess thiosulfate.', '[]', 'Used in photography as a fixing agent to remove unexposed AgBr. Demonstrates complex formation.', NULL, '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r85', NULL, '11', 'Preparation of Tetraamminecopper(II) Sulfate', 'CuSO₄ + 4NH₃ → [Cu(NH₃)₄]SO₄', 'organic', '["CuSO₄", "NH₃"]', '["[Cu(NH₃)₄]SO₄"]', 'Aqueous ammonia', 'Copper sulfate reacts with excess ammonia to form the deep blue complex tetraamminecopper(II) sulfate. The pale blue precipitate of Cu(OH)₂ first formed dissolves in excess ammonia to give the complex.', '[]', 'Used in qualitative analysis to detect copper ions. Demonstrates complex ion formation and color changes.', NULL, '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r86', NULL, '11', 'Preparation of Potassium Ferrocyanide', 'Fe + 6NH₄CN + K₂CO₃ → K₄[Fe(CN)₆] + 2NH₃ + 2CO₂ + 4NH₄⁺', 'organic', '["Fe", "NH₄CN", "K₂CO₃"]', '["K₄[Fe(CN)₆]", "NH₃", "CO₂"]', 'Fusion process', 'Iron filings are fused with potassium carbonate and nitrogenous organic matter to produce potassium ferrocyanide (yellow prussiate). This is a coordination compound with Fe in +2 oxidation state surrounded by six cyanide ligands.', '[]', 'Used to detect Fe³⁺ ions (gives Prussian blue). Used in blueprint paper and as an antidote for heavy metal poisoning.', NULL, '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r87', NULL, '11', 'Test for Fe³⁺ with Potassium Thiocyanate', 'FeCl₃ + KSCN → [Fe(SCN)]Cl₂ + KCl', 'organic', '["FeCl₃", "KSCN"]', '["[Fe(SCN)]Cl₂", "KCl"]', 'Aqueous solution', 'Ferric chloride reacts with potassium thiocyanate to form blood-red colored complex pentaaquathiocyanatoiron(III) chloride. The intense red color is characteristic of Fe³⁺ and used for its detection.', '[]', 'Sensitive test for ferric ions. Used in qualitative analysis. The color intensity can be used for colorimetric estimation of iron.', NULL, '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r88', NULL, '11', 'Bleaching Action of Sulfur Dioxide', 'SO₂ + H₂O ⇌ H₂SO₃ → H₂SO₄ + 2H (reduction)', 'organic', '["SO₂", "H₂O"]', '["H₂SO₃"]', 'Moist conditions', 'Sulfur dioxide bleaches by reduction. It removes oxygen from colored substances, making them colorless. The bleaching is temporary as atmospheric oxygen can reoxidize the substance. This is different from chlorine bleaching (oxidation).', '[]', 'Used for bleaching wool, silk, and straw. Used as a preservative for dried fruits and jams.', NULL, '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r89', NULL, '11', 'Ring Test for Nitrate Ion', 'NO₃⁻ + 3Fe²⁺ + 4H⁺ → NO + 3Fe³⁺ + 2H₂O, then Fe²⁺ + NO → [Fe(NO)]²⁺', 'organic', '["NO₃⁻", "FeSO₄", "H₂SO₄"]', '["[Fe(NO)]SO₄"]', 'Concentrated H₂SO₄ added slowly', 'Nitrate is reduced to nitric oxide by Fe²⁺ in acidic medium. NO forms a brown ring complex with Fe²⁺ at the junction of the two liquids. This is the confirmatory test for nitrate ions.', '[]', 'Confirmatory test for nitrate ions in qualitative analysis. Used in water quality testing.', NULL, '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r9', NULL, '12', 'Fries Rearrangement', 'Phenyl acetate → o-/p-Hydroxyacetophenone (AlCl₃, heat)', 'organic', '["C₆H₅OH", "CH₃COCl", "AlCl₃"]', '["HOC₆H₄COCH₃"]', 'AlCl₃, heat', 'Phenyl esters rearrange in the presence of AlCl₃ to hydroxyaryl ketones. The ester is converted to an acylium–AlCl₃ complex, which then undergoes intramolecular electrophilic attack on the phenyl ring at ortho or para positions. The product is a hydroxy ketone.', '[]', 'Synthesis of hydroxyaryl ketones used in flavours, pharmaceuticals, and sunscreen molecules.', 'Does not occur with phenyl ethers (no ester group). Fails without Lewis acid catalyst. Does not work with aryl esters having electron-withdrawing groups. Low temperature favors para product, high temperature ortho - wrong conditions give poor yields.', '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r90', NULL, '11', 'Chromyl Chloride Test for Chloride', 'K₂Cr₂O₇ + 4NaCl + 6H₂SO₄ → 2CrO₂Cl₂ + 2KHSO₄ + 4NaHSO₄ + 3H₂O', 'organic', '["K₂Cr₂O₇", "NaCl", "H₂SO₄"]', '["CrO₂Cl₂", "KHSO₄", "NaHSO₄", "H₂O"]', 'Heat with concentrated H₂SO₄', 'When a solid chloride is heated with potassium dichromate and concentrated sulfuric acid, red vapors of chromyl chloride (CrO₂Cl₂) are evolved. This is a confirmatory test for chloride ions in qualitative analysis.', '[]', 'Confirmatory test for chloride ions. Distinguishes chloride from other halides.', NULL, '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r91', NULL, '12', 'Wolff-Kishner Reduction', 'C₆H₅CHO + NH₂NH₂ → C₆H₅CH=NNH₂ → C₆H₅CH₃ + N₂ (KOH, heat)', 'organic', '["C₆H₅CHO", "NH₂NH₂", "KOH"]', '["C₆H₅CH₃", "N₂", "H₂O"]', 'Hydrazine, KOH, heat (150-200°C)', 'Aldehydes and ketones are reduced to alkanes by heating with hydrazine hydrate and strong base (KOH/NaOH) in ethylene glycol. The carbonyl group is converted to CH₂. This is an alternative to Clemmensen reduction for base-stable compounds.', '[]', 'Reduction of carbonyl compounds to hydrocarbons. Preferred over Clemmensen for acid-sensitive compounds.', 'Does not occur with base-sensitive functional groups (esters, lactones). Fails without strong base (KOH/NaOH required). Does not work at low temperature (requires 150-200°C). Acidic conditions prevent reaction.', '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r92', NULL, '12', 'Stephen Reaction (Nitrile to Aldehyde)', 'CH₃CN + SnCl₂ + 2HCl → CH₃CH=NH·HCl → CH₃CHO + NH₄Cl (Hydrolysis)', 'organic', '["CH₃CN", "SnCl₂", "HCl"]', '["CH₃CHO", "NH₄Cl", "SnCl₄"]', 'SnCl₂/HCl then H₂O', 'Nitriles are reduced to imines using stannous chloride in HCl, which are then hydrolyzed to aldehydes. This is a selective reduction that stops at the aldehyde stage without further reduction to alcohol.', '[]', 'Preparation of aldehydes from nitriles. Used when aldehydes cannot be prepared by other methods.', NULL, '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r93', NULL, '12', 'Hell-Volhard-Zelinsky Reaction', 'CH₃CH₂COOH + Br₂ → CH₃CHBrCOOH + HBr (red P)', 'organic', '["CH₃CH₂COOH", "Br₂", "P"]', '["CH₃CHBrCOOH", "HBr"]', 'Br₂, red phosphorus', 'Carboxylic acids with α-hydrogen atoms undergo halogenation at the α-position when treated with chlorine or bromine in the presence of red phosphorus. The reaction proceeds via the acid bromide intermediate.', '[]', 'Synthesis of α-halo acids which are important intermediates in organic synthesis. Used to prepare α-amino acids.', 'Does not occur with acids having no α-hydrogen (trimethylacetic acid). Fails without red phosphorus catalyst. Does not work with iodine (HI is strong reducing agent). Aromatic acids react slowly or not at all.', '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r94', NULL, '12', 'Decarboxylation of Carboxylic Acids', 'CH₃COONa + NaOH → CH₄ + Na₂CO₃ (CaO, heat)', 'organic', '["CH₃COOH", "NaOH", "CaO"]', '["CH₄", "Na₂CO₃"]', 'Soda lime (NaOH + CaO), heat', 'Sodium salts of carboxylic acids lose CO₂ when heated with soda lime to form alkanes with one carbon less. CaO prevents NaOH from attacking glass and keeps it dry.', '[]', 'Preparation of alkanes from carboxylic acids. Used to descend the homologous series.', NULL, '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r95', NULL, '12', 'HVZ Reaction with Acetic Acid', 'CH₃COOH + Cl₂ → ClCH₂COOH + HCl (red P)', 'organic', '["CH₃COOH", "Cl₂", "P"]', '["ClCH₂COOH", "HCl"]', 'Cl₂, red phosphorus', 'Acetic acid undergoes α-chlorination to form chloroacetic acid. The reaction can continue to give dichloroacetic acid and trichloroacetic acid with excess chlorine.', '[]', 'Preparation of chloroacetic acid used in the synthesis of herbicides, dyes, and pharmaceuticals.', NULL, '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r96', NULL, '12', 'Reimer-Tiemann Reaction', 'C₆H₅OH + CHCl₃ + 3NaOH → o-HOC₆H₄CHO + 3NaCl + 2H₂O', 'organic', '["C₆H₅OH", "CHCl₃", "NaOH"]', '["o-HOC₆H₄CHO", "NaCl", "H₂O"]', 'CHCl₃, aqueous NaOH, 340K', 'Phenol reacts with chloroform and aqueous sodium hydroxide to form o-hydroxybenzaldehyde (salicylaldehyde) as the major product. The reaction involves dichlorocarbene (:CCl₂) intermediate.', '[]', 'Introduction of formyl group (-CHO) at ortho position of phenol. Used to prepare salicylaldehyde.', NULL, '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r97', NULL, '12', 'Kolbe\'s Electrolytic Reaction', '2CH₃COOK → C₂H₆ + 2CO₂ + 2KOH + H₂ (electrolysis)', 'organic', '["CH₃COOK"]', '["C₂H₆", "CO₂", "KOH", "H₂"]', 'Electrolysis of concentrated sodium/potassium salt of fatty acid', 'Electrolysis of sodium or potassium salt of fatty acids gives alkanes with even number of carbon atoms at the anode. The alkyl radicals couple to form the alkane. CO₂ is evolved and H₂ is formed at cathode.', '[]', 'Preparation of alkanes. Used to prepare symmetrical alkanes with even number of carbons.', NULL, '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r98', NULL, '12', 'Williamson Ether Synthesis', 'C₂H₅ONa + CH₃I → C₂H₅OCH₃ + NaI', 'organic', '["C₂H₅ONa", "CH₃I"]', '["C₂H₅OCH₃", "NaI"]', 'SN2 reaction conditions', 'Sodium alkoxide reacts with alkyl halide to form ether. This is an SN2 reaction where the alkoxide ion acts as a nucleophile. Primary alkyl halides give good yields; tertiary halides undergo elimination.', '[]', 'General method for preparing mixed and symmetrical ethers. Used in pharmaceutical and perfume industries.', 'Does not occur with tertiary alkyl halides (elimination dominates). Fails with aryl halides (C-X bond too strong). Does not work with alcohols instead of alkoxides. Vinyl halides do not react.', '2026-06-05 22:22:41');
INSERT INTO `reactions` (`id`, `chapter_id`, `class_level`, `name`, `equation`, `reaction_type`, `reactants`, `products`, `conditions`, `explanation`, `mechanism`, `applications`, `not_occur`, `created_at`) VALUES ('r99', NULL, '12', 'Coupling Reaction of Phenol with Diazonium Salt', 'C₆H₅OH + C₆H₅N₂⁺Cl⁻ → p-HOC₆H₄N=NC₆H₅ + HCl', 'organic', '["C₆H₅OH", "C₆H₅N₂⁺Cl⁻"]', '["p-HOC₆H₄N=NC₆H₅", "HCl"]', 'Weakly alkaline (pH 9-10), 0-5°C', 'Phenol couples with benzenediazonium chloride in weakly alkaline medium to form p-hydroxyazobenzene (an azo dye). The para position of phenol is activated by the -OH group.', '[]', 'Synthesis of azo dyes. Used in textile dyeing and as indicators.', NULL, '2026-06-05 22:22:41');
